window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-08"]={"block":"med:med-clinica-medica-med-clm-08","label":"MED · MED CLM 08","count":482,"questions":[{"id":"med-clinica-medica-med-clm-08-281090","number":"281090","sourceNumber":"281090","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Acometimento do sistema nervoso central em pacientes portadores do HIV constitui-se\nem importante causa de morbimortalidade. A segunda\ncausa mais comumente associada a lesões\nocupantes de espaço neste grupo de pacientes é:","options":{"A":"Linfoma primário.","B":"Metástases.","C":"Abscesso cerebral piogênico.","D":"Neurotoxoplasmose.","E":"Criptococos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247167","number":"247167","sourceNumber":"247167","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo masculino, 37 anos, é atendido no posto de saúde com um resultado\nde anti-HIV positivo. Em relação à orientação\nterapêutica com base nas novas recomendações da\nOMS (2015), assinale a alternativa CORRETA.","options":{"A":"O início da terapia antirretroviral deve ser postergado até que os níveis de CD4 sejam inferiores\na 200 pelo risco de resistência viral\nrelacionada à exposição prolongada às drogas e seus efeitos\ncolaterais.","B":"O início da terapia antirretroviral deve preferencialmente ser feito com esquema triplo,\nassociando dois inibidores da transcriptase\nreversa nucleosídeos e um inibidor da transcriptase\nreversa não nucleosídeo.","C":"O início dos esquemas de profilaxia primária para as infecções oportunistas deve aguardar uma\nmelhora do sistema imunológico com a terapia antirretroviral.","D":"O paciente não deve receber vacina com vírus atenuado, como as vacinas para gripe A, hepatite\nB e varicela.","E":"Na ocorrência de um primeiro episódio de candidíase oral, está indicada profilaxia secundária\ncom nistatina oral até que os níveis de CD4 sejam\nsuperiores a 350."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-217667","number":"217667","sourceNumber":"217667","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Durante atendimento em Unidade Básica de Saúde, foram admitidas três pessoas, as\nquais procuraram o serviço de saúde para receber a vacina contra a febre amarela. A primeira era\numa gestante com catorze semanas de gestação, que recebera uma dose da vacina contra a febre\namarela em 2007; a segunda era uma idosa de 66 anos de idade, em uso de imunobiológicos para\no tratamento de artrite reumatoide; a terceira era um paciente com diagnóstico de HIV, com exames\nrecentes de carga viral do HIV indetectável e última dosagem de linfócitos T CD4+ de 422\ncélulas/mm³ (24,6%). A respeito da conduta quanto à realização ou não da vacinação contra a\nfebre amarela nesse caso hipotético, assinale a alternativa CORRETA:","options":{"A":"Deve-se vacinar somente a paciente gestante, por ter recebido a última dose da vacina há mais\nde dez anos e ser recomendada a dose de reforço.","B":"Deve-se vacinar somente o paciente com diagnóstico de HIV, por apresentar dosagem de\nlinfócitos T CD4+ recente acima de 350 células/mm³.","C":"Deve-se vacinar somente a paciente idosa com artrite reumatoide que está em uso de\nimunobiológicos, de forma a promover anticorpos protetores em imunossuprimidos.","D":"Devem ser vacinadas a paciente idosa e a gestante, sendo contraindicada a vacinação em\npacientes com HIV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-182675","number":"182675","sourceNumber":"182675","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"É fundamental que os médicos identifiquem manifestações/doenças que poderão\nindicar imunodeficiência moderada em portadores de\nHIV, para que os mesmos possam solicitar a\ntestagem para esse vírus. Segundo o Protocolo Clínico e Diretrizes Terapêuticas para Manejo da\nInfecção pelo HIV em Adultos ? MS ? 2017, todas as situações abaixo podem indicar\nIMUNODEFICIÊNCIA MODERADA em portadores de HIV, EXCETO:","options":{"A":"Perda de peso inexplicável (> 10% do peso corporal).","B":"Diarreia crônica com duração maior que 30 dias.","C":"Febre persistente inexplicada por mais de 1 mês.","D":"Neurotoxoplasmose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-159132","number":"159132","sourceNumber":"159132","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Diante de um paciente portador de HIV/AIDS, em abandono de tratamento que chega\nao pronto atendimento com tosse seca, dispneia\nacentuada e hipoxemia, porém com ausculta\npulmonar normal, DHL 640 UI/L, VHS = 45, Saturação O? 60%, radiografia de tórax: infiltrado\nintersticial bilateral, qual seria a primeira hipótese e qual(is) droga(s) de primeira escolha para\no\ntratamento?","options":{"A":"Tuberculose / Rifampicina, isoniazida, pirazinamida e etambutol.","B":"Pneumocistose / Sulfametoxazol e Trimetoprim.","C":"Histoplasmose / Anfotericina B.","D":"Pneumonia adquirida na comunidade / Azitromicina e ceftriaxona."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-159133","number":"159133","sourceNumber":"159133","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente portador de HIV, virgem de tratamento, assintomático com CD4=22\ncélulas/mm³ e PPD < 5 mmHg, nega contato com\npessoas portadoras de tuberculose bacilífera.\nQual(is) a(s) profilaxia(s) primária(s) é (são) DESNECESSÁRIA(S)?","options":{"A":"Azitromicina para complexo Mycobacterium avium (MAC).","B":"Sulfametoxazol + Trimetoprim para neurotoxoplasmose.","C":"Sulfametoxazol + Trimetoprim para pneumocistose.","D":"Isoniazida para tuberculose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-135991","number":"135991","sourceNumber":"135991","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"João Pedro, 7 meses, veio ao Posto de Saúde do Universitário trazido pela sua genitora\npara consulta de rotina de puericultura, que\nse queixou do aparecimento, na criança, de\nvermelhidão no tronco e coceira. A criança tinha história de desmame precoce, mas apresentava\nbom ganho de peso e de estatura nas últimas consultas, bem como desenvolvimento\naparentemente satisfatório. No prontuário, também não havia internações pregressas. Ao exame, o\nlactente apresentava hiperemia, edema e calor, lesão por escoriação com drenagem de pus. Qual a\nconduta mais recomendada para esse caso?","options":{"A":"Iniciar antibiótico oral com penicilinas ou eritromicina e, após melhora, identificar a doença de\nbase;","B":"Iniciar antibiótico oral e associar permetrina tópica por tratar-se provavelmente de escabiose,\nmoléstia comum na população;","C":"Realizar banhos com permanganatos de potássio e antibiótico tópico;","D":"Nenhuma das anteriores."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-108653","number":"108653","sourceNumber":"108653","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de cinco anos de idade, do sexo feminino, procedente do interior do estado do\nAcre, com história de febre há 4 semanas, prostração e mau estado geral. Encontrava-se irritada\nporém orientada. Ao exame físico: face pálida 3+/4+, precórdio hiperdinâmico com íctus propulsivo\nno 4º e 5º espaço intercostal, de duas polpas digitais, próximo ao mamilo esquerdo. Ausculta\ncardíaca: ritmo cardíaco em três tempos com sopro sistólico 3+/6+ audível na borda esternal\nesquerda baixa na região tricúspide e mitral, irradiado à fossa axilar esquerda. Frequência\ncardíaca:\n125 bpm em repouso. Saturação: 95% em ar ambiente. Frequência respiratória: 55 irpm. Abdome\ndoloroso, porém sem sinais de irritação peritoneal. Fígado palpável a 5 cm do rebordo costal\ndireito.\nGenitália feminina sem alterações. Pulsos presentes e simétricos nas quatro extremidades.\n\nMembros: hemiplegia esquerda com evolução de aproximadamente duas semanas. Assinale a\nalternativa que mais explica os sintomas e sinais da paciente:","options":{"A":"Endocardite infecciosa.","B":"Cardite reumática.","C":"Acidente vascular cerebral.","D":"Lúpus eritematoso sistêmico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-84512","number":"84512","sourceNumber":"84512","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São medicações de primeira escolha para o tratamento da Cistite bacteriana, EXCETO:","options":{"A":"Fosfomicina.","B":"Nitrofurantoína.","C":"Sulfametoxazol + trimetropim.","D":"Ciprofloxacina.","E":"Pivmecillinam."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-66919","number":"66919","sourceNumber":"66919","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 20 anos, do sexo feminino, sem antecedentes patológicos, apresenta um\nquadro de cistite não complicada. Durante sua consulta, explica ao médico do PSF que gostaria de\num tratamento em dose única. Neste caso, qual o tratamento de primeira eleição?","options":{"A":"Pefloxacino 800 mg VO dose única;","B":"Ciprofloxacino 1 g dose única;","C":"Fosfomicinatrometamol 3 g VO dose única;","D":"Nenhuma das acima está correta."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-66943","number":"66943","sourceNumber":"66943","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 48 anos de idade, tetraplégico após trauma raquimedular por acidente\nautomobilístico, encontra-se em acompanhamento domiciliar pelo médico de família. Faz uso de\ncateter vesical de demora com coletor fechado. O cuidador observou que a urina estava turva e a\nfamília pede que o médico solicite um exame de urina. A amostra foi colhida adequadamente, com\nos seguintes resultados positivos: uroanálise - aspecto turvo, leucócitos = 280.000/ml (normal\n10.000/ml); Cultura de urina - Klebsiella pneumoniae > 100.000 UFC/ml; Sensível a norfloxacino,\nciprofloxacina, aztreonam, gentamicina, amicacina, ceftriaxona; Resistente à ampicilina,\nnitrofurantoína, sulfametoxazol + trimetoprima. Diante desses achados, a conduta indicada seria:","options":{"A":"Ciprofloxacina por 7 dias e substituição da sonda.","B":"Orientação do paciente, cuidador e familiares.","C":"Norfloxacino profilático, 1 cápsula ao deitar.","D":"Tratamento com cefalexina em doses maiores (1,0 g de 6/6 horas)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-50088","number":"50088","sourceNumber":"50088","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente feminino, 18 anos, indígena, mora em zona rural. Há 2 semanas iniciou\nquadro de febre alta e dor em face anterior\nda coxa direita. Evoluiu com posição antálgica (pernas\nem extensão) e notou tumefação de 1/3 superior da face anterios da coxa direita. Ao exame físico\napresenta massa endurecida nessa topografia, de 10cm, muito dolorosa, sem hiperemia ou\nflutuação local. Qual a hipótese diagnótica?","options":{"A":"Sarcoma de partes moles;","B":"Piomiosite tropical;","C":"Osteomelite;","D":"Tromboflebite;"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-29351","number":"29351","sourceNumber":"29351","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação a profilaxia antibiótica na Endocardite Infecciosa qual o (s) antibiótico (s)\nmais indicado (s) no dia a dia na clínica pediátrica?","options":{"A":"Ceftriaxone dose única IM 1 hora antes do procedimento.","B":"Ceftriaxone dose inicial e 6 horas após procedimento.","C":"Amoxicilina EV, 1 hora antes do procedimento","D":"<P>Amoxicilina 200 mg/Kg VO 1 hora antes do procedimento.</P>","E":"<P>Amoxicilina 50 mg/Kg VO 1 hora antes do procedimento.</P>"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-343161","number":"343161","sourceNumber":"343161","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pessoas com infecção pelo HTLV e assintomáticas com elevada carga pró viral:","options":{"A":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, apresentam expressão de IFN-? mais baixa do\nque de IL- 10.","B":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, não apresentam expressão de IFN-? mais\nelevada do que de IL- 10.","C":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated\nmyelopathy)HAM, apresentam expressão de IFN-? mais elevada do que de IL- 10.","D":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, apresentam expressão de IFN-? mais elevada\ndo que de IL- 100."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-343167","number":"343167","sourceNumber":"343167","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Antes de iniciar a corticoterapia nesses pacientes com HAM mielopatia associada ao\nHTLV-1 (HTLV-1 associated myelopathy), é fundamental realizar avaliação clínica para excluir\noutras comorbidades, de acordo com o item correto :","options":{"A":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e escabiose.","B":"Que não possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e escabiose.","C":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e não a escabiose.","D":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, mas não tuberculose e escabiose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-313469","number":"313469","sourceNumber":"313469","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No Brasil, a distribuição epidemiológica dos coinfectados por coinfecção leishmania-HIV\nacompanha os grupos de risco para transmissão HIV/AIDS, seja por faixa etária ou por sexo .\n\nPodemos determinar como correto que:","options":{"A":"A coinfecção com o HIV induz a uma redução na taxa de letalidade por Leishmaniose Visceral\n(LV) e no número de recidivas da LV em uma\nproporção de aproximadamente o triplo e o quíntuplo,\nrespectivamente, comparando-se aos controles HIV-negativos .","B":"A coinfecção com o HIV induz a um aumento na taxa de letalidade por Leishmaniose Visceral\n(LV) e no número de recidivas da LV em uma\nproporção de aproximadamente o triplo e o quíntuplo,\nrespectivamente, comparando-se aos controles HIV-positivos .","C":"A coinfecção com o HIV induz a um aumento na taxa de letalidade por Leishmaniose Visceral\n(LV) e não no número de recidivas da LV em\numa proporção de aproximadamente o triplo e o\nquíntuplo, respectivamente, comparando-se aos controles HIV- negativos .","D":"A coinfecção com o HIV induz a um aumento na taxa de letalidade por Leishmaniose Visceral\n(LV) e no número de recidivas da LV em uma\nproporção de aproximadamente o triplo e o quíntuplo,\nrespectivamente, comparando-se aos controles HIV-negativos ."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-315207","number":"315207","sourceNumber":"315207","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Que categoria celular do sistema imunológico é a primeira a ser infectada pelo HIV?","options":{"A":"Plasmócitos.","B":"Macrófagos.","C":"Linfócitos T.","D":"Neutrófilos.","E":"Eosinófilos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-280400","number":"280400","sourceNumber":"280400","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As candidíases orofaringea e esofágica são comuns em pacientes com\nimunossupressão pelo HIV, sendo observadas,\ngeralmente, em pacientes com contagem de\nLT-CD4+ inferior a 200 cels/mm, sendo correto que:","options":{"A":"Os sintomas típicos de candidíase esofágica incluem dor retroesternal difusa, disfagia e/ou\nodinofagia, normalmente sem febre.","B":"Os sintomas atípicos de candidíase esofágica incluem dor retroesternal difusa, disfagia e/ou\nodinofagia, normalmente sem febre.","C":"Os sintomas típicos de candidíase esofágica incluem dor retroesternal difusa, disfagia e/ou\nodinofagia, normalmente com febre.","D":"Os sintomas típicos de candidíase esofágica excluem dor retroesternal difusa, disfagia e/ou\nodinofagia, normalmente sem febre."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-279036","number":"279036","sourceNumber":"279036","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O achado de DNA de Toxoplasma gondii mediante técnicas de PCR no LCR apresenta\nsensibilidade moderada (aproximadamente 50%), especificidade elevada (superior a 95%) e valor\npreditivo negativo moderado. Sendo correto que:","options":{"A":"Um teste positivo não confirma a presença de toxoplasmose, mas um teste negativo não exclui o\ndiagnóstico. Se a PCR estiver disponível e não existirem contraindicações para realizar punção\nliquórica, o teste pode ser solicitado.","B":"Um teste positivo confirma a presença de toxoplasmose, mas um teste negativo exclui o\ndiagnóstico. Se a PCR estiver disponível e não existirem contraindicações para realizar punção\nliquórica, o teste pode ser solicitado.","C":"Um teste positivo confirma a presença de toxoplasmose, mas um teste negativo não exclui o\ndiagnóstico. Se a PCR estiver disponível e existirem contraindicações para realizar punção\nliquórica, o teste pode ser solicitado mesmo assim.","D":"Um teste positivo confirma a presença de toxoplasmose, mas um teste negativo não exclui o\ndiagnóstico. Se a PCR estiver disponível e não existirem contraindicações para realizar punção\nliquórica, o teste pode ser solicitado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-280408","number":"280408","sourceNumber":"280408","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O Citomegalovirus (CMV), assim como outros vírus da família herpes vírus, permanece\nem estado latente após a infecção primária.\nPodemos indicar como correto que:","options":{"A":"No contexto da infecção pelo HIV, o risco de inativação da doença se eleva quando o LT-CD4+\nse reduz a menos de 100 céls/mm³.","B":"No contexto da infecção pelo HIV, o risco de reativação da doença se reduz quando o LT-CD4+\nse reduz a menos de 100 céls/mm³.","C":"No contexto da infecção pelo HIV, o risco de reativação da doença se eleva quando o LT-CD4+\nse reduz a menos de 100 céls/mm³.","D":"No contexto da infecção pelo HIV, o risco de reativação da doença se eleva quando o LT-CD4+\nse reduz a mais de 100 céls/mm³."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-278667","number":"278667","sourceNumber":"278667","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A discussão sobre gerenciamento de risco deve levar em consideração a experiência\ndo(a) usuário(a) com outros métodos de prevenção\npara Profilaxia Pré-Exposição (PrEP) de Risco\nà Infecção pelo HIV. Podemos apenas aceitar que:","options":{"A":"Cabe destacar que a gestão de risco desconsidera o princípio de que as pessoas são\nautônomas e capazes de fazer escolhas no seu\nmelhor interesse, se tiverem todas as informações\nnecessárias para reduzir seu risco de infecção pelo HIV.","B":"Cabe destacar que a gestão de risco considera o princípio de que as pessoas não são\nautônomas e capazes de fazer escolhas no seu\nmelhor interesse, se tiverem todas as informações\nnecessárias para reduzir seu risco de infecção pelo HIV.","C":"Cabe destacar que a gestão de risco considera o princípio de que as pessoas são autônomas e\ncapazes de fazer escolhas no seu melhor interesse, se tiverem todas as informações necessárias\npara aumentar seu risco de infecção pelo HIV.","D":"Cabe destacar que a gestão de risco considera o princípio de que as pessoas são autônomas e\ncapazes de fazer escolhas no seu melhor interesse, se tiverem todas as informações necessárias\npara reduzir seu risco de infecção pelo HIV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-279087","number":"279087","sourceNumber":"279087","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Devem também ser considerados outros indicativos para caracterização indivíduos com\nexposição frequente ao HIV, tais como os listados abaixo, indique o item errado:","options":{"A":"Repetição de práticas sexuais anais e/ou vaginais com penetração com o uso de preservativo.","B":"Frequência das relações sexuais com parcerias eventuais.","C":"Quantidade e diversidade de parcerias sexuais.","D":"Histórico de episódios de Infecções Sexualmente Transmissíveis (IST)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-279088","number":"279088","sourceNumber":"279088","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A abordagem Profilaxia Pré-Exposição (PrEP) de Risco à Infecção pelo HIV reconhece\nque as escolhas são feitas considerando\ndiferentes pertencimentos culturais, inserções\ncomunitárias e histórias de vida, que influenciarão nos modos como os métodos de prevenção são\nadotados ao longo da vida. Assim, podemos concordar com o item:","options":{"A":"A partir do conhecimento das alternativas de prevenção, não se deve conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, conforme suas práticas sexuais.","B":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, independentemente de suas práticas\nsexuais.","C":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, conforme suas práticas sexuais.","D":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, proibindo suas práticas sexuais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-278675","number":"278675","sourceNumber":"278675","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Parcerias sorodiscordantes para o HIV podem ser entendidas como:","options":{"A":"Parceria heterossexual, mas não homossexual na qual uma das pessoas é infectada pelo HIV e\na outra não.","B":"Parceria heterossexual ou homossexual na qual uma das pessoas é infectada pelo HIV e a outra\ntambém.","C":"Parceria heterossexual ou homossexual na qual uma das pessoas é infectada pelo HIV e a outra\nnão.","D":"Parceria homossexual apenas na qual uma das pessoas é infectada pelo HIV e a outra não."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-278676","number":"278676","sourceNumber":"278676","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Além da diversidade inter-subtipo do HIV, diferenças genéticas e antigênicas também\nforam descritas entre linhagens do subtipo B circulantes no Brasil, sendo correto o dado:","options":{"A":"Em nenhuma das áreas do Brasil, a variante B mostrou-se altamente prevalente,\ncorrespondendo a 57% dos subtipos B detectados\nem Ribeirão Preto (SP) e 37% dos detectados\nno Rio de Janeiro (RJ).","B":"Em algumas áreas do Brasil, a variante B nunca se mostrou altamente prevalente,\ncorrespondendo a 57% dos subtipos B detectados\nem Ribeirão Preto (SP) e 37% dos detectados\nno Rio de Janeiro (RJ).","C":"Em algumas áreas do Brasil, a variante B mostrou-se altamente prevalente, correspondendo a\n57% dos subtipos B detectados em Ribeirão Preto (SP) e 37% dos detectados no Rio de Janeiro\n(RJ).","D":"Em algumas áreas do Brasil, a variante B mostrou-se nenhuma prevalência, correspondendo a\n57% dos subtipos B detectados em Ribeirão Preto (SP) e 37% dos detectados no Rio de Janeiro\n(RJ)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249379","number":"249379","sourceNumber":"249379","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A pesquisa direta do agente oportunista em amostras de escarro espontâneo ou\ninduzido geralmente é pouco sensível para\npneumocistose (PCP). Podemos apenas concordar que:","options":{"A":"O diagnóstico definitivo não é realizado pela identificação do agente por meio das colorações de\nazul de toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes\nrespiratórios.","B":"O diagnóstico definitivo é realizado pela identificação do agente por meio das colorações de azul\nde toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes fora do\nsistema respiratório.","C":"O diagnóstico definitivo é realizado pela identificação do agente por meio das colorações de azul\nde toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes respiratórios.","D":"O diagnóstico definitivo é realizado sem a identificação do agente por meio das colorações de\nazul de toluidina, a partir de espécimes respiratórios."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249283","number":"249283","sourceNumber":"249283","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As estratégias para testagem têm o objetivo de melhorar a qualidade do diagnóstico da\ninfecção pelo HIV e, ao mesmo tempo, assegurar que o diagnóstico seja realizado o mais\nprecocemente possível, de forma segura e com rápida conclusão. Somente se mostra errado o\nitem:","options":{"A":"Fazer revisão e documentação do primeiro exame anti-HIV.","B":"Checar se há contagens de LT-CD4+ e exames de CV-HIV anteriores.","C":"Discutir uso de ARV e se houve eventos adversos prévio.","D":"Vedado discutir o tempo provável de soro positividade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249383","number":"249383","sourceNumber":"249383","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na pneumonia por Pneumocistose PCP moderada a grave (PaO2 <70MMHG) é\nrecomendado esquemas administrados preferencialmente por via EV. Indique o item com erro:","options":{"A":"A mudança de via de administração de endovenosa para oral deve ser realizada quando ocorrer\nmelhora clínica.","B":"Clindamicina 600mg EV a cada seis ou oito horas + primaquina 15-30mg VO uma vez ao dia é o\nprincipal esquema alternativo em caso de intolerância à sulfa.","C":"O esquema de escolha é a associação SMX-TMP (5mg/kg de TMP) endovenosa a cada seis ou\noito horas. O tempo total de tratamento é de 10 dias.","D":"A associação de corticosteroides ao tratamento de PCP moderada a grave apresentou redução\nimportante na mortalidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249284","number":"249284","sourceNumber":"249284","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um dos objetivos da abordagem inicial de uma pessoa com diagnóstico de infecção\npelo HIV é estabelecer uma relação de\nconfiança e respeito entre esta e a equipe multiprofissional\ndo serviço de saúde. Nesse contexto, o item inadequado é:","options":{"A":"Avaliar falhas e não a adesão e seus motivos.","B":"Verificar possibilidade de resistência(s) viral(is) à TARV e necessidade de troca.","C":"Avaliar e investigar sintomas.","D":"Manejar comorbidades não controladas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249286","number":"249286","sourceNumber":"249286","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O início precoce da terapia está associado à redução da transmissibilidade e da\nmorbimortalidade relacionadas à infecção pelo HIV. TARV para o HIV deve ser instituída\nprontamente. Podemos aceitar o item:","options":{"A":"O tenofovir e a lamivudina são fármacos antirretrovirais com atividade contra o HIV e contra o\nHBV, diminuindo o risco de progressão para cirrose e CHC.","B":"O tenofovir e a lamivudina são fármacos antirretrovirais com atividade contra o HIV e não contra\no HBV, não diminuindo o risco de progressão\npara cirrose e CHC.","C":"O tenofovir e a lamivudina são fármacos antirretrovirais com atividade contra o HBV, diminuindo\no risco de progressão para cirrose e CHC. Sem\ninteração com o HIV.","D":"O tenofovir e a lamivudina são fármacos antirretrovirais sem atividade contra o HIV e contra o\nHBV, não diminuindo o risco de progressão para cirrose e CHC."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249318","number":"249318","sourceNumber":"249318","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As pessoas em uso de PROFILAXIA PRÉ-EXPOSIÇÃO (PrEP) de risco à infecção pelo\nHIV devem ser informadas sobre a possibilidade de eventos adversos decorrentes do uso das\nmedicações. Indique o item com erro:","options":{"A":"Nos ensaios clínicos disponíveis, os eventos adversos foram incomuns e resolveram-se no\nprimeiro mês do uso de PrEP.","B":"O profissional de saúde não deve informar ao usuário os eventos adversos esperados (náusea,\ncefaleia, flatulência e edemas).","C":"Os eventos adversos são transitórios e que há possibilidade de uso de medicação sintomática\npara resolução dos sintomas.","D":"Além disso, os usuários devem ser orientados sobre sinais e sintomas de infecção aguda pelo\nHIV que requeiram avaliação médica imediata."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249320","number":"249320","sourceNumber":"249320","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No momento da decisão de descontinuação da PRÉ-EXPOSIÇÃO (PrEP) de risco à\ninfecção pelo HIV, deve-se documentar o status sorológico da pessoa que estava em uso de PrEP,\na adesão até então, as razões para descontinuidade do medicamento e situações de risco. Indique\no item errado:","options":{"A":"Se a pessoa desejar reiniciar a profilaxia após um período de interrupção, não é necessário\nrealizar novamente a abordagem inicial, verificar\ncritérios de elegibilidade e reintroduzir o\nmedicamento.","B":"Deve-se esclarecer, também, a importância de o usuário utilizar outros métodos preventivos e se\ntestar regularmente para HIV e outras IST.","C":"Possibilidade de retomar o uso da PrEP, caso ainda ocorram ou voltem a ocorrer situações de\nmaior chance de exposição ao HIV ou de utilizar a PEP em situações de exposições pontuais.","D":"A suspensão da PrEP em pessoas com doença hepática pelo HBV pode levar a\ndescompensação hepática e óbito em pacientes cirróticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249322","number":"249322","sourceNumber":"249322","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Estratégias de adesão à PROFILAXIA PRÉ-EXPOSIÇÃO (PrEP) de risco à infecção\npelo HIV, somente não mostra como correto que:","options":{"A":"A adesão aos ARV é fundamental para que a PrEP seja efetiva e eficaz.","B":"A adesão não deve ser abordada em todas as consultas, a partir de uma via de comunicação\nsimples e aberta.","C":"Avaliação da adesão da pessoa em uso da PrEP à tomada da medicação e às demais medidas\nde prevenção do HIV.","D":"Identificação de barreiras e facilitadores da adesão, evitando julgamentos ou juízos de valor."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249449","number":"249449","sourceNumber":"249449","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O cuidado contínuo em HIV pode ser entendido como o processo de atenção aos\nusuários que vivem com HIV, que são entendidos como momentos, sendo que a dita Vinculação\nseria adequadamente determinada pela seguinte alternativa.","options":{"A":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível, mas não desenvolva autonomia para o cuidado\ncontínuo. O desfecho principal para considerar uma PVHIV vinculada é a realização da primeira\nconsulta no serviço de atenção para o qual foi encaminhada e, de preferência, seu início de\ntratamento o mais rápido possível.","B":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível e desenvolva autonomia para o cuidado contínuo.\nO desfecho principal para considerar uma PVHIV vinculada é a realização da primeira consulta no\nserviço de atenção para o qual foi encaminhada e, de preferência, seu início de tratamento sendo\ndesnecessário rapidez.","C":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível e desenvolva autonomia para o cuidado contínuo.\nO desfecho principal para considerar uma PVHIV vinculada é a realização da primeira consulta no\nserviço de atenção para o qual foi encaminhada e, de preferência, seu início de tratamento o mais\nrápido possível.","D":"Processo que consiste direcionamento apenas para encaminhamento de uma pessoa\n\nrecém-diagnosticada com HIV ao serviço de saúde, para que ela realize as primeiras consultas e\nexames o mais brevemente possível e\ndesenvolva autonomia para o cuidado contínuo. O desfecho\nprincipal para considerar uma PVHIV vinculada é a realização da primeira consulta no serviço de\natenção para o qual foi encaminhada e, de preferência, seu início de tratamento o mais rápido\n\npossível."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249269","number":"249269","sourceNumber":"249269","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Indivíduos elegíveis para PROFILAXIA PRÉ-EXPOSIÇÃO (PrEP) de risco à infecção\npelo HIV PrEP apresentam maior risco para a\naquisição de Infecções Sexualmente Transmissíveis -\nIST, uma vez que estas compartilham com o HIV as mesmas vias de transmissão. O item que,\nnesse contexto, mostra erro é:","options":{"A":"Pessoas com IST e infecções não ulcerativas do trato reprodutivo têm um risco aumentado em\ntrês a 10 vezes de se infectar pelo HIV.","B":"Orienta-se realizar a testagem para sífilis, preferencialmente por teste rápido, instituindo-se o\ntratamento quando indicado.","C":"Ocorre incremento de 18 vezes de se infectar quando a doença cursa com úlceras não genitais.","D":"Recomenda-se, também, pesquisa para Chlamydia sp. e gonococo, quando disponível, e\ntratamento quando indicado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249272","number":"249272","sourceNumber":"249272","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O Brasil assumiu o compromisso dos Objetivos de Desenvolvimento do Milênio,\nproposto junto à Organização das Nações\nUnidas (ONU), sendo uma de suas metas combaterem e\nreverterem a tendência atual de propagação do HIV/AIDS. Sendo, entretanto fora desses conceitos,\no seguinte item:","options":{"A":"o país busca, como parte das ações de enfrentamento à epidemia de HIV, atingir a meta\n90-90-90.","B":"que até 2020, 90% das pessoas com HIV sejam diagnosticadas (ampliando o acesso ao\ndiagnóstico do HIV).","C":"Das pessoas com HIV diagnosticadas, 90% estejam em tratamento antirretroviral (ampliando o\nacesso à TARV).","D":"Os compromissos assumidos exijam somente que novas metodologias de cuidado e de gestão\nsejam implantadas, independente de um\ncomprometimento da sociedade para o sucesso e alcance\ndesses propósitos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249273","number":"249273","sourceNumber":"249273","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Seriam fatores que facilitam a adesão antirretroviral ARV na prática clínica dos\nesquemas terapêuticos simplificados, como as doses\nfixas combinadas, que permitam o uso de\ndiferentes medicamentos em um mesmo comprimido, sendo inadequado","options":{"A":"conhecimento e compreensão sobre a enfermidade e o tratamento.","B":"acolhimento e escuta ativa do paciente pela equipe multidisciplinar.","C":"não deve ocorrer o vínculo aos profissionais de saúde, e sim à equipe e ao serviço de saúde.","D":"capacitação adequada da equipe multidisciplinar."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-215506","number":"215506","sourceNumber":"215506","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A ausência desses sinais clínicos pode retardar o diagnóstico da Nefropatia associada\nao HIV. Sendo assim, somente uma alternativa se\nmostra ERRADA:","options":{"A":"Achado comum de proteinúria grave e hipoalbuminemia.","B":"A maioria dos pacientes com nefropatia associada ao HIV NAHIV não apresenta edema\nsignificativo ou hipertensão.","C":"Geralmente, o sedimento urinário contém cilindros hialinos e proteinúria, podendo haver\nleucocitúria e/ou hematúria associadas.","D":"A ultrassonografia do aparelho urinário demonstra rins reduzidos e hiperecogênicos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-215264","number":"215264","sourceNumber":"215264","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A profilaxia das IST não virais está indicada nas situações de exposição com risco de\ntransmissão, independentemente da presença ou gravidade das lesões físicas e idade. O esquema\nde associação de medicamentos para a profilaxia das IST não virais em vítimas de violência sexual\nnão aceita o seguinte conceito:","options":{"A":"Gonorreia, sífilis, infecção por clamídia, tricomoníase e cancroide podem ser prevenidos com o\nuso de medicamentos de reconhecida\neficácia.","B":"Algumas IST virais, como as infecções por HSV e HPV, ainda não possuem profilaxias\nespecíficas.","C":"Diferentemente do que ocorre na profilaxia da infecção pelo HIV, a prevenção das IST não virais\npode ser eventualmente postergada, em função das condições de adesão, mas se recomenda a\nsua realização imediata, sempre que possível.","D":"Deverão receber profilaxia pós-exposição sexual os casos de violência sexual em que ocorra\nexposição crônica e repetida ? situação comum em violência sexual intrafamiliar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-182751","number":"182751","sourceNumber":"182751","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quanto à transmissão do HIV em crianças, pode-se afirmar que:","options":{"A":"Atualmente predomina-se a transmissão pelo sangue e seus produtos contaminados com HIV.","B":"A maioria é infectada pela transmissão materno-infantil, durante a gestação e o parto e por meio\ndo aleitamento.","C":"O convívio social com os pais infectados tem sido causa frequente de transmissão aos filhos.","D":"A transmissão materno-infantil de mãe soropositiva para o HIV ocorre em mais de 90% das\ngestações."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183549","number":"183549","sourceNumber":"183549","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O protocolo Clínico e Diretrizes Terapêuticas para Profilaxia Pós-Exposição (PEP) de\nRisco à Infecção pelo HIV, IST e Hepatites Virais (PCDT-PEP) tem como objetivo normatizar as\nrecomendações para a PEP, incluindo, também, a abordagem em relação às IST e às hepatites\nvirais. Portanto, é CORRETO que","options":{"A":"além de atualizar os esquemas de profilaxia antirretroviral, este PCDTPEP busca a atenção\nintegral à pessoa exposta ao risco das IST, do HIV e não das hepatites virais, considerando a\nincorporação da Profilaxia Pré-Exposição (PrEP) no Sistema Único de Saúde (SUS) e a\nnecessidade de controle desses agravos, inclusive da sífilis, que tem apresentado crescente\nnúmero de casos no país","B":"além de atualizar os esquemas de profilaxia antirretroviral, este PCDTPEP busca a atenção\nintegral à pessoa exposta ao risco das IST, do HIV e das hepatites virais, considerando a\nincorporação da Profilaxia Pré-Exposição (PrEP) no Sistema Único de Saúde (SUS) e a\nnecessidade de controle desses agravos, inclusive da sífilis, que tem apresentado crescente\nnúmero de casos no país.","C":"além de atualizar os esquemas de profilaxia antirretroviral, este PCDTPEP busca a atenção\nintegral à pessoa exposta ao risco das IST, do HIV e das hepatites virais, considerando a\nincorporação da Profilaxia Pré-Exposição (PrEP) no Sistema Único de Saúde (SUS) e a\nnecessidade de controle desses agravos, inclusive da sífilis, que tem apresentado redução do\nnúmero de casos no país.","D":"além de atualizar os esquemas de profilaxia antirretroviral, este PCDTPEP busca a atenção\nbásica à pessoa exposta ao risco das IST, do\nHIV somente, considerando a incorporação da\nProfilaxia Pré-Exposição (PrEP) no Sistema Único de Saúde (SUS) e a necessidade de controle\ndesses agravos, inclusive da sífilis, que tem apresentado crescente número de casos no país."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183580","number":"183580","sourceNumber":"183580","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No atendimento inicial, após a exposição ao HIV, é necessário que o profissional avalie\ncomo, quando e com quem ocorreu a exposição. Didaticamente, perguntas direcionam o\natendimento para decisão da indicação ou não da Profilaxia - PEP. Não sendo parte do processo o\nseguinte item:","options":{"A":"o tipo de material biológico é de risco para transmissão do HIV?","B":"ocorreu exposição sexual criminosa?","C":"o tipo de exposição é de risco para transmissão do HIV?","D":"o tempo transcorrido entre a exposição e o atendimento é menor que 72 horas?"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183051","number":"183051","sourceNumber":"183051","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Profilaxia Pré-Exposição ao HIV (PrEP) consiste no uso de antirretrovirais (ARV) para\nreduzir o risco de adquirir a infecção pelo HIV. Sendo INCORRETO, apenas, que","options":{"A":"a eficácia e a segurança da PrEP já foram demonstradas em diversos estudos clínicos e\nsubpopulações, e sua efetividade foi evidenciada em estudos de demonstração.","B":"em estudo que avaliou a PrEP oral diária em homens que fazem sexo com homens e mulheres\ntrans, houve redução de 44% no risco de\naquisição de HIV com o uso diário de comprimido único\nde entricitabina (FTC) combinada ao fumarato de tenofovir desoproxila (TDF).","C":"A eficácia da profilaxia foi fracamente associada à adesão: em participantes com níveis\nsanguíneos detectáveis da medicação, a redução da incidência do HIV foi de 95%.","D":"Entre indivíduos heterossexuais, a eficácia geral da PrEP foi de 62%, sendo de 49% entre as\nmulheres e 80% entre os homens incluídos no estudo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-181402","number":"181402","sourceNumber":"181402","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Cláudio, primeiro filho de mãe soropositivo para HIV, tem 2 meses e desde o\nnascimento fora diagnosticado como portador\ndo vírus da genitora. Logo ao nascer, recebeu\nprofilaxia com zidovudina, por 4 semanas, bem como três doses de nevirapina. No momento, está\nem uso de sulfametoxazol e trimetoprim. Para o seu diagnóstico de infecção por HIV por testes\nmoleculares, há a necessidade de: I. Realizar pelo menos 3 (três) exames de carga viral. Se a\nprimeira carga viral tiver resultado acima de 5.000 cópias/ml, já se considera infecção; II.\nRealizar\nnova coleta após 15 dias da primeira, caso o resultado da primeira carga viral seja detectável até\n\n5.000 cópias/ml; III. Avaliar o contexto clínico, podendo ser solicitado o teste DNA pró-viral e\ncontagem de linfócitos T CD4+, caso ocorram dois resultados consecutivos de carga viral de até\n\n5.000 cópias/ml.","options":{"A":"II.","B":"III.","C":"I e II.","D":"I e III.","E":"I, II e III."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183072","number":"183072","sourceNumber":"183072","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Determinados segmentos populacionais, devido a vulnerabilidades específicas, estão\nsob maior risco de se infectar pelo HIV, em\ndiferentes contextos sociais e tipos de epidemia.\n\nMarque o dado INCORRETO.","options":{"A":"Essas populações, por estarem sob maior risco, devem ser alvo prioritário para o uso de\nProfilaxia Pré-Exposição ao HIV (PrEP) .","B":"No Brasil, a prevalência da infecção pelo HIV, na população geral, encontra-se em 4%, enquanto\nalguns segmentos populacionais demonstram prevalências de HIV mais elevadas.","C":"Esses subgrupos populacionais são gays, pessoas que usam drogas, profissionais do sexo e\npessoas trans.","D":"Estudos realizados no Brasil demonstraram taxas de prevalência de HIV de 4,9% entre mulheres\nprofissionais de sexo; 5,9% entre pessoas que usam drogas (exceto álcool e maconha); 10,5%\nentre gays e 31,2% entre pessoas trans."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183634","number":"183634","sourceNumber":"183634","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Existem materiais biológicos sabidamente infectantes e envolvidos na transmissão do\nHIV. Assim, a exposição a esses materiais constitui situação na qual a PEP está recomendada.\n\nNÃO sendo parte dos mesmos, o seguinte item:","options":{"A":"sêmen.","B":"fluidos vaginais.","C":"secreções nasais.","D":"líquidos de serosas (peritoneal, pleural, pericárdico)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183093","number":"183093","sourceNumber":"183093","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pessoas em parceria sorodiscordante para o HIV também são consideradas prioritárias\npara uso da Profilaxia Pré-Exposição ao HIV\n(PrEP). Sendo CORRETO, apenas, o seguinte\nconceito:","options":{"A":"As evidências científicas não indicam a baixa transmissibilidade de HIV por via sexual quando\numa pessoa HIV positiva está sob terapia\nantirretroviral (TARV) há mais de seis meses.","B":"Adicionalmente, entende-se que a PrEP não pode ser utilizada pelo(a) parceiro(a)\nsoronegativo(a) como forma complementar de\nprevenção para casos de relato frequente de sexo\nsem uso de preservativo, múltiplas parcerias e/ou para o planejamento reprodutivo de casais\nsorodiscordantes.","C":"As evidências científicas já indicam a alta transmissibilidade de HIV por via sexual quando uma\npessoa HIV positiva está sob terapia\nantirretroviral (TARV) há mais de seis meses.","D":"As evidências científicas já indicam a baixa transmissibilidade de HIV por via sexual quando uma\npessoa HIV positiva está sob terapia\nantirretroviral (TARV) há mais de seis meses, apresenta carga\nviral indetectável."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183121","number":"183121","sourceNumber":"183121","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Profilaxia Pós-Exposição (PEP) para HIV está disponível no SUS desde 1999.\nAtualmente, é uma tecnologia inserida no\nconjunto de estratégias da Prevenção Combinada, cujo\nprincipal objetivo é ampliar as formas de intervenção para evitar novas infecções pelo HIV. Estando\nINADEQUADO, apenas, o seguinte item:","options":{"A":"nesse contexto, considera-se fundamental a restrição do acesso à PEP, com prescrição efetiva\nnos atendimentos em serviços de\nurgência/emergência, unidades básicas de saúde, clínicas e\nhospitais da rede pública e privada.","B":"a Profilaxia Pós-Exposição (PEP) de risco à infecção pelo HIV, hepatites virais e outras IST\nconsiste no uso de medicamentos para reduzir o risco de adquirir essas infecções.","C":"o esquema antirretroviral (ARV) da PEP para HIV foi simplificado na atualização do PCDT, em\n2015.","D":"ocorre recomendações de profilaxia pela avaliação do risco da situação de exposição e não mais\npor categoria de exposição (acidente com material biológico, violência sexual e exposição sexual\nconsentida)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134273","number":"134273","sourceNumber":"134273","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Apresenta grande importância, na abordagem terapêutica, o conhecimento de quais\nantimicrobianos que são capazes de ultrapassar a barreira hematoencefálica. Dos listados abaixo,\nqual NÃO é capaz de concentração em SNE via endovenosa?","options":{"A":"Amicacina.","B":"Penicilina.","C":"Cloranfenicol.","D":"Cefepime."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134822","number":"134822","sourceNumber":"134822","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em se tratando de antimicrobiano, assinale a alternativa INCORRETA.","options":{"A":"Cefalosporina de segunda geração, capacidade de penetração pela barreira hemato encefálica.","B":"Cotrimoxazol, potencial lesão do tubo neural na organogênese.","C":"Penicilinas potencialmente teratogênicas.","D":"Aminoglicosídeo potencializa lesão de placa neural por curare."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131330","number":"131330","sourceNumber":"131330","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual dos métodos abaixo apresenta maior sensibilidade diagnóstica para Pneumocystis\njirovecii?","options":{"A":"Pesquisa direta no escarro e coloração de Grocott.","B":"Cultura de escarro em meio de Sabourreau.","C":"Lavado broncoalveolar e coloração pelo Giemsa.","D":"Pesquisa direta no líquido pleural e coloração de Grocott.","E":"NDA."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134827","number":"134827","sourceNumber":"134827","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em uma unidade básica de saúde a equipe responsável pela vigilância epidemiológica\nrecebeu uma notificação de um caso suspeito\nde meningite bacteriana em uma criança com dois\nanos matriculada em uma creche da região. Qual é o procedimento correto a ser realizado após a\ninvestigação inicial?","options":{"A":"Se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia com rifampicina em\ncontatos íntimos no prazo de 48h da exposição.","B":"Se o agente isolado for Haemophilus influenzae não há necessidade de realização de\nquimioprofilaxia em contatos íntimos.","C":"Se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia em contatos com\nabordagem ampliada com o uso de ceftriaxona no prazo de 96h da exposição.","D":"Independentemente do agente etiológico, realizar quimioprofilaxia em contatos com\nabordagem ampliada com uso de ceftriaxona no prazo de 96h da exposição."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-109728","number":"109728","sourceNumber":"109728","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo feminino, 68 anos, com antecedente de diabetes mellitus tipo 2, é\ninternada por pielonefrite. Urinocultura positiva para Escherichia Coli sensível à ceftriaxona.\nIniciado\ntratamento com ceftriaxona 2 g/dia. Após cinco dias de tratamento, a paciente mantém febre,\nleucocitúria e leucocitose com desvio. Assinale abaixo a conduta MAIS apropriada para o caso\ncitado:","options":{"A":"Trocar antibiótico para norfloxacino, pois sua ação é superior ao ceftriaxona em infecções do\ntrato urinário.","B":"Associar azitromicina e metronidazol, para aumentar espectro para germes atípicos e\nanaeróbios.","C":"Realizar ultrassonografia de abdome, para afastar fatores complicantes que requerem\nintervenção urológica.","D":"Manter antibioticoterapia, pois é normal a manutenção de febre em quadros de pielonefrite até o\noitavo dia de tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-109764","number":"109764","sourceNumber":"109764","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação ao Tétano generalizado, assinale a alternativa INCORRETA.","options":{"A":"Os Benzodiazepínicos são as drogas de escolha para controle dos espasmos musculares.","B":"Imunização passiva com imunoglobulina deve ser realizada nos casos confirmados.","C":"Não há acometimento do Sistema Nervoso Autônomo nos casos de Tétano generalizado.","D":"O antibiótico de escolha para o tratamento do Tétano é o Metronidazol."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-110013","number":"110013","sourceNumber":"110013","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um menino de 9 anos com uma válvula aórtica bicúspede desenvolve endocardite\nbacteriana após extração de um dente. O\norganismo mais provável de ter causado endocardite\nnesse paciente é","options":{"A":"Candida albicans.","B":"Escherichia coli.","C":"Staphylococcus aureus.","D":"Staphylococcus mitis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-109805","number":"109805","sourceNumber":"109805","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pré-escolar de 4 anos é trazido ao Pronto-socorro com história de febre, vômitos e\nprostração. Ao exame físico, apresenta rigidez de nuca. O liquor mostrou-se compatível com\nmeningite bacteriana e apresentou bacterioscopia positiva para cocos Gram-negativos. O paciente\nvive com os pais e 2 irmãos num barraco de um cômodo e frequenta uma creche pública. Os\ncontactantes devem receber quimioprofilaxia com:","options":{"A":"Ceftriaxone por 2 dias.","B":"Rifampicina por 4 dias.","C":"Rifampicina por 2 dias.","D":"Penicilina benzatina em dose única."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-86805","number":"86805","sourceNumber":"86805","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual das classes de antibióticos abaixo é a primeira escolha para tratamento da\npielonefrite em adultos?","options":{"A":"Nitrofurantoin;","B":"Betalactâmicos;","C":"Aminoglicosídeos;","D":"Sulfas;","E":"Fluoroquinolonas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-86676","number":"86676","sourceNumber":"86676","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação à Dengue, quanto à definição de caso, é correto afirmar que:","options":{"A":"Caso suspeito de dengue clássico: paciente que tenha doença febril aguda, com duração\nmáxima de 7 dias, acompanhada de pelo menos mais dois sintomas.","B":"Caso confirmado de dengue clássico: é o caso confirmado laboratorialmente.","C":"Caso suspeito de Febre Hemorrágica da Dengue (FHD): é todo caso suspeito de dengue\nclássico que também apresente manifestações hemorrágicas.","D":"Caso de dengue com complicações: é todo caso que se enquadre nos critérios de FHD e a\nclassificação de dengue clássico é insatisfatória.","E":"Caso descartado: caso suspeito, sem exame laboratorial, cujas investigações clínica e\nepidemiológica são compatíveis com outras patologias."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-362424","number":"362424","sourceNumber":"362424","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Gestante em acompanhamento pré-natal fez diagnóstico de HIV com 29 semanas.\nIniciou TARV e fez uso regular até o\nnascimento do bebê. A Carga viral (CV) com 38 semanas era\nde 1400 cópias. Com relação ao manejo do RN, qual deverá ser a conduta no alojamento conjunto:","options":{"A":"Coletar CV ao nascimento e iniciar profilaxia com AZT + 3TC + RAL por 28 dias.","B":"Coletar CV no primeiro dia de vida e iniciar profilaxia com AZT xarope por 28 dias.","C":"Coletar CV no 14° dia de vida e iniciar profilaxia com AZT e NVP por 28 dias.","D":"Coletar CV ambulatorialmente e iniciar profilaxia com TDF + 3TC + DTG."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-327286","number":"327286","sourceNumber":"327286","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pedro é recém-nascido a termo, com peso de nascimento de 3 Kg, filho de mãe que\ndescobriu HIV na 20ª semana de gestação. Iniciou uso de TARV, assim que teve o diagnóstico. No\nmomento do Parto, não havia registro da Carga Viral, após o início da TARV. Qual a conduta mais\nadequada com Pedro na maternidade e seguimento:","options":{"A":"Coletar CV na sala de parto, aguardar resultado para iniciar TARV profilática por via oral e\nencaminhar para seguimento, com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida.","B":"Coletar CV na sala de parto, iniciar AZT, 3TC e RAL por via oral e encaminhar para seguimento\ncom coleta de nova CV com: 14 dias, na 6ª e 12ª\nsemana de vida.","C":"Coletar CV na sala de parto, iniciar AZT por via oral e encaminhar para seguimento com coleta\nde nova CV com: 14 dias, na 6ª e 12ª semana\nde vida.","D":"Coletar CV na sala de parto, iniciar AZT, NVP por via oral e encaminhar para seguimento com\ncoleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-298254","number":"298254","sourceNumber":"298254","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Gestante de 21 anos, primigesta, teve a primeira consulta de pré-Natal no primeiro\ntrimestre de gestação e apresentou teste rápido para HIV positivo. Foi encaminhada para\nacompanhamento no SAE e manteve o pré-natal na UBS. Apresentou a primeira carga viral HIV\n\n25.000 cópias, CD4 520 células. Iniciou tratamento com TDF + 3TC + DTG após 20 semanas de\ngestação. Não tinha outras ISTs ou comorbidades. Com 35 semanas de idade gestacional realizou\nnova Carga viral que estava em 1000 cópias. O Bebê nasceu com 39 semanas de gestação, parto\ncesárea, peso de nascimento 3500g Estatura 49cm PC 35 cm, apgar 9/10. Com relação a\nclassificação materna e as medidas a serem tomadas com relação ao recém nascido na\nmaternidade, assinale a alternativa CORRETA:","options":{"A":"Gestante de alto risco. Coletar Carga viral do RN, iniciar profilaxia com AZT + 3TC + Raltegravir\ne não amamentar.","B":"Gestante de baixo risco. Coletar Carga viral do RN, iniciar profilaxia com AZT e não amamentar.","C":"Gestante de alto risco. Coletar Carga viral do RN, iniciar profilaxia com AZT + Nevirapina e não\namamentar.","D":"Gestante de baixo risco. Coletar Carga viral do RN, iniciar profilaxia com AZT e liberar\namamentação."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-256578","number":"256578","sourceNumber":"256578","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Avaliação por imagem do trato urinário pode ser feito com (assinale a CORRETA)","options":{"A":"Urinocultura e antibiograma","B":"EAS e Proteinúria de 24h","C":"Ultrasson e TC","D":"Clearance de creatinina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-151859","number":"151859","sourceNumber":"151859","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São doenças indicativas de síndrome da imunodeficiência adquirida (Aids), EXCETO:","options":{"A":"Pneumonia.","B":"Criptococose extrapulmonar.","C":"Histoplasmose disseminada.","D":"Linfogranuloma não Hodgkin tipo B."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-139098","number":"139098","sourceNumber":"139098","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A pielonefrite aguda é melhor diagnosticada por:","options":{"A":"Bacteriúria e piúria.","B":"Calafrios, febre e dor no flanco.","C":"Escara renal.","D":"Prejuízo da função renal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103797","number":"103797","sourceNumber":"103797","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Infecção que se dissemina através da fáscia de Buck, ao longo dos planos fasciais,\ndartos, escroto, estendendo-se para a fáscia de\nColles do períneo, podendo atingir a fáscia de\nScarpa:","options":{"A":"Síndrome de Fournier.","B":"Gangrena de Meleney.","C":"Abscesso isquiorretal.","D":"Miosite clostrídica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103863","number":"103863","sourceNumber":"103863","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Adolescente de 15 anos, sexo masculino, procurou o Pronto atendimento apresentando\nuretrite (síndrome uretral aguda). Relata vida\nsexual ativa com parceira fixa, sem uso de\npreservativo. Qual o agente etiológico provável?","options":{"A":"Haemophilus ducreyi","B":"Chlamydia trachomatis","C":"Cândida Albicans","D":"Herpes vírus"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-60818","number":"60818","sourceNumber":"60818","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São antibióticos concentração dependentes:","options":{"A":"Penicilinas, Cefalosporinas e Macrolídeos","B":"Quinolonas, Aminoglicosídeos, Polimixinas","C":"Quinolonas, Aminoglicosídeos e Macrolídeos","D":"Aminoglicosídeos, Quinolonas e Cefalosporinas","E":"Aminoglicosídeos, Quinolonas, Carbapenêmicos"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-60841","number":"60841","sourceNumber":"60841","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considerando a resistência do S. aureus aos antibióticos podemos afirmar:","options":{"A":"A resistência à Vancomicina é devido à presença do gen Van A, e o antibiótico indicado para\ntratamento seria a linezolida.","B":"A resistência à Vancomicina é devido à presença do gen Mec A, e o antibiótico indicado para\ntratamento seria a linezolida.","C":"A resistência à Oxacilina é devido à presença do gen VAN A, e o antibiótico indicado para\ntratamento seria a Vancomicina.","D":"A resistência à Vancomicina é devido à presença de enzimas que quebram o anel das\npenicilinas e o antibiótico indicado para tratamento seria a linezolida.","E":"A resistência à Oxacilina é devido à presença de enzimas que quebram o anel das penicilinas e\no antibiótico indicado para tratamento seria\numa Quinolona."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-7495","number":"7495","sourceNumber":"7495","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à cetoacidose diabética (CAD):","options":{"A":"É uma causa de acidose metabólica com ânion gap aumentado.","B":"É necessário haver tanto deficiência de insulina quanto presença de glucagon para que ocorra\nCAD.","C":"Pode haver elevação de ureia e creatinina por depleção do volume intravascular.","D":"O aceto-acetato não é detectado na urina pelo teste do nitroprussiato.","E":"A reposição de volume deve ser vigorosa, principalmente no início do tratamento."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-10040","number":"10040","sourceNumber":"10040","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sr. Nilson tem 66 anos, é diabético, hipertenso e tem insuficiência arterial periférica.\nUsa regularmente diurético e sulfanilureía. Há 3\ndias, apresenta uma ferida no 5° pododáctilo direito\ncom secreção purulenta e febre. Hoje, sua pressão arterial esta 200 x 110mmHg e sua glicemia\ncapilar 330. Você o examina e:","options":{"A":"encaminha-o para internação hospitalar solicitando avaliação pelo cirurgião vascular de plantão\nno pronto-socorro. Inicia insulinoterapia.","B":"Acrescenta beta-bloqueador ao esquema anti-hipertensivo e pede urgente avaliação cirúrgica no\npronto-socorro.","C":"aumenta as doses do diurético e da sulfanilureia e inicia antibioticoterapia oral.","D":"encaminha-o para internação hospitalar e inicia antibioticoterapia oral e biguanida.","E":"inicia insulinoterapia e antibioticoterapia oral domiciliar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9981","number":"9981","sourceNumber":"9981","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O fator de predisposição mais comum para infecções do trato urinário adquiridas no\nhospital é:","options":{"A":"Procedimento cirúrgico.","B":"Utilização de antibióticos.","C":"Idade.","D":"Sondagem vesical.","E":"Diabetes Mellitus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-49364","number":"49364","sourceNumber":"49364","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher, 23 anos de idade, com história de febre reumática desde os 18 anos de idade,\nda qual resultou regurgitação mitral leve.\nEm uso de penicilina benzatina, a cada três semanas, há\ncinco anos, deverá fazer tratamento odontológico simples com remoção de tártaro. Não teve\nrecidivas reumáticas e se queixa do uso das injeções mensais, perguntando se pode\n\ninterrompê-las. A orientação, com base em evidências científicas, é:","options":{"A":"Continuar a penicilina benzatina por, no mínimo, mais cinco anos para profilaxia de recidiva\nreumática e informar que não há indicação para profilaxia antibiótica antes do procedimento\ndentário;","B":"Continuar a penicilina benzatina por, no mínimo, mais cinco anos, fazer amoxacilina 2 gramas,\nvia oral, 1 hora após o procedimento\ndentário;","C":"Suspender a penicilina benzatina, fazer apenas amoxacilina 2 gramas, via oral, 1 hora antes do\nprocedimento dentário;","D":"Suspender a penicilina benzatina, considerando que já é adulta, e informar que não há indicação\npara profilaxia antibiótica antes do\nprocedimento dentário;","E":"Manter a penicilina benzatina até os 25 anos de idade e fazer profilaxia com amoxicilina 2\ngramas, via oral, 1 hora após o procedimento dentário."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-49449","number":"49449","sourceNumber":"49449","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem, 27 anos de idade, cursando com dor de garganta, febre com 38,5°C e tosse\ncom expectoração há cinco dias. Ao exame físico,\napresenta hiperemia de mucosas e exsudato\namarelado. Não há assimetria de palato, nem desvio mediano de pilares amigdalianos. Notam-se\nlinfadenopatias submaxilares e cervicais dolorosas. Entre os critérios clínicos usualmente\nempregados para definir possível faringite bacteriana no caso, não se inclui:","options":{"A":"febre acima de 38°C.","B":"linfadenopatia cervical.","C":"exsudato faríngeo.","D":"presença de tosse.","E":"idade inferior a 45 anos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-49466","number":"49466","sourceNumber":"49466","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Dentre os pacientes relacionados a seguir, o que tem indicação para tratamento de\ninfecção do trato urinário é:","options":{"A":"Homem, 35 anos de idade, com traumatismo raquimedular em uso de cateter de permanência,\nassintomático, com urocultura 3,4 x 10 (elevado a 5) UFC/ml para Proteus mirabilis.","B":"Homem, 75 anos de idade, com indicação de ressecção transuretral por hipertrofia prostática e\nurocultura 1,2 x 10 (elevado a 5) UFC/ml para E. coli.","C":"Mulher, 65 anos de idade, diabética, sem sintomas urinários ou febre com urocultura 2,2 x 10\n(elevado a 5) UFC/ml para E. coli.","D":"Mulher, 23 anos de idade, com febre sem disúria e urocultura 4,5 x 10² UFC/ml para E. coli, sem\npiúria em amostra única coletada por jato médio.","E":"Mulher, 55 anos de idade, com desconforto à micção, sem febre, com 25 piócitos/campo, em\nsumário de urina, urocultura \"menor que\" 10 (elevado a 5) UFC/ml, em duas amostras por coleta de\njato médio."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-34937","number":"34937","sourceNumber":"34937","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às meningites, é correto afirmar:","options":{"A":"Na meningite não bacteriana, espera-se pressão liquórica entre 50 mmHg e 190 mmHg.","B":"Na meningite bacteriana, espera-se relação glicose sérica/glicorraquia de aproximadamente 0,6.","C":"Após os 50 anos de idade, o principal agente bacteriano esperado é S.aureus.","D":"Proteinorraquia maior que 200 mg/dl não é esperada na meningite bacteriana.","E":"Pacientes que tiveram TCE e desenvolveram meningite têm maior chance de infecção por\nListeria monocytogenes."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-11141","number":"11141","sourceNumber":"11141","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher, 75 anos de idade, com doença de Alzheimer, em ambiente asilar, com\nincontinência esfincteriana prévia, vem há dois\ndias com agitação psicomotora intercalada por\nperíodos de sonolência. Não teve diarreia e a temperatura medida pela cuidadora foi de 37,8°C. Ao\nexame físico, apresenta- se sem rigidez nucal, sem sinais de localização, PR: 108 bpm, FR: 21 ipm,\nausculta cardiorrespiratória evidenciando discretos crépitos inspiratórios e expiratórios em base,\nsem variação com a tosse. Abdome flácido, indolor. A investigação deve começar por:","options":{"A":"tomografia computadorizada de crânio.","B":"Rx de tórax em PA e perfil, gram e ziehl do escarro.","C":"ecocardiograma bidimensional.","D":"sumário de urina e uroculturas.","E":"punção liquórica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-11200","number":"11200","sourceNumber":"11200","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente sexo masculino, 10 anos de idade, procedente da zona rural. Apresenta\nqueixa de febre, cefaleia e dor abdominal.\nNa história, destaca-se a ocorrência de um abscesso em\ncouro cabeludo, há 30 dias, associado a febre. Após a ocorrência do fato, o paciente desenvolveu\num quadro de persistência da febre e dor importante em HCD. O estado geral piorou, com\nleucocitose: 20000 com predomínio de polimorfonucleares (bastões: 10%, segmentados: 50%,\nlinfócitos: 25%, eosinófilos: 15%) HT: 36, Hb: 11,6, TGO: 33,5, TGP: 34,7. O estudo, por imagem,\nde abdome mostrou fígado com dimensões limítrofes, múltiplas hipodensidades, em lobo direito, a\nmaior delas em situação subcapsular, medindo 3,0 cm, em seu maior diâmetro.\n\nO diagnóstico mais provável, para o quadro descrito é:","options":{"A":"hepatoblastoma.","B":"abscessos hepáticos multifocais.","C":"esquistossomose hepática.","D":"hepatite pelo vírus A.","E":"doença policística hepática."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-11165","number":"11165","sourceNumber":"11165","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente, 10 anos de idade, sexo masculino, vem apresentando há 2 semanas, após\nextração dentária, queda progressiva do estado geral, febre persistente, palidez, sudorese. Nos\nantecedentes, é portador de insuficiência da válvula mitral de grau leve, faz uso de penicilina\nbenzatina de 21 em 21 dias, há 2 anos. O exame físico: dispneia com SS em foco da ponta,\npresença de 3ª bulha. Hemograma com leucocitose e desvio à esquerda. Ecocardiograma mostra\nmassa cardíaca oscilante em valva mitral. O diagnóstico mais provável é:","options":{"A":"cardite reumática.","B":"septicemia.","C":"endocardite infecciosa.","D":"pneumonia estafilocócica.","E":"fibroelastose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-343335","number":"343335","sourceNumber":"343335","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pessoas com infecção pelo HTLV e assintomáticas com elevada carga pró viral:","options":{"A":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, apresentam expressão de IFN-? mais baixa do\nque de IL- 10.","B":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, não apresentam expressão de IFN-? mais\nelevada do que de IL- 10.","C":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated\nmyelopathy)HAM, apresentam expressão de IFN-? mais elevada do que de IL- 10.","D":"Assim como indivíduos com mielopatia associada ao HTLV-1 (HTLV-1 associated myelopathy)\nHAM, apresentam expressão de IFN-? mais elevada\ndo que de IL- 100."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-343339","number":"343339","sourceNumber":"343339","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em PVHIV, o acometimento ganglionar da Tuberculose tende a ser bilateral, associado\ncom maior comprometimento do estado geral.","options":{"A":"Ao exame físico, os gânglios podem apresentar-se endurecidos e nunca amolecidos, aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","B":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, não aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","C":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação e/ou fistulização espontânea, com a\ninflamação da pele adjacente.","D":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação, mas não para fistulização espontânea,\ncom a inflamação da pele adjacente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-343341","number":"343341","sourceNumber":"343341","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Antes de iniciar a corticoterapia nesses pacientes com HAM mielopatia associada ao\nHTLV-1 (HTLV-1 associated myelopathy), é fundamental realizar avaliação clínica para excluir\noutras comorbidades, de acordo com o item correto :","options":{"A":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e escabiose.","B":"Que não possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e escabiose.","C":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, tuberculose e não a escabiose.","D":"Que possam se exacerbar em consequência do uso de corticoide. São elas, principalmente:\ninfecção pelo HIV, hepatites B e C, sífilis,\nestrongiloidíase, mas não tuberculose e escabiose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281855","number":"281855","sourceNumber":"281855","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A tuberculose é a doenca infecciosa de maior mortalidade entre as pessoa vivendo com\nHIV PVHIV, sendo adequado o item:","options":{"A":"As PVHIV em seguimento clínico devem ser triadas para TB em todas as visitas aos serviços de\nsaúde, mediante o questionamento sobre a existência de um dos quatro sintomas: febre, tosse,\nsudorese noturna e emagrecimento.","B":"As PVHIV em seguimento clínico não devem ser triadas para TB em todas as visitas aos\nserviços de saúde, mediante o questionamento sobre a existência de um dos quatro sintomas:\nfebre, tosse, sudorese noturna e emagrecimento.","C":"As PVHIV em seguimento clínico devem ser triadas para TB somente na primeira visita aos\nserviços de saúde, mediante o questionamento sobre a existência de um dos quatro sintomas:\nfebre, tosse, sudorese noturna e emagrecimento.","D":"As PVHIV em seguimento clínico devem ser triadas para TB em todas as visitas aos serviços de\nsaúde, mas nunca questionando sobre a existência de um dos quatro sintomas: febre, tosse,\nsudorese noturna e emagrecimento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281857","number":"281857","sourceNumber":"281857","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre o inicio célere da Terapia Antirretroviral - TARV nas pessoa vivendo com HIV\nPVHIV, pode-se afirmar que:","options":{"A":"É também uma estratégia de prevenção da TB, uma vez que a terapia diminui a incidência de TB\nnessa população, devendo ser instituída sem\ndemora.","B":"É também uma estratégia de prevenção da TB, uma vez que a terapia aumenta a incidência de\nTB nessa população, devendo ser instituída\nsem demora.","C":"É também uma estratégia de prevenção da TB, uma vez que a terapia diminui a incidência de\nTB nessa população, não devendo ser instituída\nsem demora.","D":"É também uma estratégia de prevenção da TB, uma vez que a terapia diminui a incidência de\nTB nessa população, devendo ser instituída o\nmais tarde possível."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-250019","number":"250019","sourceNumber":"250019","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Visando promover ações que viabilizem o tratamento adequado das populações com\ntuberculose mais vulnerável, especialmente pessoas vivendo com HIV e população privada de\nliberdade, somente sendo inadequado que:","options":{"A":"Adotar estratégias para acompanhamento do tratamento, capazes de reduzir os desfechos\nfavoráveis.","B":"Estimular o desenvolvimento do cuidado centrado na pessoa com tuberculose.","C":"Organizar a rede de atenção local, tendo em vista a organização da atenção básica, para\nfavorecer o acesso e a qualidade da assistência.","D":"Integrar ações de vigilância epidemiológica e assistência."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-181185","number":"181185","sourceNumber":"181185","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"De acordo com os critérios de Duke modificado para endocardite infecciosa, são\nconsiderados critérios maiores, EXCETO:","options":{"A":"Hemocultura positiva.","B":"Ecocardiograma positivo.","C":"Lesões de Janeway.","D":"Evidência de envolvimento endocárdico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157660","number":"157660","sourceNumber":"157660","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Otite Externa Maligna (OEM) é uma infecção muito grave que acomete o canal\nauditivo externo e a base do crânio. Em nossa\natualidade se trata de uma infecção rara, mas tem\nalta morbidade e potencialmente fatal. Sobre essa situação clínica, indique a alternativa\nconsiderada INADEQUADA.","options":{"A":"Acomete principalmente pacientes idosos com DM e é causada por Pseudomonas aeruginosa.","B":"Isso, possivelmente, se deve a uma microangiopatia no canal auditivo.","C":"Isso, possivelmente, se deve a diminuição do pH no cerume de diabéticos.","D":"Suscetibilidade à otite externa maligna não tem sido correlacionada ao grau de intolerância à\nglicose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157665","number":"157665","sourceNumber":"157665","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Otite Externa Maligna (OEM) é uma infecção grave que se relaciona com a DM,\nacomete o canal auditivo externo e a base do crânio, podendo apresentar importante\nmorbimortalidade. Diante de tal caso, aponte a alternativa CORRETA.","options":{"A":"A OEM geralmente não cursa com dor intensa, sendo responsiva às medicações tópicas usadas\nna otite externa aguda.","B":"Ao exame físico, o tecido de granulação é frequentemente visível na parte inferior do canal\nauditivo externo, na junção cartilagem-osso.","C":"Complicações do sistema nervoso central são muito comuns.","D":"Ocorrendo o avanço da infecção, mesmo ocorrendo osteomielite, a base do crânio é poupada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157647","number":"157647","sourceNumber":"157647","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Jovem primigesta, 23 anos de idade, procurou o hospital com quadro de estrangúria e\nfebre. A obstetrícia pediu seu parecer clínico. Durante avaliação, você encontrou uma dor lombar e\npélvica, e solicitou USG de vias urinárias, que foi normal, e um exame de urina, que demonstrou\npiúria. Qual das medicações abaixo listadas, apesar de adequada ao tratamento de pielonefrite,\ndeve ser contraindicada por risco de lesão óssea fetal?","options":{"A":"Ceftriaxona.","B":"Ciprofloxacino.","C":"Cloranfenicol.","D":"Amicacina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157693","number":"157693","sourceNumber":"157693","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Jovem de 34 anos de idade procura hospital com quadro de tosse produtiva amarelada\ne febre, além de dor pleural. Na ausculta,\nencontramos estertores creptantes em base de pulmão\ndireito. Seu diagnóstico é o de Pneumonia. Qual das opções abaixo listadas NÃO apresenta\ncobertura para bactérias ditas atípicas?","options":{"A":"Azitromicina.","B":"Amoxacilina + Clavulanato.","C":"Moxifloxacino.","D":"Tetraciclina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134737","number":"134737","sourceNumber":"134737","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Para tratamento de infecções em sistema nervoso central, apresenta importância, o\nconhecimento de antimicrobianos que seriam capazes de atingir concentração após passagem pela\nbarreira hematoencefálica. Qual dos abaixo, NÃO possui essa capacidade?","options":{"A":"Cefepime.","B":"Cefuroxima.","C":"Ceftazidime.","D":"Cefaclor."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134750","number":"134750","sourceNumber":"134750","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Apresenta grande importância clínica o conhecimento de medicações que são\npotencialmente nefrotóxicas. NÃO possui essa característica, apenas:","options":{"A":"As cefalosporinas.","B":"Os aminoglicosídeos.","C":"A vancomicina.","D":"O metronidazol."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-139741","number":"139741","sourceNumber":"139741","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual é o agente etiológico da Sífilis?","options":{"A":"Protossifiloma.","B":"Treponema pallidum.","C":"Herpes vírus.","D":"Haemophilus Ducreyi."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134771","number":"134771","sourceNumber":"134771","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Durante consulta ambulatorial, foi feita suspeita clínica de uma Infecção Urinária Baixa,\nprovavelmente uma Cistite não complicada em mulher jovem. Como não se tratava de quadro\ngrave, foi soliticitado colheita de urocultura, e, logo após, uso de antibiótico empírico. Ocorreu\nque a\npaciente se curou clinicamente da ITU, mas seu resultado de urocultura revelou que o antibiótico\nprescrito não tinha perfil adequado, portanto, a bactéria não foi sensível ao mesmo. Essa\nsituação pode ser explicada, assim, de maneira adequada, como:","options":{"A":"Erro laboratorial provavelmente.","B":"Má qualidade da amostra de urina.","C":"Excreção via urinária, assim maior concentração que a sérica avaliada pela cultura.","D":"Reagentes inadequados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134708","number":"134708","sourceNumber":"134708","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O exame padrão-ouro para diagnóstico de ITU é:","options":{"A":"Ultrassonografia de rins e vias urinárias.","B":"Hemocultura.","C":"Urina tipo 1 colhida por sondagem vesical.","D":"Urinocultura."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-139779","number":"139779","sourceNumber":"139779","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quando indicamos um tratamento antimicrobiano é importante o conhecimento do\nmecanismo de ação de que dispomos, a fim de adequar a conduta frente à indicação da provável\netiologia da infecção a ser tratada. Das medicações seguintes, assinale aquela que NÃO baseia\nsua ação em síntese proteica da bactéria.","options":{"A":"Macrolídeos.","B":"Quinolonas.","C":"Penicilina.","D":"Tetraciclina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134701","number":"134701","sourceNumber":"134701","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Segundo a Agência Nacional de Vigilância Sanitária, sobre infecção hospitalar, avalie\nas afirmações a seguir. I. É aquela adquirida\napós a admissão do paciente e que se manifesta\ndurante a internação ou após a alta, quando puder ser relacionada com a internação ou\nprocedimentos hospitalares. II. Quando se desconhecer o período de incubação do microrganismo\ne não houver evidência clínica e/ou dado laboratorial de infecção no momento da internação;\nconvenciona-se infecção hospitalar toda manifestação clínica de infecção que se apresentar a partir\nde 72 (setenta e duas) horas após a admissão. III. É aquela constatada ou em incubação no ato de\nadmissão do paciente, desde que não relacionada com internação anterior no mesmo hospital. São\nCORRETAS as afirmações contidas em","options":{"A":"I, II e III.","B":"I e II, somente.","C":"I e III, somente.","D":"II e III, somente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111830","number":"111830","sourceNumber":"111830","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Apesar do grande uso atual das ditas Quinolonas Respiratórias, ainda existe uma\nrestrição da mesma para determinado grupo de pacientes, isso é decorrente de:","options":{"A":"gestantes por lesões dentárias.","B":"crianças por lesões dentárias.","C":"fetos por alteração do tubo neural.","D":"crianças e gestantes por interação com crescimento ósseo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111857","number":"111857","sourceNumber":"111857","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Usuários de drogas injetáveis podem apresentar diversas complicações, das mais\ndiversas possíveis, entre elas a infecção e o aparecimento das ditas Vegetações nas Válvulas\nCardíacas. Qual das alternativas seguintes MELHOR caracteriza essa situação?","options":{"A":"Estreptococo.","B":"Estafilococo.","C":"Enterococo.","D":"Moraxela."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111910","number":"111910","sourceNumber":"111910","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual é o PRINCIPAL fator de pressão para o aparecimento de bactérias com alta\nresistência aos antimicrobianos?","options":{"A":"Aumento do número de pacientes em UTI.","B":"Aumento do número de idosos.","C":"Aparecimento de novos antimicrobianos.","D":"Aumento do uso indiscriminado de antibióticos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-350889","number":"350889","sourceNumber":"350889","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Jovem de 20 anos é diagnosticado com tuberculose pulmonar em Unidade Básica de\nSaúde. Na ocasião em que recebe o diagnóstico, a equipe de saúde aproveita a oportunidade para\nrealizar testagem rápida para HIV. É coletada amostra de sangue por punção digital e realizados\ndois testes rápidos (TR), na presença do paciente, com os resultados mostrados na imagem (A =\nprimeiro TR; B = segundo TR). O paciente nunca havia sido testado antes. Diante deste cenário,\nqual(is) o(s) próximo(s) exame(s) a ser(em) solicitado(s)?","options":{"A":"Novos testes rápidos.","B":"ELISA 4a geração.","C":"CD4 e carga viral.","D":"Western blot."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-292838","number":"292838","sourceNumber":"292838","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma criança de três anos de idade vem ao ambulatório com relato materno de que nos\núltimos 12 meses teve seis infecções respiratórias, sendo que em vários destes episódios fez uso\nde antibióticos com resposta satisfatória. Ao examinar a criança, o médico constata boa evolução\ndo desenvolvimento ponderoestatural e ausência de anormalidades ao exame físico. Qual a\ninterpretação adequada para o problema que essa criança apresenta?","options":{"A":"Infecções respiratórias de repetição na infância, em sua maioria, estão associadas a falhas na\nresposta imunológica.","B":"São identificados como fatores de risco: ambiente de creche, número de irmãos, poluição\nambiental e tabagismo passivo.","C":"Infecções respiratórias de repetição na infância refletem imaturidade imunológica e maior\nexposição a microrganismos infecciosos durante os primeiros anos de vida.","D":"Deve-se prosseguir investigação de doenças de base, seja de natureza aspirativa, doença\ncardíaca congênita, distúrbio neuromuscular, imunodeficiência ou malformação pulmonar."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-234039","number":"234039","sourceNumber":"234039","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 44 anos é levado à unidade de pronto atendimento com história de duas\nsemanas de febre, cefaleia intensa\nprogressiva e episódios de desorientação. Há um dia, apresenta\nconvulsões tônico-clônicas generalizadas. Ao exame: hipocorado 2+/4+, emagrecido; Glasgow 13,\nhemiparesia esquerda; ausência de sinais de irritação meníngea. Familiares relatam que fazia\nacompanhamento por infecção por HIV, mas abandonou tratamento há 1 ano. Exames de um mês\natrás: CD4 = 80 células/mm³ (VR = acima de 500 células/mm³); carga viral = 246.000 cópias/ml (VR\n\n= abaixo de 40 cópias/ml). TC de crânio com contraste teve o seguinte resultado (ver imagem).\nLEGENDA: VR: Valor de Referência. Com base na principal hipótese para o caso, qual o próximo\npasso do processo diagnóstico?","options":{"A":"Colher liquor para PCR.","B":"Iniciar prova terapêutica.","C":"Dosar IgM e IgG no sangue.","D":"Indicar biópsia estereotáxica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-234048","number":"234048","sourceNumber":"234048","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"André, 15 meses de idade, é atendido no ambulatório de pediatria com sinusites e\notites frequentes há 8 meses. Infecções de repetição não muito graves que melhoram com\nantibioticoterapia oral. Lactente apresenta crescimento e desenvolvimento normais. Vacinação\natualizada. Nega reações vacinais. Ao exame físico, apresenta tecido linfoide amigdaliano e\ngânglios palpáveis menores que 1,0 cm. Pensando na possibilidade de imunodeficiência, o\ndiagnóstico mais provável é:","options":{"A":"agamaglobulinemia ligada ao x.","B":"hipogamaglobulinemia transitória.","C":"imunodeficiência combinada grave.","D":"síndrome de imunodeficiência adquirida."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-172960","number":"172960","sourceNumber":"172960","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 49 anos é encaminhado ao Pronto-Socorro com história de febre\nintermitente há 2 semanas, associada a tosse\npredominantemente seca e dispneia progressiva.\nNega dor torácica ou hemoptoicos. Ao exame, apresenta-se emagrecido, taquidispneico (saturação\nde oxigênio em ar ambiente = 89%) e apresenta candidíase oral extensa. Não há alterações às\nauscultas cardíaca e pulmonar; ausência de visceromegalias ao exame abdominal e ausência de\nlesões de pele. Exames feitos em outro serviço:Hemoglobina 9,0 g/dL (VR: 12,8-16,5 g/dL),\nleucócitos 3.500/mm³ (10% linfócitos) (VR: 4000-11000/mm³), plaquetas 240.000/mm³ (VR:\n\n150000-450000/mm³); desidrogenase láctica = 1.200 U/L (VR: 115-225 U/L); teste rápido para HIV:\nreagente; radiografia de tórax = moderado infiltrado reticular peri-hilar bilateral. Com base na\nprincipal hipótese diagnóstica para o caso, qual a terapia antimicrobiana empírica recomendada?","options":{"A":"Anfotericina B Lipossomal.","B":"Ceftriaxona + Azitromicina.","C":"Sulfametoxazol-Trimetoprim","D":"Rifampicina-Isoniazida-Pirazinamida-Etambutol."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-173040","number":"173040","sourceNumber":"173040","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um lactente de 3 meses trazido à Unidade Básica de Saúde, apresentando quadro\nclínico compatível com bronquiolite, foi\nradiografado e realizou exames laboratoriais. Ao analisar os\nexames, o médico suspeitou de imunodeficiência primária. Que achado nesses exames fez o\nprofissional levantar essa possibilidade?","options":{"A":"Ausência de imagem tímica na radiografia de tórax.","B":"Leucograma com leucopenia e linfocitose no hemograma.","C":"Proteína C reativa e Velocidade de hemossedimentação elevadas","D":"Hiperinsuflação, opacidade ao redor do hilo pulmonar na radiografia de tórax."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-150818","number":"150818","sourceNumber":"150818","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No ambulatório, chega uma criança de oito meses de idade com relato de cicatrização\ndeficiente e abscessos profundos na pele,\nrecorrentes. Já tivera, também, ulcerações orais. Qual a\nprincipal suspeita diagnóstica?","options":{"A":"Imunodeficiência predominante dos linfócitos B.","B":"Imunodeficiência predominante dos linfócitos T.","C":"Imunodeficiência predominante do sistema fagocitário.","D":"Imunodeficiência predominante do sistema complemento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-102161","number":"102161","sourceNumber":"102161","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A sedimentoscopia urinária mostrada abaixo foi realizada em um paciente de 55 anos,\nestado geral regular, que apresentava, entre outros sintomas, febre e disúria. A conduta mais\nindicada e diagnóstico mais provável são: (VER IMAGEM)","options":{"A":"Solicitação da uroanálise e urinocultura, e tratar com sulfametoxazol + trimetoprima via oral\ndurante sete\n\ndias; cistite aguda complicada.","B":"Solicitação prévia da uroanálise e urinocultura é dispensável, e tratar com ciprofloxacino via\noral\ndurante trinta dias; prostatite aguda.","C":"Solicitação da uroanálise, urinocultura e hemocultura, e tratar com ciprofloxacino via oral\ndurante quatorze dias; pielonefrite aguda.","D":"Solicitação prévia de uroanálise e urinocultura é dispensável, e tratar com ceftriaxona\nendovenosa durante sete dias; pielonefrite aguda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-81298","number":"81298","sourceNumber":"81298","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente feminina, 66 anos, em quimioterapia para leucemia mieloide aguda. No 10º dia\nde tratamento, evolui com febre, vômitos e dor lombar. Ao exame, encontra-se taquicárdica,\ntaquipneica, hipotensa e agitada. O sinal de Giordano é positivo à esquerda. O leucograma revela\n900 leucócitos/mm³ com 50% de neutrófilos. Após coleta de urinocultura, na condição de\nmonoterapia, o esquema terapêutico mais apropriado, dentre as opções abaixo, seria:","options":{"A":"Amicacina.","B":"Aztreonam.","C":"Ciprofloxacina.","D":"Piperacilina-tazobactam."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-65737","number":"65737","sourceNumber":"65737","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo masculino, 20 anos de idade, portador de insuficiência mitral, vem\napresentando febre (até 40°C) de longa duração. Ao exame físico, observa-se palidez (++/4+) e\npetéquias conjuntivais. A ausculta cardíaca revela ritmo regular, 2 tempos, bulhas normofonéticas e\nsopro sistólico (++/4+) em foco mitral. O abdome está flácido, indolor à palpação, sem\nvisceromegalias, espaço de Traube ocupado. O ecocardiograma mostra massa cardíaca oscilante\naderida ao folheto anterior da valva mitral compatível com vegetação. O diagnóstico de endocardite\nneste caso foi feito baseado em:","options":{"A":"Um critério maior + 3 critérios menores.","B":"Um critério maior + 4 critérios menores.","C":"Nenhum critério maior + 5 critérios menores.","D":"Nenhum critério maior + 3 critérios menores.","E":"Três critérios maiores + nenhum critério menor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-65751","number":"65751","sourceNumber":"65751","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma criança de quatro anos de idade apresenta lesões em ambas as pernas\ncaracterizadas como erupção vesicopustulosa,\nalgumas com crostas (VER IMAGEM). Além de\nantissépticos locais, qual o tratamento tópico mais adequado para essa afecção?","options":{"A":"Azitromicina.","B":"Tetraciclina.","C":"Gentamicina.","D":"Cloranfenicol.","E":"Ácido fusídico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-08/65751.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-51291","number":"51291","sourceNumber":"51291","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 10 anos, internado há 7 dias em UTI com quadro de broncopneumonia\ncomplicada por derrame pleural e\npneumatoceles, está usando antibioticoterapia apropriada ao\ncaso. Durante a infusão em 15 minutos de um dos antibióticos, subitamente apresenta eritema\nmultiforme-like, prurido intenso, rash envolvendo face, pescoço, parte superior do tronco e dos\nbraços, taquicardia e queda da pressão arterial média. Qual o diagnóstico e a fisiopatologia?","options":{"A":"Síndrome do homem vermelho, reação não mediada por IgE, devido à infusão de vancomicina\nacima de 20 mg/kg/h.","B":"Síndrome do homem vermelho, reação não mediada por IgE, devido à infusão de ceftriaxona\nacima de 20 mg/kg/h.","C":"Síndrome urticariforme, reação não mediada por IgE, devido à infusão de vancomicina abaixo de\n20 mg/kg/h","D":"Síndrome urticariforme, reação mediada por IgE, devido à infusão de ceftriaxona abaixo de 20\nmg/kg/h."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-141588","number":"141588","sourceNumber":"141588","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual das opções abaixo consiste em indicação de intervenção cirúrgica emergente (no\nmesmo dia) em pacientes com endocardite?","options":{"A":"Próteses instáveis.","B":"Endocardite fúngica.","C":"Perfuração de septo.","D":"Ruptura para o saco pericárdico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45383","number":"45383","sourceNumber":"45383","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considerando-se as meningites bacterianas na infância, é CORRETO afirmar:","options":{"A":"Crianças em tratamento, com quadro clínico estável e evolução favorável, a persistência da\nfebre indica mau prognóstico.","B":"Em lactentes, os sinais de irritação meníngea podem ser pouco evidentes e, em geral, são mais\ntardios nessa faixa etária.","C":"A quimioprofilaxia deve ser realizada em profissionais de saúde e contactantes de crianças com\nmeningites meningocócica e pneumocócica.","D":"Ao exame do fundo de olho, detecta-se frequentemente papiledema decorrente da hipertensão\nintracraniana.","E":"A coleção subdural ocorre na metade das crianças com meningite e é mais frequente na\nmeningite meningocócica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-37595","number":"37595","sourceNumber":"37595","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No tratamento de abscessos de partes moles, são indicações de uso de\nantibioticoterapia sistêmica, exceto:","options":{"A":"presença de febre, linfangite ou linfadenite.","B":"presença de múltiplos abscessos.","C":"em pacientes com diabetes.","D":"localização em face, couro cabeludo, região\ncervical, mãos, pés, genitais e/ou tronco."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-37420","number":"37420","sourceNumber":"37420","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação ao manejo da endocardite infecciosa, marque a opção CORRETA:","options":{"A":"Ecocardiograma transtorácico normal descarta o diagnóstico de EI.","B":"Sopro sistólico em foco tricúspide é o achado mais frequentemente encontrado em pacientes\ncom EI.","C":"A detecção de duas hemoculturas positivas com Streptococcus viridans em paciente com\nsuspeita de EI constitui-se em critério maior para o diagnóstico de endocardite infecciosa.","D":"Febre e nódulos de Osler são critérios maiores para o diagnóstico de EI.","E":"A válvula cardíaca mais frequentemente acometida em usuários de drogas injetáveis é a mitral."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-32509","number":"32509","sourceNumber":"32509","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um menino de 8 anos de idade, previamente hígido, apresenta uma história de três\nsemanas de febre de origem indeterminada,\nfadiga, perda de peso, mialgia e suores noturnos. Há 5\ndias, associou ao quadro clínico pequenos nódulos nas pontas dos dedos, sopro cardíaco,\npetéquias e esplenomegalia moderada. O diagnóstico mais provável é:","options":{"A":"Febre reumática.","B":"Leucemia aguda.","C":"Endocardite infecciosa.","D":"Tuberculose.","E":"Doença de Kawasaki."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-36962","number":"36962","sourceNumber":"36962","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Adolescente de 17 anos foi trazida para o dentista por apresentar descoloração do\nesmalte dentário. É provável que, na idade pré-escolar, ela tenha feito uso de qual dos\nmedicamentos abaixo?","options":{"A":"Cloranfenicol.","B":"Clindamicina.","C":"Tetraciclina.","D":"Quinolonas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-37403","number":"37403","sourceNumber":"37403","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Você está cuidando de um jovem portador de prótese valvar mitral metálica internado\nem um hospital. Durante a internação, ele\nnecessitará ser submetido a alguns procedimentos\ncirúrgicos ou diagnósticos invasivos. Para qual dos procedimentos abaixo a antibioticoprofilaxia da\nendocardite é melhor indicada?","options":{"A":"Colonoscopia.","B":"Sondagem vesical.","C":"Endoscopia digestiva alta.","D":"Colecistectomia por vídeo (colecistite crônica calculosa).","E":"Adenoamigdalectomia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-30893","number":"30893","sourceNumber":"30893","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente 82 anos, há 4 dias com cefaleia, febre e alterações do estado mental. No\nexame físico há discreta rigidez de nuca e\ndesidratação. O exame de bacterioscopia do liquor\nmostrou bastonetes gram-positivos. Qual das bactérias abaixo é o provável agente etiológico?","options":{"A":"Listeria monocytogenes.","B":"Staphylococcus aureus.","C":"Haemophilus influenzae.","D":"Neisseria meningitidis.","E":"Streptococcus pneumoniae."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-29441","number":"29441","sourceNumber":"29441","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Fármaco de escolha para o tratamento da otite média aguda, pois é seguro, bem\ntolerado e tem bom espectro de ação:","options":{"A":"Cefalexina;","B":"Amoxicilina","C":"Ceftriaxona:","D":"Eritromicina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-24383","number":"24383","sourceNumber":"24383","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Afonso, 18 anos, portador de cardiopatia congênita, necessita realizar a extração\ndentária dos terceiros molares (sisos). Seu\ndentista solicitou antibioticoprofilaxia pelo risco de\nendocardite infecciosa. No caso de Afonso, o esquema pode ter sido realizado à base de:","options":{"A":"Amoxicilina","B":"Sulfametoxazol + trimetoprim","C":"Gentamicina","D":"Amicacina"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27737","number":"27737","sourceNumber":"27737","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O pediatra de plantão é chamado a uma da manhã ao leito de um garoto de sete anos\ncom febre, há dois dias no hospital para\ntratamento e controle da dor de uma crise falciforme. A\ncriança está letárgica, mas sem desconforto respiratório agudo. Os sinais vitais são temperatura de\n39,7°C, pressão arterial 100/55 mmHg, frequência cardíaca de 100 bpm e frequência respiratória\n17 ipm. A pele é quente e úmida, e as conjuntivas estão claras. Não há sopro. Ausculta pulmonar\nnormal. Uma cicatriz cirúrgica recente e em boas condições é visível no quadrante superior\nesquerdo do abdome. O abdome é suave e indolor, sem massas. Hemograma de urgência: 33% de\nhematócrito, leucócitos totais de 16.000/mm³, e contagem de plaquetas 130.000/mm³. A\nhemocultura colhida neste momento é mais propensa a revelar, dentro de alguns dias, o seguinte\norganismo:","options":{"A":"Candida sp.","B":"Haemophilus influenzae tipo b.","C":"Pseudomonas aeruginosa.","D":"Salmonella sp.","E":"Streptococcus pneumoniae."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-24364","number":"24364","sourceNumber":"24364","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"\"Ocorre quando o agente está presente na superfície do organismo em quantidade\nmínima, multiplicando-se numa proporção suficiente para\nmanter-se, mas sem produzir evidência\nde qualquer reação do hospedeiro.\". Essa acepção técnica corresponde à:","options":{"A":"infecção.","B":"infestação.","C":"colonização.","D":"contaminação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9054","number":"9054","sourceNumber":"9054","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher de 23 anos, usuária de cocaína IV, chega à emergência sonolenta,\ndesorientada, taquipneica, com febre alta, dor\npleurítica bilateral e tosse produtiva com\nexpectoração sanguino-purulenta há 3 dias. Qual dos seguintes diagnósticos pode justificar o\nquadro acima?","options":{"A":"Endocardite por S. aureus","B":"Pneumonia por Mycoplasma","C":"Pneumonia por fungos associada ao HIV","D":"Sepse estreptocócica"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9059","number":"9059","sourceNumber":"9059","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual dos seguintes NÃO é um critério para definição de febre de origem obscura\n(FOO)?","options":{"A":"Temperaturas axilares acima de 37,9º C em várias ocasiões","B":"Leucograma normal em duas ou mais ocasiões","C":"Duração da febre por mais de 3 semanas","D":"Impossibilidade de estabelecer um diagnóstico a despeito de uma semana de internação\nhospitalar"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-6938","number":"6938","sourceNumber":"6938","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma criança com cetoacidose diabética apresenta: glicemia 500 mg/dL; sódio sérico\n126 mEq/L; potássio sérico 4 mEq/L; cloro 80\nmEq/L; ureia 16 mEq/L; e HCO3 6 mEq/L. A conduta\ninicial mais apropriada nesse caso é:","options":{"A":"Expansão com soro fisiológico e administração de insulina.","B":"Correção da hiponatremia com NaCl 3% intravenoso.","C":"Administração de bicarbonato para correção da acidose metabólica.","D":"Administração de insulina regular subcutânea conforme a glicemia.","E":"Expansão com Ringer Lactato que já corrige parcialmente a acidose metabólica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9069","number":"9069","sourceNumber":"9069","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Kerlianne, 3 anos, afrodescendente, mora em uma favela. As condições sanitárias de\nsua residência são bastante precárias.\nRecentemente, apresentou quadro abrupto de diarreia\nlíquida, seguida de febre elevada, cefaleia, acentuada palidez cutâneo-mucosa e sinais flogísticos\nem membro inferior direito, caracterizando uma osteomielite. Qual a provável etiologia do quadro\ndiarreico? Que outra patologia de base poderia estar associada? Por favor, marque a opção que,\nprovavelmente, envolve a etiologia da diarreia e a doença de base da garota?","options":{"A":"Rotavírus e Artrite reumatoide.","B":"Salmonella e Anemia falciforme","C":"Giardíase e Fibrose cística.","D":"Enterobiose e AIDS."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-349710","number":"349710","sourceNumber":"349710","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um jovem de 25 anos comparece à UBS com quadro de tosse há cerca de 3 semanas,\ncom relato de dispneia progressiva. Ele vive\ncom HIV (PVHIV), porém abandonou o tratamento há\ncerca de dois anos. Ao exame clínico, não há alterações na ausculta respiratória, porém ele\napresenta uma FR de 26 irpm e uma Sat O2 em ar ambiente de 93%, também apresenta febre de\n38,2°C ao exame clínico. Considerando o agente etiológico mais provável nesse paciente, qual é o\nachado radiológico esperado na radiografia de tórax?","options":{"A":"Opacidade irregular em ápice direito.","B":"Opacidade multilobular com níveis hidroaéreos.","C":"Infiltrado intersticial peri-hilar.","D":"Opacidade peri-hilar em vidro fosco.","E":"Inversão da trama vascular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284281","number":"284281","sourceNumber":"284281","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A tuberculose é endêmica no Brasil e o aumento da sua incidência nas últimas décadas\nestá relacionado à epidemia do vírus HIV. A\nrespeito dessas patologias, julgue o item a seguir.\n\nPacientes HIV+ com carga viral indetectável apresentam taxa de transmissão sexual entre 5 e 10%\na cada relação sexual desprotegida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284282","number":"284282","sourceNumber":"284282","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A tuberculose é endêmica no Brasil e o aumento da sua incidência nas últimas décadas\nestá relacionado à epidemia do vírus HIV. A\nrespeito dessas patologias, julgue o item a seguir.\n\nPacientes HIV+, com carga viral indetectável, CD4 de 86 e história prévia de neurocriptococose têm\nindicação de profilaxia secundária com fluconazol.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-274394","number":"274394","sourceNumber":"274394","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às características da infecção pelo vírus da imunodeficiência humana (HIV),\nem crianças, assinale a alternativa correta.","options":{"A":"Sem tratamento, o curso clínico da infecção pelo HIV é mais lento na criança em relação ao\nadulto.","B":"Os adolescentes que se infectaram por transmissão vertical, pelo uso crônico de regimes\nantirretrovirais, apresentam mais efeitos adversos como dislipidemia e lipodistrofia, além das\ncomplicações não infecciosas decorrentes da inflamação crônica causada pelo HIV.","C":"A infecção é, em geral, assintomática no período neonatal e o risco de progressão é diretamente\ncorrelacionado à idade da criança, ou seja, os mais jovens estão sob menor risco de progressão\nrápida.","D":"Em maiores de 5 anos, a progressão da doença e infecções oportunistas podem ocorrer mesmo\nquando apresentam contagens normais de células\nTCD+.","E":"O padrão de progressão lenta ocorre em grande parte das crianças infectadas no período\nperinatal, com progressão mínima ou nula da doença até o início da vida adulta."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-262440","number":"262440","sourceNumber":"262440","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ndiagnóstico da paciente é cistite não complicada, e os antibióticos recomendados para cistite não\ncomplicada em mulheres são fosfomicina trometamol (3 g por via oral, em dose única) e\nnitrofurantoína (100 mg por via oral, a cada seis horas, por cinco dias). Essas drogas têm\nmecanismos de ação únicos e baixas taxas de resistência. Também apresentam altas\nconcentrações urinárias e são ativos contra bactérias produtoras de betalacmase de espectro\nestendido (ESBL).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-262441","number":"262441","sourceNumber":"262441","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\npadrão-ouro para o diagnóstico de infecção do trato urinário (ITU) é uma cultura de urina positiva,\napesar de, no caso da paciente, não ser indicado coleta de material para cultura. A cultura de urina\ne o teste de sensibilidade aos antimicrobianos devem ser realizados em gestantes, mulheres com\nsuspeita de pielonefrite aguda e em infecções recorrentes, em razão do maior risco de resistência\nbacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-262442","number":"262442","sourceNumber":"262442","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. A\nITU recorrente é definida como a repetição de pelo menos três ITUs em seis meses. Em cada\nepisódio, o paciente deve apresentar sintomas agudos de início e bacteriúria ? 10 2 UFC/mL no\nexame de urina (EAS).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-262443","number":"262443","sourceNumber":"262443","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ndiagnóstico da irmã da paciente é de bacteriúria assintomática e não deve ser indicado tratamento\nantimicrobiano para ela. Atualmente, a indicação de tratamento de bacteriúria assintomática é\nconsenso apenas em duas situações: no caso de gestantes e antes de procedimento urológico\ninvasivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255677","number":"255677","sourceNumber":"255677","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de 55 anos de idade apresentou quadro de febre, mal-estar e dor\nabdominal difusa. Durante a investigação, foi diagnosticado abscesso hepático com ruptura\nintra-abdominal. A respeito desse caso clínico e tendo em vista os conhecimentos médicos\n\ncorrelatos, julgue o item a seguir. Ruptura de abscesso é raro e acontece com maior frequência em\nabscessos acima de 6 cm.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255695","number":"255695","sourceNumber":"255695","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Determinado paciente de 44 anos de idade está apresentando febre, mal-estar e\nhipoxemia importante. Durante ampla\ninvestigação, descobriu-se que o paciente é portador do vírus\nHIV. Realizou-se uma tomografia de tórax, que evidenciou lesão compatível com pneumocistose, e\numa gasometria arterial, que demonstrou uma PaO2 de 60. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Esse paciente pode receber\ncorticoterapia para auxiliar no tratamento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255759","number":"255759","sourceNumber":"255759","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Determinada primigesta de 20 anos de idade, sem parceiros sexuais fixos, com oito\nepisódios anuais de infecção urinária do trato inferior, buscou atendimento após um período de\ntempo, depois de sofrer estupro. Na consulta, refere desejo de abortar. Além disso, a paciente\napresenta lupus eritematoso sistêmico, com anti-RO positivo. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. No caso de infecções urinárias de\nrepetição, conforme a quantidade, deve-se realizar profilaxia, além de orientações específicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-196640","number":"196640","sourceNumber":"196640","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Determinada paciente de 16 anos de idade iniciou atendimento pré-natal em posto de\nsaúde da família e foi diagnosticada com\nHIV nas sorologias de primeiro trimestre, iniciando terapia\nantirretroviral adequada e com boa adesão imediatamente. Os demais exames de rotina de\n\npré-natal mostraram-se normais. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Crianças com\npeso de nascimento inferior a 1.500 g não devem\nfazer uso do AZT.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177563","number":"177563","sourceNumber":"177563","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. A presença de derrame pleural apontaria contra o diagnóstico firmado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177568","number":"177568","sourceNumber":"177568","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. Espera-se, nesse paciente, uma contagem de CD4 abaixo de 100.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177573","number":"177573","sourceNumber":"177573","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. A profilaxia para S. pneumoniae em pacientes HIV+ exige contagem de CD4 acima de 200.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177582","number":"177582","sourceNumber":"177582","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. A profilaxia para P. jiroveci é realizada com sulfametoxazol-trimetoprima diariamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177588","number":"177588","sourceNumber":"177588","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. Atualmente, a Organização Mundial da Saúde (OMS) recomenda que se considere a\nprescrição de tenofovir/emtricitabina (Truvada®) como forma de prevenção da infecção por HIV na\ncomunidade homossexual.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-134990","number":"134990","sourceNumber":"134990","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Logo após a coleta de sangue para exames laboratoriais de rotina em uma paciente\nportadora de HIV que apresentava carga viral\nelevada, uma auxiliar de enfermagem sofreu uma\nperfuração acidental na polpa digital com agulha que havia feito a coleta. Nesse caso, seguindo o\nesquema de profilaxia antirretroviral preconizado pelo Ministério da Saúde, a auxiliar de\nenfermagem deve ser submetida à seguinte quimioprofilaxia básica: AZT + 3TC (lamivudina) por\nvinte e oito dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45762","number":"45762","sourceNumber":"45762","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma criança de quatro anos é levada ao pronto-socorro por apresentar febre alta e\nvômitos há 12 horas. O exame físico revela criança irritada ao manuseio, febril (tax.: 39,8°C),\nlevemente desidratada e com rigidez de nuca. Feita punção lombar, observaram-se os seguintes\nresultados: 600 células (95% polimorfonucleares), proteína (55 mg/dl) e glicose (70 mg/dl). A\nrespeito desse caso, assinale a alternativa CORRETA.","options":{"A":"A introdução das vacinas conjugadas contra Haemophylus influenzae B e pneumococo não\ninterferiram na incidência da doença por esses germes.","B":"A quimioprofilaxia dos contactantes está indicada somente na suspeita de meningococo.","C":"Há indicação de se prescrever anticonvulsivante profilático.","D":"O tratamento de escolha nesse caso é a prescrição de ceftriaxona, na dosagem adequada, de\n24/24 horas.","E":"É rotina repetir a punção lombar após 24 horas para avaliar a eficácia do tratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-49168","number":"49168","sourceNumber":"49168","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de quarenta e dois anos de idade procurou atendimento médico em\nserviço de pronto atendimento, relatando que apresentava, havia seis dias, tosse produtiva com\nexpectoração piossanguinolenta de odor pútrido, astenia, dispneia e dor torácica\n\nventilatório-dependente. Informou ser etilista crônico. O exame físico mostrou dentes em precário\nestado de conservação e presença de murmúrio\nvesicular rude em hemitórax direito, sem ruídos\nadventícios ou outras anormalidades. A radiografia de tórax mostrou uma cavidade com paredes\nespessadas, com nível hidroaéreo, circundada por área de consolidação pulmonar no segmento\nsuperior do lobo inferior do campo pulmonar direito. Com base nesse caso clínico, julgue o item\nseguinte.: \"Deve-se recomendar a esse paciente tratamento antimicrobiano inicial com clindamicina\npor via intravenosa.\"","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-49171","number":"49171","sourceNumber":"49171","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de quarenta e dois anos de idade procurou atendimento médico em\nserviço de pronto atendimento, relatando que apresentava, havia seis dias, tosse produtiva com\nexpectoração piossanguinolenta de odor pútrido, astenia, dispneia e dor torácica\n\nventilatório-dependente. Informou ser etilista crônico. O exame físico mostrou dentes em precário\nestado de conservação e presença de murmúrio vesicular rude em hemitórax direito, sem ruídos\nadventícios ou outras anormalidades. A radiografia de tórax mostrou uma cavidade com paredes\nespessadas, com nível hidroaéreo, circundada por área de consolidação pulmonar no segmento\nsuperior do lobo inferior do campo pulmonar direito. Com base nesse caso clínico, julgue o item\nseguinte. A principal hipótese diagnóstica é abscesso pulmonar.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-32179","number":"32179","sourceNumber":"32179","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de 65 anos de idade foi atendido no pronto-socorro, história de início\nabrupto de febre havia 48 horas, evoluindo com\ncefaleia holocraniana e vômitos. No exame físico,\nencontrava-se com nível de consciência rebaixado e apresentava rigidez de nuca. A TC de crânio\nera normal. A melhor conduta, nesse caso, é:","options":{"A":"iniciar ampicilina e dexametasona imediatamente.","B":"realizar punção lombar e iniciar ceftriaxone com ampicilina.","C":"colher hemoculturas e iniciar ceftriaxone.","D":"iniciar ceftriaxone imediatamente.","E":"realizar punção lombar e aguardar resultado do exame do liquor para iniciar o tratamento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-32180","number":"32180","sourceNumber":"32180","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Lactente de sete meses de idade é levado ao pronto-socorro por apresentar choro e\nirritabilidade intensa havia seis horas, acompanhados de febre alta e vômitos em jato. Ao exame\nfísico, a criança estava pálida, com extremidades frias, choro intenso, fontanela anterior abaulada\ne\nrigidez de nuca evidente. Ausência de manchas ou petéquias pelo corpo. Com base nessa\nsituação, assinale a alternativa correta.","options":{"A":"A ceftriaxona é o antibiótico de primeira escolha para o caso em questão","B":"A frequência da doença descrita, causada pelo Haemophilus influenza tipo B, continua relevante,\napesar da introdução da vacina Hib no\ncalendário vacinal do Ministério da Saúde.","C":"A azitromicina na dose de 500 mg/dia, durante três dias, deve ser usada para os contactantes\nde pacientes com a doença descrita no caso,\nindependentemente do agente etiólogico.","D":"A reposição hidreletrolítica, mesmo na ausência de instabilidade hemodinâmica, deve ser feita\nprecocemente e em larga escala.","E":"É recomendável o uso de dexametasona (dose = 0,6 mg/kg/dia, quatro vezes ao dia)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-7546","number":"7546","sourceNumber":"7546","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de 49 anos de idade que relata poliúria, polidipsia e perda de peso\ninexplicável nos últimos meses, procura\navaliação médica para alívio dos sintomas. Na história\nclínica, refere ser filho de pais diabéticos e ter padrão alimentar inadequado (horários\nirregulares e\ningestão de alimentos hipercalóricos). Ao exame físico evidenciado: peso 128 Kg e altura 170 cm.\nPresença de acantose nigrans cervical. Circunferência abdominal 130 cm. PA: 140 x 100 mmHg.\nExames complementares: glicose plasmática de jejum 150 mg/dl e glicose plasmática pós-prandial\n(2h) 200 mg/dl. Com base nessa situação hipotética, assinale a alternativa correta.","options":{"A":"O tratamento inicial deve constar de orientações para perda de peso e início de metformina.","B":"O tratamento da hiperglicemia pós-prandial, neste caso, não influencia na prevenção das\ncomplicações macro e microvasculares do diabetes.","C":"A metformina pode gerar acidose lática e efeitos cardíacos adversos como aumento do risco de\ninfarto do miocárdio.","D":"Estudos mostram que a redução da pressão arterial nesses pacientes, não reduz as\ncomplicações cardiovasculares.","E":"O objetivo primário para LDL-c nesse paciente deve ser < 130mg/dl, conforme as diretrizes da\nSociedade Brasileira de Diabetes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-352393","number":"352393","sourceNumber":"352393","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para\no vírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. A PrEP para o HIV é de grande\nrelevância mundial, uma vez que tem um impacto direto na busca pela meta 95-95-95 da OMS para\no controle da HIV/AIDS até 2030. Apesar de historicamente o Brasil não conseguir atingir todas as\nmetas estabelecidas, tem apresentado resultados mais satisfatórios do que a média global.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-334880","number":"334880","sourceNumber":"334880","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de 36 anos de idade procurou o pronto-socorro apresentando episódio de\nconvulsão há 30 minutos. Informou ter o diagnóstico de síndrome da imunodeficiência humana. A\ntomografia computadorizada de crânio revelou lesões múltiplas localizadas nos gânglios da base. À\ncausa mais provável da lesão neurológica descrita é","options":{"A":"meningite viral.","B":"tuberculose.","C":"tumor maligno cerebral.","D":"neurocisticercose.","E":"toxoplasmose."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-307111","number":"307111","sourceNumber":"307111","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às imunodeficiências primárias que atualmente são denominadas erros\ninatos da imunidade, assinale a alternativa correta. Alternativas:","options":{"A":"Um episódio de molusco contagioso deve ser sempre investigado.","B":"A imunodeficiência combinada grave é uma deficiência da imunidade celular.","C":"Otite externa de repetição é um sinal de alerta.","D":"Atraso do desenvolvimento deve ser investigado no segundo ano de vida.","E":"Helmintíase isolada pode ser um sinal clínico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-273311","number":"273311","sourceNumber":"273311","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Marque a alternativa que corresponde a sinal de alerta para Imunodeficiência primária\nna criança:","options":{"A":"Três ou mais infecções virais de vias aéreas nos dois primeiros anos de vida.","B":"Duas pneumonias graves em um ano.","C":"Dengue grave com choque hemorrágico.","D":"Cicatriz vacinal após BCG."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-291461","number":"291461","sourceNumber":"291461","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem de 37 anos de idade com aids/HIV diagnosticado há 3 anos compareceu à\nconsulta com o médico da UBS próxima de sua casa, trazendo resultados de exames solicitados na\nconsulta anterior. O teste rápido molecular para tuberculose feito no escarro confirmou o\ndiagnóstico de tuberculose pulmonar e sensibilidade à rifampicina. A carga viral para HIV\napresentou resultado de 98.000 cópias por mililitro. Nessa situação, o médico deverá:","options":{"A":"Avaliar eventual resistência do HIV aos antirretrovirais em uso para depois desse resultado\niniciar o tratamento da tuberculose.","B":"Avaliar eventual resistência do HIV aos antirretrovirais em uso, sem atrasar início do tratamento\nda tuberculose.","C":"Avaliar se eventual resistência aos antirretrovirais não é necessária, pois a carga viral está\nabaixo de 100.000 cópias.","D":"Avaliar eventual resistência do HIV através da quantificação de linfócitos CD4."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-291532","number":"291532","sourceNumber":"291532","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente, em tratamento para infecção por HIV há 5 anos, com boa aderência ao\ntratamento e carga viral indetectável em exame realizado há 1 mês, procurou a Unidade Básica de\nSaúde para consulta médica. O médico no atendimento verificou que o paciente trouxe resultado de\nexame de escarro que mostrou a presença de bacilo álcool ácido resistente (valor de referência:\nnegativo) feito há 10 dias. Foi verificado que a cultura ainda não havia ficado pronta. Frente a\nesse\ncaso, o médico deveria:","options":{"A":"Suspender o tratamento contra a infecção pelo HIV e iniciar o tratamento de tuberculose.","B":"Manter o tratamento contra a infecção pelo HIV e iniciar o tratamento de tuberculose antes do\nresultado da cultura.","C":"Suspender o tratamento contra a infecção pelo HIV e iniciar o tratamento de tuberculose apenas\napós o resultado da cultura.","D":"Suspender o tratamento contra a infecção pelo HIV e iniciar o tratamento de tuberculose de\nimediato."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-203133","number":"203133","sourceNumber":"203133","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma lactente de 4 meses de vida com diagnóstico de imunodeficiência congênita\ncombinada grave precisa realizar atualização do\ncartão vacinal, pois não recebeu qualquer dose de\nvacina desde a alta da maternidade. Com base nesse caso clínico, assinale a alternativa que\napresenta as vacinas indicadas para essa paciente.","options":{"A":"Vacina poliomelite 1, 2, 3 inativada, pneumocócica 23-valente, meningocócica C.","B":"Tríplice bacteriana (DTPw), vacina poliomelite 1, 2, 3 inativada, rotavírus.","C":"Vacina poliomelite 1, 2, 3 inativada, rotavírus, meningocócica C.","D":"Tríplice bacteriana (DTPw), pneumocócica 23-valente, rotavírus.","E":"Tríplice bacteriana (DTPw), rotavírus, meningocócica C."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-206081","number":"206081","sourceNumber":"206081","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Somente não podemos determinar a relação de, nas Pessoas Vivendo com HIV\n(PVHIV) com lesões ósseas, o seguinte item:","options":{"A":"A osteomalácia é um defeito na mineralização óssea devido a uma quantidade inadequada de\ncálcio, somente.","B":"Embora raramente, é associado à TDF, pelo efeito no metabolismo do fósforo e a EFV, pelo\ncomprometimento do metabolismo da vitamina D.","C":"Outros fatores associados a deficit de vitamina D são pele escura, má nutrição, pouca exposição\nà luz solar, má absorção, obesidade e doença\nrenal crônica.","D":"A osteomalácia leva à dor óssea, fraqueza muscular, baixa massa óssea e, eventualmente,\nfraturas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-206150","number":"206150","sourceNumber":"206150","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Fica determinado que a Secretaria de Vigilância em Saúde adote as medidas\nnecessárias ao cumprimento efetivo do disposto\nnesta Instrução Normativa. Sendo que se deve\ncumprir o seguinte:","options":{"A":"em todo o processo de abordagem consentida aos usuários que não comparecem aos serviços\nde saúde para conhecimento dos resultados de\nexames realizados para HIV e outras DST, ou que\nnão estejam comparecendo ao tratamento, deverá ser mantida a confidencialidade das informações\ndo usuário.","B":"em todo o processo de abordagem consentida aos usuários que comparecem aos serviços de\nsaúde para conhecimento dos resultados de\nexames realizados para HIV e outras DST, ou que\nestejam comparecendo ao tratamento, não deverá ser mantida a confidencialidade das informações\ndo usuário.","C":"em todo o processo de abordagem consentida aos usuários que não comparecem aos serviços\nde saúde para conhecimento dos resultados de\nexames realizados para HIV e outras DST, ou que\nnão estejam comparecendo ao tratamento, não deverá ser mantida a confidencialidade das\ninformações do usuário.","D":"em todo o processo de abordagem consentida aos usuários que não comparecem aos serviços\nde saúde para conhecimento dos resultados de\nexames realizados para HIV e outras DST, ou que\nnão estejam comparecendo ao tratamento, deverá ser mantida a não confidencialidade das\ninformações do usuário para parceiro sexual."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183908","number":"183908","sourceNumber":"183908","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Acerca das infecções e suas implicações clínico-cirurgícas, julgue o próximo item. As\nprincipais causas de morte por HIV/AIDS são infecções oportunistas e câncer, ambos resultantes\nda falência progressiva do sistema imunitário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183873","number":"183873","sourceNumber":"183873","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A respeito de doenças infecciosas e transmisssíveis, julgue o item seguinte. O risco de\ncontaminação pelo HIV é maior entre os portadores de outras doenças infecciosas sexualmente\ntransmissíveis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-183880","number":"183880","sourceNumber":"183880","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A respeito de doenças infecciosas e transmisssíveis, julgue o item seguinte. No Brasil, o\ntratamento medicamentoso para pessoas portadoras de HIV está indicado apenas para os casos\nsintomáticos da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-158048","number":"158048","sourceNumber":"158048","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 27 anos de idade inicia acompanhamento médico após o diagnóstico de\nHIV, já devidamente confirmado.\nEncontra-se assintomático e já leva exames demonstrando CD4 -\n422 células/mm³. Na abordagem, mostra bom entendimento da doença e demonstra ansiedade em\niniciar prontamente a terapia antirretroviral (TARV). Após as explicações necessárias acerca da\nTARV, o paciente conta que pesquisou muito as doenças oportunistas que poderia ter em razão do\nHIV, questionando acerca da necessidade de iniciar as profilaxias para essas infecções.\n\nConsiderando o caso clínico apresentado, o microrganismo contra o qual se deve realizar a\nprofilaxia nesse paciente é o:","options":{"A":"P. jirovecii.","B":"T. gondii.","C":"S. pneumoniae.","D":"CMV.","E":"M. avium."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-158057","number":"158057","sourceNumber":"158057","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 27 anos de idade foi levado ao pronto-socorro em razão de perda\nprogressiva da capacidade de realizar\natividades laborais e domiciliares em contexto de meses,\nacompanhada por sonolência e cefaleia constantes. Foi realizada tomografia computadorizada em\nregime de urgência, com laudo ainda não disponível, representada a seguir. Com base nas\ninformações apresentadas, assinale a alternativa que indica, respectivamente, a melhor hipótese\ndiagnóstica para esse caso e um exame que a reforçaria:","options":{"A":"Tuberculoma cerebral - biópsia da lesão.","B":"Neurotoxoplasmose - anti-HIV.","C":"Neurocisticercose - exame parasitológico de fezes.","D":"Abscesso cerebral - punção de liquor com citológico diferencial.","E":"Astrocitoma - biópsia de lesão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-168518","number":"168518","sourceNumber":"168518","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem com 55 anos de idade procura atendimento em Unidade Básica de Saúde\n(UBS) por apresentar furunculose de\nrepetição. Durante a investigação de fator predisponente,\ncogita-se a possibilidade de infeção pelo vírus da imunodeficiência humana (HIV). O paciente relata\nque não tem filhos e vive em união estável há cerca de 20 anos, Nega uso de preservativo nas\nrelações sexuais com sua perceira e afirma não ter relacionamentos extraconjugais. Refere quatro\nparceiras prévias à atual e afirma que sempre fez uso de preservativo nas relações sexuais com\nessas parceiras. Nega transfusões sanguíneas ou cirurgias prévias. Em face desse quadro, o\nmédico deve","options":{"A":"solicitar sorologia anti-HIV, sem ser necessário pedir autorização do paciente; e, sendo a\nsorologia positiva, iniciar o tratamento\nantirretroviral se a contagem de linfócitos T CD4+ for \"menor\nou igual\" 350 células/mm³, nada devendo informar à parceira, de modo a manter o sigilo médico\nrecomendado pelo Código de Ética Médica.","B":"solicitar sorologia anti-HIV, caso autorizado pelo paciente após o aconselhamento pré-teste, e,\nsendo positiva, iniciar o tratamento antirretroviral se a contagem de linfócitos T CD4+ for \"menor\nou\nigual\" 500 células/mm³, e solicitar, ainda, que o paciente leve sua parceira à UBS, para\noferecer-lhe\naconselhamento e testagem anti-HIV.","C":"solicitar sorologia anti-HIV, caso autorizado pelo paciente após aconselhamento pré-teste, e,\nsendo positiva, iniciar o tratamento\nantirretroviral se a contagem de linfócitos T CD4+ for \"menor ou\nigual\" 500 células/mm³, e, ainda, convocar, de imediato, a parceira do paciente para\naconselhamento e testagem, comunicando-lhe o diagnóstico do parceiro.","D":"solicitar sorologia anti-HIV, sem haver necessidade de pedir autorização ao paciente, e, sendo a\nsorologia positiva, iniciar o tratamento antirretroviral se a contagem de linfócitos T CD4+ for\n\"menor\nou igual\" 350 células/mm³, e, ainda, aguardar a oportunidade de testagem da parceira do paciente,\nem ida dela à UBS, para comunicar-lhe o diagnóstico do parceiro."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111269","number":"111269","sourceNumber":"111269","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os fenômenos retratados abaixo são manifestações características do seguinte quadro\ninfeccioso: (VER IMAGEM).","options":{"A":"Pneumonia por Pneumococcus.","B":"Diabetes descompensada.","C":"Sífilis.","D":"Endocardite por Staphylococcus aureus.","E":"Osteomielite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111303","number":"111303","sourceNumber":"111303","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Assinale a alternativa correta, com relação à infecção urinária na gravidez.","options":{"A":"A bacteriúria assintomática é diagnosticada quando existe mais de 100 000 leucócitos/ml no\nexame de urina.","B":"A Escherichia coli é o agente etiológico mais comum na gravidez.","C":"Deve-se sempre aguardar a urocultura, para que o tratamento seja mais adequado.","D":"Nos casos graves, a internação da paciente é opcional.","E":"O tratamento da bacteriúria assintomática é desnecessário, já que não representa infecção."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111349","number":"111349","sourceNumber":"111349","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Criança de 3 anos de idade dá entrada no pronto socorro com história de febre alta\nhá 1 dia, acompanhada de vômitos. Ao exame, encontra-se em MEG, obnubilada, com rigidez de\nnuca e lesões de pele compatíveis com vasculite. Enchimento vascular > 3 seg, PA = 40/20mmHg,\nT= 39,5? C. Com base no quadro apresentado, você pode afirmar:","options":{"A":"É certamente um quadro de meningite\n\nmeningocóccica, devendo iniciar Penicilina Cristalina em altas doses e coleta de líquor para\nanálise.\nIniciar profilaxia a familiares e\nprofissionais do PS com Rifampicina. Internamento em isolamento.","B":"O quadro é compatível com meningite bacteriana e choque séptico, devendo ser iniciada\ncefalosporina de 3ª geração, precedida de\ndexametasona e infusão rápida de solução fisiológica EV\n20 a 100 ml/kg/hora. Providenciar vaga em UTIP.","C":"O quadro é de meningite bacteriana e choque\n\nhipovolêmico. Solicita vaga em UTIP enquanto hidrata a criança com Solução Fisiológica 4 ml/kg/h\ne aguarda líquor para definir antibiótico a ser\nutilizado.","D":"É certamente meningite bacteriana com falência de suprarrenal, devendo iniciar Hidrocortisona\nimediatamente e Penicilina Cristalina em altas doses. Internar em isolamento.","E":"O quadro é de CIVD secundária a meningite por meningococo, seguindo a sequência iniciar\nCefalosporina de 3ª geração, colher líquor, fazer volume para choque na forma de plasma fresco,\niniciar corticosteróide EV e solicitar vaga na UTIP."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-64440","number":"64440","sourceNumber":"64440","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os germes anaeróbicos têm importante papel nas infecções abaixo, EXCETO:","options":{"A":"Ferida por mordidas de animais","B":"Endometrite","C":"Periodontite","D":"Diverticulite","E":"Pneumonia hospitalar"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-137563","number":"137563","sourceNumber":"137563","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma mulher de 23 anos de idade, casada, do lar e nuligesta, iniciou atividade sexual há\n3 anos, após casamento. No momento, essa\nmulher está em tratamento para condilomatose vulvar\nem uma Unidade Básica de Saúde (UBS) e apresenta boa evolução. Ela não mantém relações\nextraconjuguais, seu marido é saudável e não tem histórico de doença sexualmente transmissível\n(DST) e (ou) uso de drogas injetáveis. Após aconselhamento, realizou sorologia para HIV e o\nresultado foi positivo. Diante disso, foi solicitada pesquisa sorológica para HIV em nova amostra\nsanguínea. A paciente retorna hoje à UBS para conhecer o resultado. Ambas as amostras foram\nprocessadas no mesmo laboratório e seus resultados são apresentados nas figuras a seguir (VER\nIMAGENS). Nessa situação, que conduta deve ser adotada para a paciente?","options":{"A":"Solicitar contagem de linfócitos T- CD4+.","B":"Solicitar contagem de linfócitos T - CD4+ e a quantificação da Carga Viral do HIV.","C":"Encaminhar a paciente para o Serviço de Assistência Especializada em DST/AIDS.","D":"Solicitar análise sorológica para HIV, em uma nova amostra sanguínea, pela técnica de Western\nBlot.","E":"Solicitar análise sorológica para HIV, em uma nova amostra sanguínea, pela técnica de\nImunofluorescência indireta."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-30965","number":"30965","sourceNumber":"30965","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma paciente com 25 anos de idade com diagnóstico prévio de insuficiência mitral\nreumática e que nega alergia à penicilina, foi admitida em hospital terciário em razão de\nendocardite infecciosa. Durante a evolução do seu quadro clínico, a paciente apresentou cefaleia\nintensa e pulsátil, sonolência e hemianopsia. A angiotomografia computadorizada do crânio com\ncontraste mostrou a presença de aneurisma micótico em ramo da artéria cerebral média. Com\nrelação a essa condição clínica, julgue o item. Considere que essa paciente tenha recebido alta\nhospitalar e que, após 6 meses, necessite realizar uma extração dentária. Nesse caso, deve-se\nobrigatoriamente fazer a profilaxia para endocardite infecciosa com amoxicilina, 2 gramas, por via\noral, 30 minutos a 60 minutos antes do procedimento dentário.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-30966","number":"30966","sourceNumber":"30966","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente com 25 anos de idade com diagnóstico prévio de insuficiência mitral\nreumática e, que nega alergia à penicilina,\nfoi admitido em hospital terciário em razão de\nendocardite infecciosa. Durante a evolução do seu quadro clínico, o paciente apresentou cefaleia\nintensa e pulsátil, sonolência e hemianopsia. A angiotomografia computadorizada do crânio com\ncontraste mostrou a presença de aneurisma micótico em ramo da artéria cerebral média. Com\nrelação a essa condição clínica, julgue o item. Nesse caso, deve-se imediatamente associar ao\ntratamento em curso um antimicrobiano com ação sobre fungos, como a anfotericina B lipossomal.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-138568","number":"138568","sourceNumber":"138568","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A enfermeira de uma equipe de Saúde da Família aborda o médico para saber o que\ndeve ser feito com um paciente que atendeu\nhoje. Trata-se de homem recém-chegado do interior,\nem tratamento para tuberculose e AIDS. O relatório trazido por ele informa que há cinco anos\niniciou terapia antiretroviral. Há seis meses iniciou tratamento para tuberculose, não tendo\napresentado intolerância a nenhum medicamento. A medida a ser adotada em relação ao paciente\né","options":{"A":"dar continuidade ao dois tratamentos sob\nresponsabilidade da equipe de Saúde da Família.","B":"dar continuidade apenas ao tratamento antiretroviral, pois a tuberculose já foi adequadamente\ntratada (seis meses).","C":"prolongar o esquema de tratamento para tuberculose para doze meses.","D":"investigar situação dos comunicantes quanto à tuberculose, como forma indireta de avaliar a\nadesão do paciente ao tratamento.","E":"encaminhar o paciente para tratamento conjunto\n\ncom os serviços de referência local de DST/AIDS e de tuberculose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-354104","number":"354104","sourceNumber":"354104","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação a infecção pelo vírus da imunodeficiência humana, a doença pode ou não\nter expressão clínica logo após a infecção,\nsendo importante que o profissional saiba conduzir a\ninvestigação laboratorial após a suspeita de risco de infecção pelo HIV. Além disso, é\nimprescindível conhecer o conceito de janela diagnóstica que é o...","options":{"A":"intervalo compreendido entre o início do estagiamento laboratorial da infecção pelo HIV até o\ninício dos sintomas conforme detecção dos marcadores, seja ele RNA viral, DNA proviral, antígeno\np24 ou anticorpo.","B":"tempo entre o exame de carga viral, para fins diagnósticos, e o teste de detecção do dos\nmarcadores, seja ele RNA viral, DNA proviral, antígeno p24 ou anticorpo.","C":"tempo entre o teste rápido com amostras obtidas por punção venosa (sangue total, soro ou\nplasma) e a detecção dos marcadores, seja\nele RNA viral, DNA proviral, antígeno p24 ou anticorpo.","D":"tempo decorrido entre a infecção e o aparecimento ou detecção de um marcador da infecção,\nseja ele RNA viral, DNA proviral, antígeno p24\nou anticorpo.","E":"intervalo entre a primo infecção da mãe e o aparecimento de sintomas no concepto a partir da\ndetecção dos marcadores seja, ele RNA viral, DNA proviral, antígeno p24 ou anticorpo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-359215","number":"359215","sourceNumber":"359215","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na avaliação clínica do paciente com suspeita de infecção por HIV, deve-se considerar\nalguns conceitos e conhecimentos. Sobre o\nassunto, assinale a alternativa INCORRETA.","options":{"A":"Na possibilidade de infecção aguda ou recente pelo HIV, deve-se realizar investigação com\ntestes de muito alta sensibilidade, como\ndosagem viral por RT-PCR. A associação de testes como\nantígeno e anticorpo neste momento, podem ser úteis para confirmar infecção recente, como no\ncaso de testes negativos.","B":"Na suspeita de infecção recente, com viremia negativa e antígeno/anticorpo negativos, a\nprobabilidade de infecção pelo HIV é baixa, mas a suspeição clínica em casos de exposição muito\nrecente pode exigir outro teste, devendo ser realizado em 1-2 semanas.","C":"Os algoritmos mais recentes têm tornado a investigação de HIV cada vez mais ampla e\nfavorecendo o diagnóstico precoce ou em fase aguda, o que aumenta taxa de tratamento\nantirretroviral, reduz sintomas causados pelo HIV e, considerando a evolução dos tratamentos,\naumenta o número de casos de doença controlada e aumento de erradicação.","D":"Em pacientes em uso de PrEP, a detecção de viremia com poucas cópias virais, mesmo que\nacima de 100 cópias/ml, devem sofrer\nconfirmação antes do início de terapia antirretroviral pela alta\ntaxa de falsos positivos, considerando a sensibilidade do método."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-345695","number":"345695","sourceNumber":"345695","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O mecanismo da patogênese do HTLV-1 ainda não é totalmente compreendido.\nPodemos indicar como correto que:","options":{"A":"Entre todas as proteínas regulatórias codificadas pelo DNA pro viral, as proteínas TAX e HBZ\nnão são essenciais para a manutenção da\npersistência viral e para a patogênese, atuando, por\nmeio da indução do crescimento celular associado a uma forte vigilância imunológica.","B":"Entre todas as proteínas regulatórias codificadas pelo DNA pro viral, as proteínas TAX e HBZ\nsão essenciais para a manutenção da persistência\nviral e para a patogênese, atuando, por meio da\nindução do crescimento celular associado a uma forte vigilância imunológica.","C":"Entre todas as proteínas regulatórias codificadas pelo DNA pro viral, as proteínas TAX e HBZ\nsão essenciais para a manutenção da persistência\nviral e para a patogênese, atuando, por meio da\nindução do crescimento celular nunca associado a uma forte vigilância imunológica.","D":"Entre todas as proteínas regulatórias codificadas pelo DNA pro viral, as proteínas TAX e não a\nHBZ são essenciais para a manutenção da persistência viral e para a patogênese, atuando, por\nmeio da indução do crescimento celular associado a uma forte vigilância imunológica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-345696","number":"345696","sourceNumber":"345696","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A intensidade da resposta imunológica e a ativação da HBZ definem o tipo de\ncomportamento da infecção pelo HTLV-1. Sendo correto que:","options":{"A":"Nunca foi reportada a correlação entre a compartimentação intracelular da HBZ com o desfecho\nclínico da infecção, tendo-se proposto que\na presença citoplasmática de HBZ em leucócitos de\npacientes com HAM seria um biomarcador de progressão da doença.","B":"Foi reportada a correlação entre a compartimentação intracelular da HBZ com o desfecho clínico\nda infecção, tendo-se proposto que a presença\ncitoplasmática de HBZ em leucócitos de pacientes\ncom HAM não seria um biomarcador de progressão da doença.","C":"Foi reportada a correlação entre a compartimentação intracelular da HBZ com o desfecho clínico\nda infecção, tendo-se proposto que a presença\ncitoplasmática de HBZ em leucócitos de pacientes\ncom HAM seria um biomarcador de progressão da doença.","D":"Foi reportada a correlação entre a compartimentação intracelular da HBZ com o desfecho clínico\nda infecção, tendo-se proposto que a presença\ncitoplasmática de HBZ em hemácias de pacientes\ncom HAM seria um biomarcador de progressão da doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-345700","number":"345700","sourceNumber":"345700","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O HTLV-1 infecta diferentes tipos celulares: células dendríticas, macrófagos, monócitos,\nlinfócitos T CD8+.","options":{"A":"Principalmente, os linfócitos T CD4+, que não funcionam como reservatórios para o vírus.","B":"Principalmente, os linfócitos T CD4+, que funcionam como reservatórios para o vírus.","C":"Exceto, os linfócitos T CD4+, que funcionam como reservatórios para o vírus.","D":"Principalmente, os linfócitos T CD4+, que funcionam como barreira para o vírus."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-345703","number":"345703","sourceNumber":"345703","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Nos linfócitos T CD4+, o HTLV-1 pode permanecer latente por um longo período:","options":{"A":"Mantendo uma taxa baixa de replicação, o que pode causar alterações genéticas, induzir\nproliferação celular ou mesmo provocar lesão do\nsistema nervoso central (SNC) a partir de uma\nresposta imune inflamatória.","B":"Mantendo uma taxa baixa de replicação, o que não pode causar alterações genéticas, induzir\nproliferação celular ou mesmo provocar lesão do sistema nervoso central (SNC) a partir de uma\nresposta imune inflamatória","C":"Mantendo uma taxa elevada de replicação, o que pode causar alterações genéticas, induzir\nproliferação celular ou mesmo provocar lesão do sistema nervoso central (SNC) a partir de uma\nresposta imune inflamatória","D":"Mantendo uma taxa baixa de replicação, o que pode causar alterações genéticas, mas não\ninduzir proliferação celular ou mesmo provocar\nlesão do sistema nervoso central (SNC) a partir de\numa resposta imune inflamatória"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-320434","number":"320434","sourceNumber":"320434","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Lactente, 1 ano e 5 meses, apresenta, desde os 7 meses de vida, otites de repetição (5\nepisódios, sendo três episódios com supuração). Seu crescimento pôndero-estatural é normal, mas\no pediatra encaminha para o imunologista por suspeita de imunodeficiência primária do tipo celular.\nEsse encaminhamento se justifica?","options":{"A":"Sim, mas a suspeita é de imunodeficiência primária do sistema complemento.","B":"Sim, mas a suspeita é de imunodeficiência primária humoral.","C":"Não, já que a hipogamaglobulinemia fisiológica é comum até? dois anos.","D":"Não, pois não veremos imunodeficiência primaria após os seis meses de vida.","E":"Não, pois é comum a criança nos dois primeiros anos de vida apresentar 10 ou mais infecções\nbacterianas"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-313296","number":"313296","sourceNumber":"313296","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"De acordo com o Ministério da Saúde, a associação de fibrato com estatina com a\nTerapia antirretroviral ? TARV promove o aumento do risco de:","options":{"A":"Enterite necrotizante","B":"Arritmias cardíacas.","C":"Rabdomiólise.","D":"Hepatotoxicidade.","E":"Efeitos tromboembólicos periféricos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-313303","number":"313303","sourceNumber":"313303","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Para uma jovem de 19 anos, solteira, sem filhos, sexualmente ativa, que procura a\nUnidade Básica de Saúde para exames de rotina, o Médico faz alguns encaminhamentos e\nsolicitação de exames laboratoriais. Após a avaliação do leucograma, o Médico da Família relata à\njovem, sobre a necessidade de investigação de possível infecção pelo HIV. Qual achado levou o\nmédico a essa conduta:","options":{"A":"Eosinofilia.","B":"Presença de granulação tóxica.","C":"Hipersegmentação de neutrófilos.","D":"Presença de células de Mott.","E":"Presença de vacúolos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-314090","number":"314090","sourceNumber":"314090","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As imunodeficiências primárias (IDP) são um grupo heterogêneo de doenças\ncongênitas, caracterizadas por disfunção de um ou\nmais componentes do sistema imunológico,\nocasionando infecções recorrentes, principal manifestação clínica dessas doenças. Em relação aos\nprincipais grupos de IDP, suas características, tipos de infecções e germes mais comuns, numerar\na 2ª coluna de acordo com a 1ª e, após, assinalar a alternativa que apresenta a sequência\nCORRETA: (1) Defeitos predominantemente de anticorpos. (2) Defeitos da imunidade celular\n(células T). (3) Defeitos de complemento. ( ) Predisposição para infecções graves causadas por\npatógenos intracelulares, como microbactérias, Salmonella sp, vírus, fungos, protozoários e germes\noportunistas como Pneumocystis jirovecii. Comorbidades podem frequentemente estar associadas,\ncomo rash neonatal, alterações neurológicas, diarreia persistente e falência de crescimento\nponderoestatural, especialmente nos casos de imunodeficiência combinada grave. ( ) Podem estar\nassociados a quadros autoimunes (vasculites, lúpus eritematoso sistêmico, entre outros) e\ninfecções por bactérias capsuladas. Deficiências dos componentes terminais do complemento (que\ncompõem o complexo de ataque à membrana) predispõem às infecções graves causadas por\nNeisseria sp, como meningites, artrites, uretrites e quadros sépticos. ( ) Suscetibilidade aumentada\npara infecções do trato respiratório (oto-sino-pulmonares) causadas por bactérias extracelulares\ncapsuladas, como Streptococcus pneumoniae, Haemophilus influenzae tipo b, Moraxella sp);\ninfecções gastrointestinais (diarreia crônica) causadas por enterovírus e Giardia lamblia; e outros\nsítios e patógenos, como artrites sépticas causadas por Mycoplasma sp.","options":{"A":"1 - 2 - 3.","B":"3 - 2 - 1.","C":"2 - 3 - 1.","D":"2 - 1 - 3.","E":"3 - 1 - 2."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-257343","number":"257343","sourceNumber":"257343","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 37 anos recebe o diagnóstico de infecção pelo HIV. É assintomático e nega\ncomorbidades ou uso regular de medicamentos. Já teve tuberculose e gonorreia, tratados\nadequadamente, ambos há mais de 5 anos. O exame físico não apresenta anormalidades. O\nmédico fará avaliação para início da terapia antirretroviral. Assinale a alternativa que apresenta\num\nexame que NÃO está indicado para esse paciente nessa consulta:","options":{"A":"Creatinina.","B":"Dosagem de linfócitos CD4.","C":"Teste tuberculínico.","D":"VDRL."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-287334","number":"287334","sourceNumber":"287334","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Iniciar o tratamento do paciente portador de HIV com TARV (terapia antirretroviral) deve\nser considerado prioridade em alguns casos,\nEXCETO:","options":{"A":"Linfócito T -CD4+ <350 céls/mm³.","B":"Paciente gestante.","C":"Tuberculose latente.","D":"Risco cardiovascular elevado (>20%)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-266376","number":"266376","sourceNumber":"266376","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação ao manejo adequado das infecções pelo HIV, é correto afirmar:","options":{"A":"Na abordagem ambulatorial inicial do paciente, a história familiar a ser colhida deve ser voltada\npara a presença de diabetes mellitus e\ndoenças cardiovasculares na família; a presença de\nneoplasias malignas nesse contexto é irrelevante.","B":"Na ectoscopia do paciente, o achado de dermatite seborreica pode ser indicador de infecção por\nHIV, assim como lesões extensas de psoríase.","C":"Paciente que já iniciou terapia antirretroviral e faz uso regular da mesma, com carga viral\nindetectável e CD4 acima de 350 deve dosar carga viral e CD4 a cada 6 meses.","D":"Deve ser realizado PPD apenas na abordagem inicial no caso de pacientes cuja medida do\nmesmo foi inferior a 5mm."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-260684","number":"260684","sourceNumber":"260684","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Lactente, 14meses, apresenta desde os cinco meses otites de repetição (5 episódios)\nsendo quatro episódios com supuração. O pediatra\nencaminha para o imunologista por suspeita de\nimunodeficiência primária do tipo celular. Esse encaminhamento se justifica:","options":{"A":"Não, já que a hipogamaglobulinemia fisiológica é comum até dois anos.","B":"Sim, mas a suspeita é de imunodeficiência primária humoral.","C":"Sim, mas a suspeita é de imunodeficiência primária do sistema complemento.","D":"Não, pois não veremos imunodeficiência primária após os seis meses de vida","E":"Não, pois não ocorreu nenhum episódio de infecção associado a internação hospitalar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-287876","number":"287876","sourceNumber":"287876","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os critérios para definição de caso de Aids, em indivíduos com 13 anos de idade ou\nmais (critério CDC adaptado), são a evidência do diagnóstico de infecção pelo HIV por teste\nsorológico ou virológico e:","options":{"A":"Menção de Aids/Sida em algum campo da Declaração de Óbito ou menção e investigação\nepidemiológica inconclusiva.","B":"Diagnóstico de, pelo menos, uma doença indicativa de Aids e/ou contagem de linfócitos T\nCD4+<350células/mm³.","C":"Somatório de, pelo menos, 10 pontos, de acordo com a escala de sinais, sintomas ou doenças.","D":"Diagnóstico de, pelo menos, duas doenças indicativas de imunodeficiência de caráter grave.","E":"Menção de Aids/Sida em algum exame sorológico ou virológico e contagem de linfócitos T\nCD4+<500células/mm³."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-234412","number":"234412","sourceNumber":"234412","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem de 34 anos comparece na consulta de retorno, após ter recebido o\ndiagnóstico de infecção pelo HIV, solicitado\ncomo rastreio em avaliação periódica de saúde. Ele\nnão apresenta nenhuma queixa. Nega ter o diagnóstico de outras doenças atuais ou prévias ou\nfazer uso diário de quaisquer medicamentos. O exame físico não apresenta anormalidades. Traz os\nseguintes resultados de exames: Exames de laboratório: hemoglobina 13,9g/dL; leucócitos\n5.460/mm³; neutrófilos segmentados 4.190/mm³; linfócitos 780/mm³; plaquetas 183.000/mm³;\ncreatinina 1,0mg/dL; carga viral de HIV 345.000cópias/?L; linfócitos CD4 80/?L; teste tuberculínico\n7mm; toxoplasmose IgG positivo e IgM negativo; VDRL não reator; anti-HBs positivo; HBsAg\nnegativo; anti-HCV negativo. Radiografia do tórax: sem anormalidades. Considerando o caso\ndescrito, assinale a alternativa que apresenta a prescrição MAIS ADEQUADA para a profilaxia de\ninfecções oportunistas nesse paciente, além dos antirretrovirais:","options":{"A":"Azitromicina; isoniazida.","B":"Isoniazida; azitromicina; sulfametoxazol-trimetoprim.","C":"Isoniazida; sulfametoxazol-trimetoprim.","D":"Sulfametoxazol-trimetoprim."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-234429","number":"234429","sourceNumber":"234429","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A respeito das imunodeficiências primárias, é CORRETO afirmar que:","options":{"A":"A deficiência de IgA é a imunodeficiência mais comum e deve ser tratada com infusão\nendovenosa de imunoglobulina (IVIG).","B":"A maioria dos casos de infecção recorrente na infância têm relação com deficiências\nimunológicas identificáveis.","C":"A história de uma infecção bacteriana grave, como sepse e meningite, deve levar à suspeição\nclínica de imunodeficiência primária.","D":"O teste do pezinho oferecido pelo Sistema Único de Saúde realiza triagem para imunodeficiência\ncombinada grave."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-199510","number":"199510","sourceNumber":"199510","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A infecção pelo HIV pode cursar com quadro inespecífico, algumas vezes chamado de\nsíndrome retroviral aguda. Sobre esse tema, assinale a alternativa INCORRETA:","options":{"A":"A mononucleose infecciosa, a infecção pelo\ncitomegalovírus e a toxoplasmose aguda são\ndiagnósticos diferenciais.","B":"A faringite, as úlceras orais e a esofagite são\nmanifestações possíveis.","C":"A síndrome de Guillain-Barré é uma manifestação rara.","D":"O teste diagnóstico mais sensível é o ELISA\ndireto para anticorpos anti-HIV 1 e 2."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-220293","number":"220293","sourceNumber":"220293","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 23 anos, previamente hígido, apresentou uma crise convulsiva do tipo\ntônico-clônica generalizada. Negava crises convulsivas prévias, uso de drogas ou quaisquer\ncomorbidades conhecidas. Relata emagrecimento de 10 kg nos últimos 6 meses, além de cefaleia\nbifrontal diária há 1 mês. Ao exame físico, estava hipocorado, anictérico, alerta e orientado. Havia\npequenos e múltiplos linfonodos palpáveis nas regiões cervicais, occipitais e axilares. Os exames\nrespiratório, cardiovascular, abdominal e neurológico não revelaram anormalidades. Os exames de\nlaboratório revelaram: hemoglobina = 10 g/dl; leucócitos = 7.700/mm³; plaquetas: 110.000/mm³;\nanti-HIV = reagente; CD4 = 120/mm³; antiToxoplasma gondii: IgM = não reagente, IgG = reagente;\nanticitomegalovírus: IgM não reagente, IgG: reagente. A Tomografia de Crânio (TC) com contraste\nrevelou a seguinte imagem: Sobre o caso descrito, assinale a alternativa INCORRETA.","options":{"A":"As principais hipóteses diagnósticas são neurotoxoplasmose e citomegalovirose.","B":"O tratamento empírico com sulfadiazina + pirimetamina pode ser feito e a resposta clínica e\nradiológica avaliada em 10 a 14 dias.","C":"O diagnóstico etiológico definitivo é obtido pela realização da biópsia cerebral estereotáxica.","D":"Os glicocorticoides podem ser usados se houver rebaixamento da consciência e edema cerebral\ncom efeito de massa à TC."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-215120","number":"215120","sourceNumber":"215120","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os campos da imunologia e da oncologia estão ligados desde o final do século 19,\nquando o cirurgião William Coley relatou\nque uma injeção de bactérias mortas em locais de\nsarcoma poderia levar ao encolhimento do tumor. Desde então, os avanços exponenciais na\ncompreensão da interseção entre a vigilância imunológica e o crescimento e desenvolvimento do\ntumor levaram a amplos avanços terapêuticos que agora estão sendo estudados em todos os tipos\nde câncer, o que abrange o conceito de Imunoterapia. Uma resposta imune citotóxica eficiente e\nespecífica contra um tumor requer uma interação complexa e de rápida evolução entre vários tipos\nde células no sistema imune adaptativo e inato. Os tipos de células envolvidas diretamente no\nreconhecimento e rejeição de tumores são, EXCETO:","options":{"A":"Linfócitos CD8 + e CD4 +, tradicionalmente denominados células T citotóxicas e células T\nauxiliares.","B":"Células Natural Killer (NK) que não requerem apresentação de antígeno pelo complexo principal\nde histocompatibilidade (MHC) para atividade citotóxica.","C":"CD3, que codifica um complexo proteico transmembranar não variável com um componente de\nativação baseado em tirosina intracelular.","D":"FoxP3 + / CD25 + / CD4 + / T regulatório (Treg) e células supressoras derivadas de mielóides\n(MDSCs) que inibem em grande parte a atividade dos linfócitos T citotóxicos.","E":"Macrófagos M1, que liberam interferon (IFN) gama e são responsáveis pela fagocitose, e\nmacrófagos M2, que liberam citocinas como IL-4, IL-10, fator de crescimento transformador beta\n(TGF- beta)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-196741","number":"196741","sourceNumber":"196741","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Médicos da assistência primária devem sempre considerar a hipótese de alteração do\nsistema imunológico diante de algumas especificidades na anamnese e exame físico da criança.\nDessa forma, a capacitação e atualização sistemática para as imunodeficiências primárias é\nessencial. Marque a afirmativa correta.","options":{"A":"A produção de anticorpos pelas células B deve ser avaliado pelos níveis séricos de\nimunoglobulina e linfócitos T","B":"A exclusão inicial de defeitos imunológicos é dispendiosa e demorada, quase sempre realizadas\nem laboratórios especializados","C":"A avaliação da função imunológica deve ser iniciada nos casos de lactentes e crianças com\ndesordens imunológicas especificas e em todos os casos com infecções raras, crônicas ou de\nrepetição","D":"Quando os resultados de triagem inicial forem normais, para os pacientes com infecções\nbacterianas de repetição e pouco frequentes,\ntorna-se desnecessária a investigação de células\nfagocitárias e de células T"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-196805","number":"196805","sourceNumber":"196805","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem de 29 anos está há cerca de três semanas com tosse seca e dispneia, que\ninicialmente era leve e que foi se acentuando e agora está intensa. Vem apresentando também\nfebre. No exame físico há monilíase oral, esforço respiratório, com FR = 30 irpm; crepitações\npulmonares discretas, FC = 112 bpm; PA = 100 x 65 mmHg; Glasgow = 15; sem sinais meníngeos.\nExames complementares: DHL sérica = 980 U/ml; gasometria arterial com pO2 = 68 mmHg.\n\nRadiografia de tórax com infiltrado intersticial peri-hilar. Qual é a conduta?","options":{"A":"Sulfametoxazol + trimetoprima e corticoide.","B":"Sulfametoxazol + trimetoprima.","C":"Ceftriaxona + azitromicina.","D":"Ceftriaxona + azitromicina e corticoide."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-188008","number":"188008","sourceNumber":"188008","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Analisando-se a sensibilidade dos antibióticos, é correto afirmar:","options":{"A":"a ampicilina/sulbactam é pouco ativa contra anaeróbios e enterococcus;","B":"ceftazidima é uma cefalosporina com boa atividade contra gram-negativos, principalmente frente\nà Pseudomonas aeruginosa;","C":"o aztreonam é bem ativo contra gram-negativos e gram-positivos, mas pouco ativo contra\nanaeróbios;","D":"a moxifloxacina é uma quinolona de quarta geração, de espectro estendido, dose única diária,\ncom um diferencial dentro da classe de possuir boa atividade frente ao Staphylococcus aureus\nmeticilina-resistente;","E":"o ertapenem é um carbapenêmico com meia vida mais longa que o imipenem, podendo ser\nadministrado, também, por via intramuscular, porém pouco ativo contra anaeróbicos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-155465","number":"155465","sourceNumber":"155465","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A qualidade que tem o agente infeccioso de, uma vez instalado no organismo do ser\nhumano e de outros animais, produzir sintomas em maior ou menor proporção dentre os\nhospedeiros infectados é a definição de:","options":{"A":"Infectividade.","B":"Virulência.","C":"Imunogenicidade.","D":"Suscetibilidade.","E":"Patogenicidade."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-148590","number":"148590","sourceNumber":"148590","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 44 anos há seis meses abandonou terapia antirretroviral para infeção por\nHIV. Deu entrada no pronto socorro com perda\nde peso, febre, tosse não produtiva e dispnéia com\npiora evolutiva há uma semana. Ao exame físico apresenta FC = 115 bpm, FR= 34 irpm, terceira\nbulha, cardíaca e sibilos esparsos bilaterais à ausculta. Radiografia de tórax evidenciou infiltrado\nintersticial difuso peri-hilar bilateral. A PaO? em ar ambiente foi de 72%. Assinale a alternativa\nque\napresenta a melhor opção terapêutica.","options":{"A":"Rifampicina + izoniazida + pirazinamida.","B":"Sulfametoxazol + trimetoprim.","C":"Levofloxacino + azitromicina.","D":"Clindamicina + primaquina.","E":"Amoxicilina+clavulanato."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-162602","number":"162602","sourceNumber":"162602","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Patogenicidade é definida pela capacidade:","options":{"A":"De um agente etiológico produzir casos graves ou fatais.","B":"De um agente infeccioso produzir sintomas em maior ou menor proporção dentre os hospedeiros\ninfectados.","C":"Que têm certos organismos de penetrar e se desenvolver ou de se multiplicar no novo\nhospedeiro.","D":"Que tem o agente etiológico para induzir imunidade no hospedeiro.","E":"Que tem o parasita de se difundir através de tecidos, órgãos e sistemas anatomo-fisiológicos do\nhospedeiro."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-148592","number":"148592","sourceNumber":"148592","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os sucessos na prevenção da transmissão vertical, principal mecanismo de aquisição\ndo HIV em pediatria, levaram a uma\nsignificativa redução dos casos novos, porém, com\nestabilização nos últimos anos. Observe as afirmativas abaixo e marque a sentença incorreta a\nrespeito de infecção por HIV na infância.","options":{"A":"Em todos os recém-nascidos de mulheres infectadas pelo HIV recomenda-se a não\namamentação e a substituição do leite materno por fórmula infantil após aconselhamento.","B":"Todos os recém-nascidos de mulheres infectadas pelo HIV devem receber profilaxia com\nantirretroviral.","C":"No diagnóstico de crianças menores de 18 meses de idade, resultados detectáveis de carga viral\nabaixo de 5.000 cópias/mL devem ser cuidadosamente analisados e repetidos por causa da\npossibilidade de um resultado falso-positivo.","D":"Uma criança menor de 18 meses de idade com duas cargas virais indetectáveis, sendo a\nsegunda após quatro meses de idade, é\nconsiderada não infectada pelo HIV.","E":"O parto vaginal e o tratamento da mãe HIV positiva com antirretrovirais reduz o risco de\ntransmissão do vírus para o bebê."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131629","number":"131629","sourceNumber":"131629","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os microorganismos responsáveis por artrite bacteriana não gonocócica aguda, em\nadultos saudáveis, na maioria das vezes são:","options":{"A":"Estreptococos dos grupos A, B e C.","B":"Pseudomonas aeruginosa.","C":"Bacteroides fragilis e Fusobacterium spp.","D":"Staphylococcus epidermidis.","E":"Staphylococcus aureus."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131630","number":"131630","sourceNumber":"131630","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As endocardites bacterianas em prótese valvar, que ocorrem entre 2 e 12 meses após\na cirurgia de troca valvar, têm como\nprincipais agentes etiológicos:","options":{"A":"Enterococos.","B":"Bactérias do grupo HACEK.","C":"Bacilos Gram-negativos.","D":"Estafilococos coagulase-negativos.","E":"Estreptococos do grupo A."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-101005","number":"101005","sourceNumber":"101005","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 51 anos, com história de infecção prévia por HIV, tendo descontinuado o\ntratamento com antirretrovirais há cerca de 1 ano. Há 4 semanas com tosse não produtiva, dispneia\nprogressiva e perda ponderal de 2 kg. Há 3 dias com febre de 38,5ºC. O exame físico\n\nencontrava-se com frequência respiratória de 32 irpm; dispneico; crepitações em bases pulmonares\nbilateralmente; pressão arterial de 100 x 70 mmHg; frequência cardíaca de 90 bpm; saturação de\nO2 de 89% em ar ambiente. A oroscopia evidenciou placas esbranquiçadas em orofaringe.\n\nRadiografia e tomografia de tórax evidenciando infiltrado inflamatório intersticial bilateral com\npadrão de \"vidro fosco\". Assinale a\nalternativa que representa o agente etiológico mais provável\ndeste caso:","options":{"A":"Pneumocystis jirovecii.","B":"Mycobacterium tuberculosis.","C":"Moraxella catarrhalis.","D":"Histoplasma capsulatum.","E":"Toxoplasma gondii."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-77364","number":"77364","sourceNumber":"77364","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A médica residente, responsável pelas internações da clínica médica, é chamada pelo\nmédico do pronto-socorro para realizar internação de determinada paciente. Trata-se de uma\nsenhora, 82 anos, diabética, com sequelas leves de AVC prévio que limitam sua deambulação de\nmodo que permanece grande parte do dia acamada. Filha refere vários tratamentos com\nantibióticos diversos para infecções urinárias diagnosticadas por médico de saúde da família (último\ntratamento há menos de 1 mês). Essa mesma residente havia atendido essa senhora 48h antes no\nseu estágio no PS, devido queixa da filha de que a paciente estava desanimada e permanecendo\nmais tempo na cama. Nesse atendimento ela solicitou um EAS e urocultura, sob a justificativa de\ncontrole de tratamento e liberou a senhora para domicílio. Assim que teve acesso ao resultado, a\nfilha retornou com a mãe ao hospital, sem novas queixas, bastante irritada por ter recebido alta 48h\nantes, sendo então indicada internação pelo médico do PS. Os exames que haviam sido solicitados\nmostravam: EAS (urina rotina): 6 piócitos; nitrito negativo; flora bacteriana aumentada.\nUrocultura:\n\nE. coli multirresistente, sensível apenas à gentamicina. Diante desse quadro, o preceptor desta\nmédica residente, durante a corrida de leitos, deve:","options":{"A":"Explicar que esses exames foram realizados desnecessariamente, que a indicação de\ninternação foi equivocada, e dar alta para a paciente sem nenhum tratamento antibiótico.","B":"Colher nova urocultura, colhida através de sondagem vesical de alívio, e iniciar gentamicina até\nresultado da nova cultura solicitada.","C":"Iniciar gentamicina com dose ajustada para o clearance de creatinina.","D":"Colher nova urocultura, colhida através de sondagem vesical de alívio, e somente iniciar\ngentamicina se confirmada a resistência aos outros antibióticos.","E":"Iniciar meropenem, pois não existe E. coli na comunidade resistente ao meropenem, devido ao\nrisco de insuficiência renal com uso de aminoglicosídeos em idosos diabéticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-59427","number":"59427","sourceNumber":"59427","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Acerca dos principais problemas com resistência bacteriana, marque a alternativa\nINCORRETA:","options":{"A":"A produção de betalactamase de espectro ampliado (ESBL) é um dos mecanismos de\nresistência mais importantes das\nenterobactérias, conferindo assim resistência aos carbapenens.","B":"O crescimento da resistência dos bacilos Gram negativos, em especial Acinetobacter spp. E P.\naeruginosa aos carbapenens, representa um grande problema nas unidades de terapia intensiva\nbrasileiras.","C":"A polimixina B tem sido utilizada como alternativa em caso de resistência ao meropenen em\npacientes com infecção por Acinetobacter spp.","D":"Apesar de ainda ser fato relativamente raro, há um aumento da incidência dos enterococos\nresistentes à vancomicina no Brasil.","E":"Há evidentes fortes que indicam superioridade da linezolida no tratamento de pneumonias\ncausadas por S. Aureus resistentes a oxacilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-59056","number":"59056","sourceNumber":"59056","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 20 anos, com história de febre há cinco dias. Apresenta celulite extensa em\nmembro inferior direito. Em relação ao paciente em questão, é incorreto afirmar:","options":{"A":"Uso de cefalotina está indicado, pois apresenta boa cobertura para bactérias Gram-positivas de\npele.","B":"Caso o paciente apresente alergia a betalactâmicos, uma opção para tratamento é clindamicina.","C":"Caso o paciente receba clindamicina, o aparecimento de diarreia pode ser devido à colite\npseudomembranosa.","D":"Se houver crescimento de Staphylococcus aureus na hemocultura, o médico deve estar atento à\npossibilidade de disseminação a distância.","E":"Se o paciente apresentar radiografia de tórax com derrame pleural, o diagnóstico de empiema\nsugere etiologia estreptocócica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-59063","number":"59063","sourceNumber":"59063","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação à infecção do trato urinário assinale a alternativa mais adequada:","options":{"A":"Infecções do trato urinário baixo de repetição são comuns em mulheres jovens; nesse caso, a\ncoleta da urocultura é mandatória para avaliar o patógeno em questão.","B":"Pacientes com pielonefrite já com tratamento em curso devem realizar exames de imagem\nabdominal (ultrassonografia ou tomografia\ncomputadorizada) em caso de recorrência da febre, para\navaliar presença de coleções.","C":"No caso de infecção urinária baixa em mulheres, o patógeno mais comum é a Escherichia coli,\nmas o crescimento de Staphylococcus saprophyticus também deve ser valorizado.","D":"Infecções polimicrobianas são comuns em casos de infecção urinária de repetição.","E":"Questões B e C estão corretas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-59033","number":"59033","sourceNumber":"59033","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quanto às meningites na infância, seus agentes etiológicos e os aspectos de vigilância\nepidemiológica envolvidos é correto afirmar que:","options":{"A":"As gestantes que tiveram contato com pacientes com meningite por Haemophilus influenzae B\nou por meningococo não devem receber\nrifampicina devido aos seus possíveis efeitos\nteratogênicos.","B":"Vinte e quatro horas após o início da antibioticoterapia com ceftriaxona, o paciente com\nmeningite meningocócica não é considerado mais infectante.","C":"A indicação de profilaxia com rifampicina para meningococo é restrita aos contatos íntimos\nintradomiciliares com idade inferior ou igual a cinco anos.","D":"A notificação compulsória das meningites agudas às autoridades municipais de saúde limita-se\nàquelas suspeitas de terem etiologia bacteriana.","E":"A vacina conjugada contra Haemophilus influenzae B não está indicada para lactentes que já\ntiveram meningite por este agente infeccioso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-43327","number":"43327","sourceNumber":"43327","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente 67 anos, sexo feminino, negra, portadora de Miocardiopatia Dilatada\nBiventricular Grave, Insuficiência Renal\nCrônica ainda não dialítica (em acompanhamento com\nnefrologia), portadora de Marca-passo Cardíaco implantado há cerca de 4 meses em virtude de\nBloqueio Átrio Ventricular Total. Dá entrada no hospital Evangélico após ter recebido alta há cerca\nde 48 horas, de internação cardiológica com duração de 1 semana (poucos dados disponíveis\ndesta internação no prontuário, tanto de história como de exames). Apresenta o seguinte quadro:\nFebre diária, não termometrada, que segundo acompanhantes já havia iniciado mesmo antes da\nprimeira internação, acompanhada de hiporexia progressiva, prostração e adinamia. Nas últimas 24\nhoras apresentou piora clínica com rebaixamento do nível de consciência sendo trazida de volta ao\nhospital. Exame clínico: Febre (38,5°), abertura ocular ao estímulo, movendo os quatro membros,\nporém sem atender comandos, verbalizando poucas palavras incompreensíveis. Rigidez de nuca.\n\nRCR 3t (B3) FC 100 bpm. Ictus desviado para esquerda e para baixo. SSR 3/6 em foco mitral e\ntricúspide. PA 100 x 60 mmHg. Abdome livre. Exames realizados: ECG: átrios em ritmo sinusal e\nventrículos comandados por marca-passo; RX tórax com opacidades nodulares difusas distribuídas\npor ambos os pulmões e de tamanhos diferentes; Laboratório: Hb 9,5 Leucócitos 20.000 (bastões\n15 segmentados 70), plaquetas 65.000, Ureia 300, creatinina 8,0, PCR 120; TC Crânio alterações\ncompatíveis com a idade; Liquor turvo, hipercelular, com predomínio de polimorfonucleares, glicose\nbaixa, proteína elevada. Cultura positiva para estafilococos sensível à oxacilina; Hemocultura (03\namostras) positiva para estafilococos sensível à oxacilina. Qual é o DIAGNÓSTICO PRINCIPAL?","options":{"A":"Púrpura Trombocitopênica Trombótica induzida por estafilococcia.","B":"Pneumonia estafilocócica, sepse e disfunção de múltiplos órgãos.","C":"\"Endocardite\" de cabo de marca-passo.","D":"Meningite estafilocócica e sepse.","E":"Endocardite aguda estafilocócica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-43328","number":"43328","sourceNumber":"43328","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente 67 anos, sexo feminino, negra, portadora de Miocardiopatia Dilatada\nBiventricular Grave, Insuficiência Renal\nCrônica ainda não dialítica (em acompanhamento com\nnefrologia), portadora de Marca-passo Cardíaco implantado há cerca de 4 meses em virtude de\nBloqueio Átrio Ventricular Total. Dá entrada no hospital Evangélico após ter recebido alta há cerca\nde 48 horas, de internação cardiológica com duração de 1 semana (poucos dados disponíveis\ndesta internação no prontuário, tanto de história como de exames). Apresenta o seguinte quadro:\nFebre diária, não termometrada, que segundo acompanhantes já havia iniciado mesmo antes da\nprimeira internação, acompanhada de hiporexia progressiva, prostração e adinamia. Nas últimas 24\nhoras apresentou piora clínica com rebaixamento do nível de consciência sendo trazida de volta ao\nhospital. Exame clínico: Febre (38,5°), abertura ocular ao estímulo, movendo os quatro membros,\nporém sem atender comandos, verbalizando poucas palavras incompreensíveis. Rigidez de nuca.\n\nRCR 3t (B3) FC 100 bpm. Ictus desviado para esquerda e para baixo. SSR 3/6 em foco mitral e\ntricúspide. PA 100 x 60 mmHg. Abdome livre. Exames realizados: ECG: átrios em ritmo sinusal e\nventrículos comandados por marca-passo; RX tórax com opacidades nodulares difusas distribuídas\npor ambos os pulmões e de tamanhos diferentes; Laboratório: Hb 9,5 Leucócitos 20.000 (bastões\n15 segmentados 70), plaquetas 65.000, Ureia 300, creatinina 8,0, PCR 120; TC Crânio alterações\ncompatíveis com a idade; Liquor turvo, hipercelular, com predomínio de polimorfonucleares, glicose\nbaixa, proteína elevada. Cultura positiva para estafilococos sensível à oxacilina; Hemocultura (03\namostras) positiva para estafilococos sensível à oxacilina. Quais os exames e condutas principais?","options":{"A":"Avaliação da hematologia e realização de plasmaférese.","B":"lntubação, coleta de aspirado traqueal e vancomicina.","C":"Ecocardiograma transtorácico, retirada do cabo de marca-passo e oxacilina.","D":"Início precoce de oxacilina e coleta de nova amostra de liquor conforme evolução do quadro.","E":"Ecocardiograma Transesofágico e Vancomicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-43334","number":"43334","sourceNumber":"43334","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre a prevenção da endocardite infecciosa (EI), marque a alternativa INCORRETA:","options":{"A":"Estes são alguns exemplos de pacientes considerados como alto risco de adquirir EI: portadores\nde prótese cardíaca valvar, portadores de\ncardiopatias congênitas, como as do tipo comunicação\ninterventricular (CIV) e comunicação interatrial (CIA) e pacientes com história prévia de\nendocardite.","B":"Devem receber profilaxia antibiótica pacientes de risco elevado para EI e que realizarão\nprocedimentos odontológicos que envolvem a manipulação do tecido gengival.","C":"Não há indicação de profilaxia para procedimentos sem risco de bacteremia.","D":"Deve-se usar o esquema de Ampicilina + gentamicina para pacientes de risco elevado de EI nas\ncirurgias gastrointestinais e geniturinárias.","E":"Não há indicação de profilaxia para pacientes com prolapso mitral sem regurgitação, mesmo\npara cirurgias gastrointestinais e\ngeniturinárias."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-43978","number":"43978","sourceNumber":"43978","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação às infecções bacterianas do sistema nervoso central podemos afirmar,\nexceto:","options":{"A":"No período neonatal, os principais agentes etiológicos responsáveis pelas meningites\nbacterianas são: E. coli, estreptococo do grupo B e Listeria monocytogenes.","B":"No Brasil, a N. meningitidis é o principal agente etiológico das meningites bacterianas fora do\nperíodo neonatal.","C":"Os achados de morfologia do liquor em pacientes com meningite bacteriana incluem\nclassicamente aumento de celularidade com predomínio de polimorfonuclear.","D":"A glicorraquia está diminuída e o seu nível deve ser comparado ao da glicose sanguínea.\n\nGeralmente esse nível é menor que dois terços da concentração da glicose no sangue periférico,\nem condições de normalidade.","E":"A proteinorraquia está geralmente elevada, sendo o valor normal até 40 mg/dl."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-32488","number":"32488","sourceNumber":"32488","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"É INCORRETO afirmar sobre a Infecção do Trato Urinário (ITU) nas mulheres:","options":{"A":"O risco relativo de ITU aguda aumenta durante as 48 horas após atividade sexual.","B":"O risco de desenvolver segunda ITU é maior que o da primeira, com pelo menos 20% de\nrecorrência em 6 meses de seguimento.","C":"O estriol reduz o tônus muscular e a peristalse ureteral, aumentando o risco de ITU na gestação.","D":"Mulheres com diabetes insulino-dependente têm incidência de ITU de 2 a 4 vezes maior.","E":"Nas mulheres idosas o risco de ITU aumenta substancialmente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-23120","number":"23120","sourceNumber":"23120","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São fatores de risco para a Infecção de Trato Urinário (ITU) em mulheres, exceto:","options":{"A":"atividade sexual","B":"diabetes mellitus","C":"gestação","D":"uso de sondas vesicais","E":"terapia hormonal"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27337","number":"27337","sourceNumber":"27337","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, compareceu ao ambulatório de dermatologia\ncom queixa de dor e calor na perna direita. Ao\nexame dermatológico, apresentava\ncomprometimento de extensa área no membro inferior direito que se encontrava edemaciado,\neritematoso e quente. Além disso, apresentava tinha interdigital entre o terceiro e quarto\npododáctilo e linfadenomegalia inguinal à direita. O quadro cutâneo estava associado a sintomas\ngerais de febre (39°C) e calafrios.De acordo com o caso clínico descrito, marque a alternativa\nincorreta:","options":{"A":"A erisipela é geralmente causada pelo estreptococo beta-hemolítico do grupo A.","B":"O caso descrito pode evoluir com bolhas associadas, sendo denominada erisipela bolhosa.","C":"O paciente acima não apresentava fator de risco para o desenvolvimento dessa dermatose\ncausada por bactéria.","D":"O linfedema ou mesmo a elefantíase podem ocorrer como conseqüência dos surtos recidivantes.","E":"A droga de escolha para o tratamento é a penicilina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27401","number":"27401","sourceNumber":"27401","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Das cefalosporinas abaixo, é mais ativa contra Pseudomonas aeruginosa:","options":{"A":"Cefotaxima","B":"Ceftriaxona","C":"Cefoxitina","D":"Cefazolina","E":"Ceftazidima"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9382","number":"9382","sourceNumber":"9382","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Síndrome poliglandular auto-imune tipo 2 caracteriza-se por:","options":{"A":"Diabetes mellitus insulino dependente, disfunção da tireoide e doença de Addison.","B":"Candidíase mucocutânea, hipoparatiroidismo e doença de Addison.","C":"Carcinoma medular da tireoide, feocromocitoma e hiperparatiroidismo.","D":"Hiperparatiroidismo, tumor de pâncreas e da hipófise.","E":"Hiperparatiroidismo, tumor de pâncreas e feocromocitoma."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9469","number":"9469","sourceNumber":"9469","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O anaeróbio mais comumente isolado nas peritonites secundárias é:","options":{"A":"Bactérias do gênero Clostridium.","B":"Streptococcus viridans.","C":"Pseudomonas aeruginosa.","D":"Escherichia coli.","E":"Bacteroides fragilis."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9387","number":"9387","sourceNumber":"9387","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A causa mais comum de hipoparatireoidismo é:","options":{"A":"Perda idiopática de função das glândulas paratireoides.","B":"Síndrome de DiGeorge.","C":"Lesão cirúrgica das glândulas paratireoides.","D":"Hipertireoidismo.","E":"Nenhuma das respostas acima."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-331989","number":"331989","sourceNumber":"331989","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre as crianças expostas ao HIV, é correto afirmar que:","options":{"A":"Nos primeiros seis meses de vida, não devem receber as vacinas oferecidas pelo PNI, mas sim\nimunológicos especiais no centro de referência.","B":"O Ministério de Saúde do Brasil recomenda que a coleta da primeira carga viral seja feita na\nsegunda semana de vida do recém-nascido.","C":"Deve-se iniciar a profilaxia para pneumonia por Pneumocystis jiroveci com o uso de\nsulfametoxazol + trimetoprim três vezes por\nsemana se a contagem de linfocitos CD4 estiver abaixo\nde 15%.","D":"As não infectadas tendem a apresentar mais infecções bacterianas e quadros mais graves se\ncomparadas a crianças não expostas ao HIV.","E":"Para o diagnóstico de infecção pelo HIV, a recomendação é que o teste anti-HIV seja feito entre\no sexto e o 12° mês de vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-342632","number":"342632","sourceNumber":"342632","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na evolução da infecção pelo HIV, é comum ocorrer envelhecimento precoce, que pode\nser explicado pela associação de:","options":{"A":"processo inflamatório crônico e ativação imune persistente","B":"controle completo da replicação viral após tratamento e uso tardio de antiretrovirais","C":"intensa inflamação do início da infecção e controle da ativação imune","D":"ativação imune persistente e uso precoce de antirretrovirais"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-331997","number":"331997","sourceNumber":"331997","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente apresenta pneumonia de repetição difusa, associada a piodermite recorrente,\nbaixo desenvolvimento ponderal e lesões bacterianas\nperiorificiais. Deve-se considerar como\nprincipal hipótese diagnóstica:","options":{"A":"Fibrose cística.","B":"Leucopenia cíclica.","C":"Deficiência de cd20.","D":"Doença granulomatosa crônica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-302833","number":"302833","sourceNumber":"302833","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um paciente de 30 anos queixa-se de tosse seca, febre baixa e dispneia progressiva há\nvinte dias, com piora recente. Confessa que há dois anos descobriu ser soropositivo para HIV, mas\nnão quis realizar qualquer tratamento ou investigação e perdeu o acompanhamento. Qual dos itens\nabaixo NÃO sugere pneumonia por Pneumocystis jiroveci?","options":{"A":"Contagem de linfócitos CD4 menor que 200 células/mm3.","B":"Hipoxemia.","C":"Elevação do níveis de DHL(lactato desidrogenase).","D":"Derrame pleural volumoso.","E":"Radiografia de tórax normal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-314101","number":"314101","sourceNumber":"314101","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Entre as alterações metabólicas e cardiovasculares associada à SIDA (síndrome da\nimunodeficiência adquirida), encontra-se a","options":{"A":"resistência insulínica.","B":"elevação do LDL-C.","C":"redução do colesterol total.","D":"elevação do HDL."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-311906","number":"311906","sourceNumber":"311906","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A pneumocistose (PCP) é uma doença oportunista muito comum entre pacientes\nimunossuprimidos pelo vírus HIV. Ela pode ocorrer por reatividade de infecção latente ou por\nreinfecção. Depois de inalado, o Pneumocystis escapa das defesas do trato respiratório superior e\ndeposita-se nos alvéolos. Neste local, o macrófago alveolar vai prontamente fagocitar o patógeno e\ndestruí-lo, desencadeando uma reação inflamatória local. Sobre a fisiopatogenia da pneumocistose\ne seu tratamento, pode-se afirmar que:","options":{"A":"o paciente com AIDS, por ter sua imunidade celular prejudicada, tende a ter uma apresentação\nclínica de PCP mais branda e, na maioria das\nvezes, não necessita realizar tratamento\nmedicamentoso específico.","B":"Sulfametoxazol-trimetoprim é a droga de escolha para tratamento da PCP e deve ser utilizada na\ndose de 5mg/kg/dia de seu componente\ntrimetoprim, com duração de 21 dias.","C":"a densidade parasitária em forma de trofozoíto no tecido pulmonar não é responsável pela\nextensão da reação inflamatória desencadeada pelo Pneumocystis e, portanto, a gravidade da\ndoença independe desse mecanismo.","D":"a presença de exsudato inflamatório nos alvéolos pode levar a uma diminuição da oferta de\noxigênio ao paciente e, portanto, o uso do corticoesteroides é um dos pilares de tratamento desta\ndoença quando o paciente tem indícios de hipoxemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-311908","number":"311908","sourceNumber":"311908","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O Toxoplasma gondii é um protozoário de distribuição endêmica e capaz de provocar\ndoença em diversos tecidos e órgãos. Sobre a\ntoxoplasmose podemos dizer:","options":{"A":"A profilaxia secundária da Toxoplasmose no paciente com aids deve ser descontinuada após a\ncontagem de linfócitos T CD4 > 100.","B":"É fundamental a identificação de anticorpos da classe IgM para se fazer o diagnóstico de\nreinfecção por toxoplasmose, cuja forma clínica mais comum é a neurotoxoplasmose.","C":"A Toxoplasmose aguda em imunocompetentes, usualmente, não precisa de tratamento. Porém\neste deve ser considerado se os sintomas são\ngraves ou persistentes.","D":"O ácido fólico pode ser utilizado em substituição ao ácido folínico, sendo esses dois\nmedicamentos indicados para neutralizar os efeitos tóxicos da combinação de sulfadiazina e\npirimetamina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-300923","number":"300923","sourceNumber":"300923","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considerando o tratamento da hepatite C aguda e crônica para pacientes com idade\nmaior ou igual a 18 anos, não submetidos a tratamentos prévios com DAA. Pacientes com\ngenótipos 1, 2, 4, 5 e 6 e com cirrose Child-B ou Child-C, sem contraindicação e tolerantes à\nribavirina, estão de acordo com o item:","options":{"A":"Poderão ter o tempo de tratamento diminuído para 2 semanas, desde que haja associação da\nribavirina ao NS5A indicado.","B":"Poderão ter o tempo de tratamento diminuído para 12 semanas, desde que não haja associação\nda ribavirina ao NS5A indicado.","C":"Poderão ter o tempo de tratamento aumentado para 12 semanas, desde que haja associação da\nribavirina ao NS5A indicado.","D":"Poderão ter o tempo de tratamento diminuído para 12 semanas, desde que haja associação da\nribavirina ao NS5A indicado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-300925","number":"300925","sourceNumber":"300925","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em pacientes com cirrose Child-Pugh B e C, a dose inicial de ribavirina deve ser de\n500mg ao dia, podendo ser aumentada conforme\na tolerância do paciente e avaliação médica.\nSendo adequado o item:","options":{"A":"A dose máxima não deve ultrapassar 11 mg/kg/dia. A adição de ribavirina, quando possível, é\nsempre proibida em pacientes cirróticos e em todos aqueles com menor chance de resposta\nvirológica: não respondedores aos esquemas com interferon, genótipo 3, sexo masculino, idade\n\n>40 anos, ou a critério da equipe médica.","B":"A dose máxima não deve ultrapassar 11 mg/kg/dia. A adição de ribavirina, quando possível, é\nsempre recomendada em pacientes cirróticos e em todos aqueles com maior chance de resposta\nvirológica: não respondedores aos esquemas com interferon, genótipo 3, sexo masculino, idade\n\n>40 anos, ou a critério da equipe médica.","C":"A dose máxima não deve ultrapassar 11 mg/kg/dia. A adição de ribavirina, quando possível, é\nsempre recomendada em pacientes cirróticos e em todos aqueles com menor chance de resposta\nvirológica: não respondedores aos esquemas com interferon, genótipo 3, sexo masculino, idade\n\n>40 anos, ou a critério da equipe médica.","D":"A dose máxima não deve ultrapassar 11 mg/kg/dia. A adição de ribavirina, quando possível, é\nsempre recomendada em pacientes cirróticos e em todos aqueles com menor chance de resposta\nvirológica: respondedores aos esquemas com interferon, genótipo 3, sexo masculino, idade >40\nanos, ou a critério da equipe médica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-295390","number":"295390","sourceNumber":"295390","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A profilaxia pré-exposição ao HIV (PrEP) representa uma estratégia adicional nova,\neficaz e segura, de prevenção disponível no Sistema Único de Saúde (SUS) com o objetivo de\nreduzir a transmissão do HIV. Essa estratégia de prevenção deve ser oferecida a","options":{"A":"todos os homens e mulheres sexualmente ativos com sinais e sintomas de uma infecção viral\naguda.","B":"homens e mulheres que tiveram diagnóstico de uma infecção sexualmente transmissível nos\núltimos seis meses.","C":"homens e mulheres que mantiveram relação sexual sem preservativo nas últimas 72 horas.","D":"profissionais do sexo, sem considerar a quantidade e a diversidade de parcerias sexuais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-308288","number":"308288","sourceNumber":"308288","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O nosso país atualmente apresenta quedas nas taxas de transmissão vertical do HIV.\n\nEste fato é decorrente de medidas profiláticas, envolvendo cuidados com o binômio\n\nmãe-recém-nascido. Medidas como o aumento do número de diagnósticos realizados durante o\npré-natal, utilização da terapia antirretroviral e medidas profiláticas para o recém-nascido\ncontribuíram para esse cenário (Pascom et al.,2020). Gestante, portadora do vírus HIV há cerca de\n3 anos, não faz uso de terapia antirretroviral, deu entrada no Hospital e Maternidade Dona Íris, em\ntrabalho de parto. Recém nascido com peso ao nascimento de 3150 gramas, Capurro de 39\nsemanas e 2 dias. Qual (is) antirretroviral (is) este recém-nascido deverá receber?","options":{"A":"AZT (zidovudina) por 42 dias.","B":"AZT (zidovudina) por 28 dias e NVP (nevirapina) por 3 dias.","C":"AZT (zidovudina) , NVP (nevirapina) e 3TC (lamivudina) por 28 dias.","D":"AZT (zidovudina) , 3TC (lamivudina) e RAL (raltegravir) por 28 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-308301","number":"308301","sourceNumber":"308301","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As imunodeficiências primárias, estão sendo diagnosticadas em números cada vez\nmaior. Atualmente mais de 95 diferentes tipos já\nforam descritos. Em nosso meio, essas doenças\nainda são subdiagnosticadas acarretando prejuízos para os pacientes por elas acometidos. Marque\na alternativa que não representa sinal de alerta para investigação das imunodeficiências primárias.","options":{"A":"Duas ou mais pneumonias no período de 1 ano.","B":"Quatro ou mais novas otites no período de 1 ano.","C":"História familiar de imunodeficiência primária.","D":"Estomatite ou candidíase oral ou cutânea."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-294342","number":"294342","sourceNumber":"294342","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A doença granulomatosa crônica da infância é uma imunodeficiência hereditária,\ngeralmente ligada ao cromossoma X. As crianças\nfrequentemente podem ser infectadas por fungos.\nDentre esses, o mais comum é:","options":{"A":"candida albicans.","B":"aspergilus fumigatus.","C":"torulepsis glabrata.","D":"criptococos neoformans."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281251","number":"281251","sourceNumber":"281251","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre as hepatites virais crônicas, toxicidade medicamentosa, abuso de álcool, doença\ngordurosa não alcoólica do fígado,\nesteatose e esteatohepatite, pode-se afirmar que:","options":{"A":"São fatores importantes da doença hepática nessa população de pessoas vivendo com HIV\nPVHIV, com desfecho para cirrose hepática.","B":"Não são fatores importantes da doença hepática nessa população de pessoas vivendo com HIV\nPVHIV, com desfecho para cirrose hepática.","C":"São fatores importantes da doença hepática nessa população de pessoas vivendo com HIV\nPVHIV, sem desfecho para cirrose hepática.","D":"São fatores sem importância nessa população de pessoas vivendo com HIV PVHIV, com\ndesfecho para cirrose hepática."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281257","number":"281257","sourceNumber":"281257","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Há mecanismos principais de lesão hepática associada aos ARV antirretrovirais, sendo\ncorreto o item:","options":{"A":"Reações de hipersensibilidade, toxicidade direta do fármaco e/ou seu metabólito, toxicidade\nmitocondrial e não a SIR síndrome inflamatória da reconstituição imune.","B":"Reações de hipersensibilidade apenas, não ocorrendo toxicidade direta do fármaco e/ou seu\nmetabólito, toxicidade mitocondrial e SIR síndrome inflamatória da reconstituição imune.","C":"Reações de hipersensibilidade, toxicidade direta do fármaco e/ou seu metabólito, toxicidade\nmitocondrial e SIR síndrome inflamatória da reconstituição imune.","D":"Reações de hipersensibilidade, toxicidade direta do fármaco, mas não de seus metabólitos,\ntoxicidade mitocondrial e nunca SIR síndrome inflamatória da reconstituição imune."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281258","number":"281258","sourceNumber":"281258","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação aos Inibidores de Transcriptase Reversa Não Análogos de Nucleosídeos\n(ITRNN). Pode-se afirmar que:","options":{"A":"Os ITRNN não podem causar hepatotoxicidade por reação de hipersensibilidade ou por\ntoxicidade direta dos medicamentos.","B":"Os ITRNN podem causar hepatotoxicidade por reação de hipersensibilidade, mas não por\ntoxicidade direta dos medicamentos.","C":"Os ITRNN podem causar hepatotoxicidade sem reação de hipersensibilidade ou toxicidade\ndireta dos medicamentos.","D":"Os ITRNN podem causar hepatotoxicidade por reação de hipersensibilidade ou por toxicidade\ndireta dos medicamentos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281260","number":"281260","sourceNumber":"281260","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação aos Inibidores de Protease (IP), pode-se afirmar que:","options":{"A":"A hepatotoxicidade não associada aos IP geralmente ocorre após semanas ou meses do início\nda medicação.","B":"A hepatotoxicidade associada aos IP geralmente ocorre após semanas ou meses do início da\nmedicação.","C":"A hepatotoxicidade associada aos IP nunca ocorre após semanas ou meses do início da\nmedicação.","D":"A hepatotoxicidade associada aos IP geralmente ocorre após anos do início da medicação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281262","number":"281262","sourceNumber":"281262","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Hepatite e alterações hepáticas relacionadas ao HIV com falência hepática têm sido\nrelatadas, sendo correto o item:","options":{"A":"Com TPV tipranavir em combinação com RTV ritonavir. O ATV atazanavir não causa\ncomumente hiperbilirrubinemia indireta (não associada a\ninjúria hepática) e, normalmente, não\nnecessita descontinuação do tratamento.","B":"Com TPV tipranavir em combinação com RTV ritonavir. O ATV atazanavir causa comumente\nhiperbilirrubinemia indireta (não associada a injúria hepática) e, normalmente, necessita\ndescontinuação do tratamento.","C":"Com TPV tipranavir em combinação com RTV ritonavir. O ATV atazanavir causa comumente\nhiperbilirrubinemia indireta (não associada a injúria hepática) e, normalmente, não necessita\ndescontinuação do tratamento.","D":"Com TPV tipranavir em combinação com RTV ritonavir. O ATV atazanavir nunca causa\ncomumente hiperbilirrubinemia indireta (não associada a\ninjúria hepática) e, normalmente, não\nnecessita descontinuação do tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-281263","number":"281263","sourceNumber":"281263","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A Toxicidade Hepática é um dos efeitos adversos graves mais comumente associados\naos antirretrovirais ARV. Sendo correto o item:","options":{"A":"A apresentação clínica da hepatotoxicidade pode variar de elevação assintomática de\ntransaminases até falência hepática grave.","B":"A apresentação clínica da hepatotoxicidade não pode variar de elevação assintomática de\ntransaminases até falência hepática grave.","C":"A apresentação clínica da hepatotoxicidade pode variar de elevação assintomática de\ntransaminases, mas não para falência hepática grave.","D":"A apresentação clínica da hepatotoxicidade não pode variar para falência hepática grave."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-265854","number":"265854","sourceNumber":"265854","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pacientes com cirrose hepática devem ser frequentemente monitorados em relação à\nfunção hepática, sendo ADEQUADO o item:","options":{"A":"Exceto aqueles em uso de medicamentos inibidores de protease.","B":"Principalmente aqueles em uso de medicamentos promotores de protease.","C":"Principalmente aqueles em uso de medicamentos indutores de protease.","D":"Principalmente aqueles em uso de medicamentos inibidores de protease."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-274506","number":"274506","sourceNumber":"274506","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As imunodeficiências primárias (IDP) são doenças consideradas raras isoladamente;\nporém, fazem parte de um conjunto de mais de\n200 diferentes alterações já descritas e uma\nprevalência estimada de 1:2.000 nascidos vivos. A Fundação Jeffrey Modell, em conjunto com\noutras instituições americanas, formularam sinais de alerta que pudessem chamar a atenção para a\nnecessidade de se investigar uma possível imunodeficiência. No Brasil, esses sinais de alerta\nsofreram uma adaptação para a realidade local, em um esforço conjunto da Sociedade Brasileira de\nPediatria e da Associação Brasileira de Alergia e Imunopatologia. Quais dos sinais/sintomas abaixo\nfazem parte dos 10 sinais de alerta para investigação de IDP?","options":{"A":"Uma pneumonia no último ano.","B":"Duas ou mais novas otites no último ano.","C":"Um episódio de infecção sistêmica grave (meningite, osteoartrite, septicemia).","D":"Asma leve, doença do colágeno ou doença autoimune."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-282049","number":"282049","sourceNumber":"282049","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Você é chamado para recepcionar um bebê termo, nascendo via parto normal, peso de\nnascimento 3,100kg, mãe com teste rápido positivo para HIV, sabidamente positiva, sem\ntratamento prévio e pré-natal irregular. Mãe recebendo AZT (Zidovudina) injetável intra-parto. Em\nrelação ao recém-nascido, assinale a alternativa correta:","options":{"A":"O recém-nascido deverá receber AZT 4mg/kg/dose a cada 6 horas com início nas duas\nprimeiras horas de vida e mantida por 4 semanas.","B":"O recém-nascido deverá receber AZT 4 mg/kg/dia a cada 12 horas durante 4 semanas com\ninício nas primeiras 72 horas de vida e NVP (Nevirapina), também nas primeiras 72h de vida.","C":"O recém-nascido deverá receber AZT 4 mg/kg/dia a cada 12 horas durante 4 semanas a partir\nda quarta semana de vida e NVP em três doses\nsemanais.","D":"O recém-nascido deverá receber AZT 4 mg/kg/dose a cada 12 horas a ser inciada,\npreferencialmente, nas primeiras 2horas de vida e NVP\ntrês doses, sendo a primeira dose nas\nprimeiras 48h de vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249465","number":"249465","sourceNumber":"249465","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na pneumonia por Pneumocistose PCP moderada a grave (PaO2 <70MMHG) é\nrecomendado esquemas administrados preferencialmente por via EV. Indique o item com erro:","options":{"A":"A mudança de via de administração de endovenosa para oral deve ser realizada quando ocorrer\nmelhora clínica.","B":"Clindamicina 600mg EV a cada seis ou oito horas + primaquina 15-30mg VO uma vez ao dia é o\nprincipal esquema alternativo em caso de intolerância à sulfa.","C":"O esquema de escolha é a associação SMX-TMP (5mg/kg de TMP) endovenosa a cada seis ou\noito horas. O tempo total de tratamento é de 10 dias.","D":"A associação de corticosteroides ao tratamento de PCP moderada a grave apresentou redução\nimportante na mortalidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249472","number":"249472","sourceNumber":"249472","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A pesquisa direta do agente oportunista em amostras de escarro espontâneo ou\ninduzido geralmente é pouco sensível para\nPneumocistose PCP. Podemos apenas concordar que:","options":{"A":"O diagnóstico definitivo não é realizado pela identificação do agente por meio das colorações de\nazul de toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes\nrespiratórios.","B":"O diagnóstico definitivo é realizado pela identificação do agente por meio das colorações de azul\nde toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes fora do\nsistema respiratório.","C":"O diagnóstico definitivo é realizado pela identificação do agente por meio das colorações de azul\nde toluidina, Grocott, Giemsa ou técnica de imunofluorescência a partir de espécimes respiratórios.","D":"O diagnóstico definitivo é realizado sem a identificação do agente por meio das colorações de\nazul de toluidina, a partir de espécimes respiratórios."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249476","number":"249476","sourceNumber":"249476","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os principais achados pneumocistose ao exame físico incluem taquipneia, taquicardia e\nausculta pulmonar normal ou com estertores finos ao final da expiração. Sibilos, sinais de\ncondensação pulmonar ou derrame pleural são raramente encontrados. Somente mostra erro o\nitem:","options":{"A":"O achado radiográfico mais típico de PCP é o infiltrado intersticial periférico e assimétrico.","B":"Pneumatoceles e pneumotórax também podem ser observados.","C":"Rx de tórax pode ser normal em até um quarto dos casos de PCP.","D":"TC pode revelar atenuação pulmonar em vidro fosco."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247426","number":"247426","sourceNumber":"247426","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre infecções oportunistas no paciente adulto com AIDS (Acquired Immunodeficiency\nSyndrome), assinale a CORRETA:","options":{"A":"A profilaxia secundária para pneumocistose com sulfametoxazol-trimetoprim pode ser\ndescontinuada após aumento de linfócito T CD4\npara acima de 200 células/mm³, por pelo menos\ntrês meses.","B":"Doença disseminada pelo complexo Mycobacterium avium tipicamente ocorre em pacientes com\ncontagem de linfócitos T CD4 menor ou igual a 100 células/mm³. Para esses pacientes está\nindicado profilaxia com azitromicina.","C":"O uso de corticoides como terapia adjunta para pneumocistose está fortemente contraindicado\npelo risco de disseminação da doença.","D":"A neurotoxoplasmose no paciente com AIDS é uma doença de reativação e, portanto, a\npresença de Imunoglobulina (Ig) M sérica\nanti-toxoplasma é fundamental para seu diagnóstico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-252765","number":"252765","sourceNumber":"252765","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Infecções respiratórias recorrentes são muito comuns na prática clínica pediátrica.\nAproximadamente 50% das crianças com infecções recorrentes são saudáveis, 30% têm algum tipo\nde alergia, 10% são portadores de patologias crônicas e 10% podem apresentar algum grau de\nimunodeficiência. Sobre imunodeficiências em pediatria, é correto afirmar que:","options":{"A":"As imunodeficiências primárias são defeitos de um ou mais componentes do sistema\nimunológico e raramente têm caráter congênito ou hereditário.","B":"A deficiência seletiva de IgA é a doença de maior prevalência dentre todas as imunodeficiências\nprimárias.","C":"Nas deficiências celulares, o crescimento pôndero-estatural é normal, pois o início das\nmanifestações clínicas é tardio, ocorrendo após a adolescência.","D":"Nas deficiências terminais do sistema complemento geralmente os quadros infecciosos são\nbrandos e autolimitados."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-232284","number":"232284","sourceNumber":"232284","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação aos cuidados imediatos com o recém-nascido (RN) exposto ao HIV,\ndeve-se:","options":{"A":"realizar o parto empelicado, fazendo a retirada do neonato, mantendo-se as membranas\namnióticas íntegras.","B":"clampear o cordão umbilical após um minuto da extração do concepto, ou até que a pulsação no\ncordão cesse, sem qualquer ordenha.","C":"evitar a realização do banho nas primeiras 24 horas subsequentes ao parto. Só limpar o RN com\ncompressas macias e úmidas.","D":"cancelar a aspiração das vias aéreas do RN, a fim de se evitar traumatismos em mucosas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249538","number":"249538","sourceNumber":"249538","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O cuidado contínuo em HIV pode ser entendido como o processo de atenção aos\nusuários que vivem com HIV, que são entendidos como momentos, sendo que a dita Vinculação\nseria adequadamente determinada pela seguinte alternativa.","options":{"A":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível, mas não desenvolva autonomia para o cuidado\ncontínuo. O desfecho principal para considerar uma PVHIV vinculada é a realização da primeira\nconsulta no serviço de atenção para o qual foi encaminhada e, de preferência, seu início de\ntratamento o mais rápido possível.","B":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível e desenvolva autonomia para o cuidado contínuo.\nO desfecho principal para considerar uma PVHIV vinculada é a realização da primeira consulta no\nserviço de atenção para o qual foi encaminhada e, de preferência, seu início de tratamento o mais\nrápido possível.","C":"Processo que consiste no acolhimento, orientação, direcionamento e encaminhamento de uma\npessoa recém-diagnosticada com HIV ao serviço de\nsaúde, para que ela realize as primeiras\nconsultas e exames o mais brevemente possível e desenvolva autonomia para o cuidado contínuo.\nO desfecho principal para considerar uma PVHIV vinculada é a realização da primeira consulta no\nserviço de atenção para o qual foi encaminhada e, de preferência, seu início de tratamento sendo\ndesnecessário rapidez.","D":"Processo que consiste direcionamento apenas para encaminhamento de uma pessoa\n\nrecém-diagnosticada com HIV ao serviço de saúde, para que ela realize as primeiras consultas e\nexames o mais brevemente possível e\ndesenvolva autonomia para o cuidado contínuo. O desfecho\nprincipal para considerar uma PVHIV vinculada é a realização da primeira consulta no serviço de\natenção para o qual foi encaminhada e, de preferência, seu início de tratamento o mais rápido\n\npossível."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249540","number":"249540","sourceNumber":"249540","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recomenda-se que os testes de genotipagem do HIV, sejam realizados o mais\nprecocemente possível em relação ao diagnóstico da falha. Somente sendo incorreto que:","options":{"A":"nas situações de CV-HIV baixa, os testes de genotipagem podem ser menos eficazes, pois a\namplificação das sequências pode ser frustrada.","B":"além disso, subpopulações minoritárias portadoras de mutações de resistência sempre serão\ndetectadas.","C":"a CV persistente, mesmo baixa, leva a acúmulo de mutações e resistência cruzada nas classes\ndos medicamento sem uso.","D":"cerca de 60% dos pacientes mantidos com supressão viral parcial desenvolvem novas mutações\nde resistência após 18 meses."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247476","number":"247476","sourceNumber":"247476","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente gestante de 35 anos, com 39 semanas, cesárea eletiva. Gestação sem\nintercorrências. Tem sorologia HIV positiva, com diagnóstico há 4 anos, em seguimento adequado.\nCarga viral negativa. Fez uso de AZT (zidovudina) oral a partir da 14ª quarta semana de gestação.\nO bebê nasce em boas condições, é colocado em berço aquecido, secado, aspirado suavemente\nas vias aéreas e levado ao banho com água e sabão. Em relação ao recém-nascido, quais são as\ncondutas e orientações a seguir mais adequadas?","options":{"A":"AZT endovenoso 1 dose de 2 mg/Kg no recém-nascido na sala de parto após 8 horas iniciar a\nmedicação AZT de 6/6 horas por 6 semanas. Não amamentar ao seio materno. Colher sorologias\ntoxoplasmose, rubéola, hepatite C e B, citomegalovírus, herpes simples, hemograma e provas de\nfunção hepática com 42 dias de vida.","B":"AZT endovenoso 1 dose de 2mg/Kg na sala de parto. Colher sorologia HIV, toxoplasmose,\nrubéola, hepatite C e B, citomegalovírus, herpes\nsimples, hemograma de sangue periférico e\naguardar resultados para conduta. Não amamentar ao seio materno e prescrever fórmula infantil.","C":"Não amamentar ao seio materno, prescrever fórmula infantil, prescrever AZT oral de 6 em 6\nhoras por 6 semanas, iniciar de preferência nas primeiras 2 horas de nascimento. Colher\nhemograma, provas de função hepática e sorologias toxoplasmose, rubéola, hepatite C e B,\ncitomegalovírus, herpes simples e sífilis.","D":"Liberar seio materno na primeira hora de vida. Iniciar AZT oral após 48 horas de vida, devido\ncarga viral materna negativa. Colher sorologias HIV, toxoplasmose, rubéola, hepatite C e B,\ncitomegalovírus, herpes simples e hemograma de sangue periférico. Aguardar resultado para\nconduta."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247477","number":"247477","sourceNumber":"247477","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente gestante de 35 anos, com 39 semanas, cesárea eletiva. Gestação sem\nintercorrências. Tem sorologia HIV positiva, com diagnóstico há 4 anos, em seguimento adequado.\nCarga viral negativa. Fez uso de AZT (zidovudina) oral a partir da 14ª quarta semana de gestação.\nO bebê nasce em boas condições, é colocado em berço aquecido, secado, aspirado suavemente\nas vias aéreas e levado ao banho com água e sabão. Qual é o principal efeito colateral do uso de\nAZT no recém-nascido?","options":{"A":"Hepatite medicamentosa.","B":"Hipotireoidismo.","C":"Leucemia.","D":"Anemia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-249557","number":"249557","sourceNumber":"249557","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As indicações terapêuticas para as pessoas que apresentam coinfecção HCV-HIV são\nas mesmas preconizadas para pacientes não\nco-infectados HCV-HIV. Está correto apenas que:","options":{"A":"Para os pacientes cujo diagnóstico de ambas as infecções ocorre concomitantemente, é\naconselhável iniciar, primeiramente, o tratamento para o HIV e atingir a supressão viral antes de\niniciar o tratamento para o HCV ? especialmente em pacientes com imunossupressão grave\n(contagem de LT-CD4+ <200 células/mm3).","B":"Para os pacientes cujo diagnóstico de ambas as infecções ocorre concomitantemente, é\naconselhável iniciar, primeiramente, o tratamento para o HIV e atingir a supressão viral antes de\niniciar o tratamento para o HCV ? especialmente em pacientes com imunossupressão leve\n(contagem de LT-CD4+ <200 células/mm3).","C":"Para os pacientes cujo diagnóstico de ambas as infecções ocorre concomitantemente, é\naconselhável iniciar, primeiramente, o tratamento para o HCV ? especialmente em pacientes com\nimunossupressão grave (contagem de LT-CD4+ <200 células/mm3).","D":"Para os pacientes cujo diagnóstico de ambas as infecções ocorre concomitantemente, é\naconselhável iniciar, primeiramente, o\ntratamento para o HIV e atingir a supressão viral após iniciar\no tratamento para o HCV ? especialmente em pacientes com imunossupressão grave (contagem de\nLT-CD4+ <20 células/mm3)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-229596","number":"229596","sourceNumber":"229596","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A epidemia de AIDS e os seus efeitos devastadores nas pessoas vivendo com o HIV ?\ndentre eles a alta letalidade e o aumento de casos de TB resistente aos medicamentos, somente\nNÃO podemos aceitar que:","options":{"A":"Ocorre alta letalidade e o aumento de casos de TB resistente aos medicamentos.","B":"Há uma alta concentração da TB em populações vulneráveis socialmente.","C":"Não surgem novidades nos campos diagnósticos e terapêuticos.","D":"Há Necessidade de priorização no combate à doença, seja em nível global ou nacional."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-201660","number":"201660","sourceNumber":"201660","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O interferon-Y, como outros interferons, tem a capacidade de interferir nas infecções\nvirais. Essa substância:","options":{"A":"Tem como principal ação a resposta imune à infecção viral.","B":"Inibe a atuação de macrófagos e monócitos.","C":"Tem importante papel na diferenciação de células CD4 T.","D":"Atua estimulando a diferenciação de linfócitos em células Th2."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-218242","number":"218242","sourceNumber":"218242","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual célula é identificada principalmente pela presença de imunoglobulina sobre sua\nsuperfície?","options":{"A":"Célula T.","B":"Célula NK.","C":"Linfócito B.","D":"Macrófago."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-210587","number":"210587","sourceNumber":"210587","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considere: paciente de 46 anos, portador de HIV diagnosticado há 3 anos, em\ntratamento irregular com antirretrovirais, queixa\nastenia, tosse e dispneia progressiva há 15 dias.\nAdmitido no Pronto Atendimento, realiza a seguinte tomografia de tórax: Quanto ao manejo clínico\ndo caso, assinale a alternativa correta.","options":{"A":"A gasometria arterial do paciente deve revelar pO2 acima de 70mmHg.","B":"A dosagem de CD4 deve estar inferior a 50 células/mm3.","C":"Os efeitos adversos do tratamento de primeira linha seriam hepatite, nefrite e pancitopenia.","D":"O corticoide não apresentaria benefício nesses casos.","E":"O uso de profilaxia prévia afastaria o diagnóstico de pneumocistose pulmonar."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-214921","number":"214921","sourceNumber":"214921","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em pacientes infectados pelo vírus HIV, qual o mecanismo patogênico que justifica a\nfrequência de cerca de 40% ao longo da vida de tumores malignos (linfoma não Hodking, sarcoma\nde Kaposi):","options":{"A":"células pelo HIV apresentam oncogenes que levam ao desenvolvimento de câncer","B":"formação de proteínas quiméricas pró-carcinogênicas pelo genoma viral","C":"imunodeficiência causada pela infecção pelo HIV","D":"ativação de oncogenes pela transcriptase reversa do vírus HIV"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-217023","number":"217023","sourceNumber":"217023","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A infecção pelo HIV ainda é muito frequente em nosso meio. Além das chamadas\n\"doenças oportunistas\", sabe-se que a patologia\npode comprometer outros sistemas, sobretudo\nquando lactentes ou crianças jovens são expostos ao vírus. Com relação às manifestações da\ninfecção por HIV, assinale a alternativa incorreta.","options":{"A":"Os sinais neurológicos da encefalopatia da AIDS podem surgir nos primeiros meses de vida ou\nse manisfestar em torno dos 5 anos de idade.","B":"De modo geral, crianças infectadas ao nascimento apresentam boa resposta imune, o que indica\na vacinação precoce. O uso de vacinas inativadas\nnão oferece risco a esses pacientes.","C":"O tratamento antirretroviral deve ser realizado em todas as crianças menores de 12 meses,\nindependentemente de sintomatologia, carga viral ou estado imunológico.","D":"Em crianças maiores de 6 anos com contagem de CD4+ < 500 células/mm³, é recomendado\ntratamento antirretroviral urgente.","E":"O curso clínico da infecção por HIV é mais rápido na criança do que no adulto, devido à\nimaturidade imunológica, e progressivamente maior quanto menor a idade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205568","number":"205568","sourceNumber":"205568","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O uso de antirretroviral ARV pode aumentar o risco cardiovascular RCV pela\ndislipidemia, os benefícios superam o pequeno risco observado com seu uso. Sendo\nINADEQUADO que:","options":{"A":"É importante ressaltar que as ferramentas utilizadas na prática clínica para estimar o RCV em\npacientes com HIV foram desenhadas para a população geral.","B":"O próprio HIV é um fator de risco para doença cardiovascular.","C":"As ferramentas podem subestimar o risco real de DCV nas pessoas vivendo com HIV PVHIV.","D":"O intervalo da reavaliação do risco cardiovascular RCV não varia de acordo com o risco inicial e\no esquema antirretroviral ARV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205574","number":"205574","sourceNumber":"205574","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Dados relativos aos mecanismos fisiopatogênicos da doença hepática induzida pelo\nálcool sugerem que a infecção pelo HIV pode exacerbar essa doença, uma vez que, tanto o vírus\nquanto o álcool, atuam em alvos comuns, alterando a permeabilidade intestinal e elevando os\nníveis séricos de lipopolissacarídeos, o que determina um agravamento na progressão da doença\nhepática. Sendo INCORRETO que:","options":{"A":"O uso de álcool é mais frequente em PVHIV que na população geral. O uso excessivo de álcool\nestá associado à esteatose hepática, a qual, se persistente, pode levar a esteato-hepatite, fibrose\nhepática e cirrose hepática.","B":"A suspeita de doença hepática alcoólica normalmente deriva da observação clínica, mas não\ndos hábitos do paciente.","C":"Deve-se investigar rotineiramente a quantidade e o padrão de ingestão de álcool.","D":"Os testes de lesão e função hepática podem ser úteis na investigação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205590","number":"205590","sourceNumber":"205590","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pacientes infectados pelo HIV podem desenvolver várias complicações ligadas aos\nossos, sendo INADEQUADO o seguinte item:","options":{"A":"Essas incluem baixa densidade mineral óssea (osteopenia), osteoporose, osteonecrose e, mais\nraramente, osteomalácia.","B":"Dentre estas, osteopenia e osteoporose são as mais comuns.","C":"Estima-se que 50% das mulheres e 25% dos homens com mais de 50 anos terão uma fratura de\nfragilidade relacionada à osteoporose no restante de suas vidas.","D":"A ocorrência de uma fratura de fragilidade é, em geral, inadequada para diagnosticar\nosteoporose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205608","number":"205608","sourceNumber":"205608","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A presença de doença gordurosa não alcoólica tem sido associada a maior risco de\ndoença cardíaca e diminuição de sobrevida na\npopulação geral. Não há tratamento medicamentoso\nespecífico para essa condição, devendo-se instituir, sempre que possível, medidas gerais que\npossam contribuir para a modificação dos fatores preditivos. Sendo INADEQUADO que:","options":{"A":"A esteatose hepática está relacionada a uma progressão mais acelerada de fibrose hepática.","B":"O diagnóstico definitivo fundamenta-se na investigação de marcadores séricos indiretos de\nfibrose hepática (TGO, TGP, albumina, INR, plaquetas) e de biópsia hepática, não é mais\nconsiderada o padrão-ouro.","C":"Outros métodos que podem ser utilizados são a ultrassonografia, com sensibilidade moderada\n(60% a 94%) e especificidade alta (84% a\n95%), o fibroscan e a RM.","D":"O tratamento da NASH se baseia no controle das condições associadas ? perda de peso,\natividade física, tratamento do DM e mudança\nnos hábitos alimentares, com redução da ingestão\nde açúcares/carboidratos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205622","number":"205622","sourceNumber":"205622","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recomenda-se designar uma ou mais pessoas para elaborar e monitorar o plano de\ncontrole da TB, adaptado às condições da instituição. Dentro do plano de controle de infecção\ntuberculosa em Serviços de Atenção Especializada SAE, somente NÃO podemos aceitar que\nocorra o seguinte, assinale-o:","options":{"A":"Identificar problemas relacionados à adequada ventilação do ambiente, mas nunca propor ou\nencaminhar soluções.","B":"Identificar responsáveis por elaborar e monitorar o plano.","C":"Fazer um diagnóstico da situação da coinfecção na unidade com os principais indicadores\nrelacionados as duas doenças.","D":"Identificar responsáveis pelas etapas previstas no plano."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-205634","number":"205634","sourceNumber":"205634","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Para adequado referenciamento de pacientes a outros serviços, os Serviços de\nAtenção Especializada (SAE) somente NÃO devem aceitar o seguinte item:","options":{"A":"No entanto, o SAE continuará responsável pelo manejo clínico e acompanhamento desses\npacientes.","B":"Casos de resistência aos medicamentos de tuberculose não deverão ser encaminhados às\nreferências terciárias de TB, para definição do melhor esquema terapêutico antituberculose.","C":"Efeitos adversos menores ao tratamento da tuberculose deverão ser manejados no SAE.","D":"Efeitos adversos maiores poderão ser manejados no SAE, dependendo da estrutura local, ou\nencaminhados a outras referências secundárias da TB."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-178745","number":"178745","sourceNumber":"178745","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma das complicações no tratamento da síndrome da imunodeficiência adquirida\n(SIDA) é a nefrotoxicidade dos\nantirretrovirais (ARV). Qual, dos seguintes ARV, está relacionado\ncom doença renal crônica?","options":{"A":"Abacavir.","B":"Lamivudina.","C":"Tenofovir.","D":"Zidovudina.","E":"Elvitegravir."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-175410","number":"175410","sourceNumber":"175410","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"É correto afirmar, sobre a infecção aguda por HIV (vírus da imunodeficiência humana),\nque:","options":{"A":"cerca de 70% dos pacientes são assintomáticos","B":"o diagnóstico clínico é obtido em cerca de 80% dos pacientes que apresentam sintomas","C":"meningite com predomínio linfomonocitário e cultura negativa pode ser atribuída a infecção\naguda pelo HIV","D":"a sorologia para HIV (ELISA no soro ou teste rápido) torna-se positiva em média 90 dias após a\ninfecção, pois detecta anticorpos da classe IgG, os quais aparecem tardiamente","E":"nenhuma das anteriores"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-185128","number":"185128","sourceNumber":"185128","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Deve-se iniciar a terapia antirretroviral em pacientes com HIV","options":{"A":"apenas quando a contagem de CD4 < 350.","B":"quando CD4 < 200 e carga viral superior a 1.000 cópias.","C":"com alguma carga viral detectável, independente da contagem de CD4.","D":"apenas quando a contagem de CD4 > 350 e carga viral superior a 1.000 cópias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157037","number":"157037","sourceNumber":"157037","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em pacientes infectados pelo vírus HIV, qual o mecanismo patogênico que justifica a\nfrequência de cerca de 40% ao longo da vida de tumores malignos (linfoma não Hodking, sarcoma\nde Kaposi)?","options":{"A":"Células pelo HIV apresentam oncogenes que levam ao desenvolvimento de câncer.","B":"Formação de proteínas quiméricas pró-carcinogênicas pelo genoma viral.","C":"Imunodeficiência causada pela infecção pelo HIV.","D":"Ativação de oncogenes pela transcriptase reversa do vírus HIV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-160563","number":"160563","sourceNumber":"160563","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 31 anos foi admitido no pronto-socorro com insuficiência respiratória de\ninício insidioso e evolução progressiva. Além\nda dispneia, apresentava também tosse seca há 20\ndias, associada à adinamia. Não havia relato de febre. Ao exame físico, apresentava ausculta\nrespiratória normal e oximetria de pulso com 87% de saturação de O?. Exames complementares\nevidenciaram anemia normocítica e normocrômica, desidrogenase láctica aumentada, e radiografia\nde tórax com infiltrado difuso bilateralmente de predomínio peri-hilar. Teste rápido para HIV foi\npositivo. Como o paciente refere alergia a sulfas, o tratamento de escolha nesses casos é:","options":{"A":"ciprofloxacina.","B":"dapsona.","C":"clindamicina + primaquina.","D":"dapsona + pentamidina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157268","number":"157268","sourceNumber":"157268","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No caso de um RN termo, nascido de parto cesáreo, de uma mãe com diagnóstico de\ninfecção por HIV na internação para o parto, que não realizou pré-natal, mas utilizou AZT periparto\ncorretamente, qual a quimioprofilaxia indicada?","options":{"A":"AZT oral nas primeiras 4 horas de vida e, depois, 2 doses ao dia durante 6 semanas.","B":"AZT oral nas primeiras 4 horas de vida e, depois, 2 doses ao dia durante 4 semanas.","C":"AZT oral nas primeiras 4 horas de vida e, depois, 2 doses ao dia durante 6 semanas e\nNevirapina 3 doses; a primeira com até 24\nhoras de vida; a segunda, 24 horas após a 1ª dose; a\nterceira, 24 horas após a 2ª dose.","D":"AZT oral nas primeiras 4 horas de vida e, depois, 2 doses ao dia durante 4 semanas e\nNevirapina uma dose diária durante 4 semanas.","E":"AZT oral nas primeiras 4 horas de vida e, depois, 2 doses ao dia durante 4 semanas e\nNevirapina 3 doses; a primeira com até 48\nhoras de vida; a segunda, 48 horas após a 1ª dose; a\nterceira, 96 horas após a 2ª dose."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-156522","number":"156522","sourceNumber":"156522","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Esquema utilizado para prevenção de transmissão vertical do vírus HIV, para neonatos.","options":{"A":"Oseltamivir","B":"Zidovudina","C":"Vanganciclovir","D":"Estavudina"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-127991","number":"127991","sourceNumber":"127991","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 16 anos com cefaléia e congestão nasal há 5 dias. No dia do atendimento,\nevoluiu com edema de olho direito, cefaléia\nfrontal à direita e vômitos. O exame físico revela\npaciente letárgico, mas despertável, proptose do olho direito e congestão nasal. A nuca está livre,\ne\nnão há outra alteração no exame físico. O exame a ser realizado, nesse caso, será:","options":{"A":"Punção lombar","B":"Ressonância magnética do cérebro e dos seios da face","C":"Cultura de aspirado em orofaringe","D":"Painel toxicológico"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-141547","number":"141547","sourceNumber":"141547","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A infecção urinária tem como bactéria mais frequente:","options":{"A":"Enterococcus faecalis.","B":"Staphylococcus saprophyticus.","C":"Escherichia coli.","D":"Klebsiella sp."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-136560","number":"136560","sourceNumber":"136560","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual dos antimicrobianos se mostra inefetivo para o tratamento de bactérias sem\nparede celular (atípicas) causadoras de pneumonia?","options":{"A":"Meropenem.","B":"Claritromicina.","C":"Levofloxacino.","D":"Moxifloxacino."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-129916","number":"129916","sourceNumber":"129916","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, vendedora, procurou atendimento médico para\navaliação de rotina. Paciente sem queixas. Nega comorbidades. Apresentava exame físico normal.\nForam solicitados hemograma, glicemia de jejum, lipidograma, ureia, creatinina, alanina\naminotransaminase, aspartato aminotransaminase, exame simples de urina e urocultura. Paciente\nretornou após uma semana com o resultado dos exames. Persistia assintomática. Os exames\napresentaram todos os resultados normais, exceto a urocultura que mostrou crescimento de\nEscherichia coli produtora de Betalactamase de Espectro Estendido (ESBL). O antibiograma\nindicou sensibilidade a amicacina, colistina, piperacilina-tazobactam e carbapenêmicos. Qual a\nconduta indicada para este paciente?","options":{"A":"Internação e início de antibioticoterapia endovenosa com meropenem 1 g, de 8 em 8 horas.","B":"Internação e início de antibioticoterapia endovenosa com meropenem em dose dobrada.","C":"Início de antibioticoterapia endovenosa com amicacina 1 g, uma vez ao dia, em regime\nambulatorial.","D":"Orientação à paciente de retornar, caso apresente sintomas, e não iniciar tratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-127317","number":"127317","sourceNumber":"127317","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre a história natural da infecção pelo vírus HIV, analise as proposições elencadas a\nseguir: I. A doença Aids (ou SIDA) ocorre, em média, cerca de 1 a 2 anos após o paciente ter sido\ninfectado; II. Os anticorpos anti-HIV podem não ser detectáveis (anti-HIV Elisa falso-negativo) nas\nprimeiras 4 a 6 semanas após o indivíduo ter sido infectado, o que se denomina ?janela\nimunológica?; III. As manifestações clínicas da infecção primária pelo HIV, quando ocorrem,\ngeralmente acontecem de 2 a 4 semanas após o indivíduo ter sido infectado. A infecção primária\npelo HIV é autolimitada e tem duração de cerca de 2 a 4 semanas; IV. É comum um período de\nlatência clínica, isto é, ausência de sintomas, entre a infecção primária pelo HIV e as\nmanifestações\nclínicas de Aids. Esse período dura, em média, em torno de 8 a 10 anos; V. Na infecção primária\npelo HIV, tipicamente ocorre queda do CD4. Algumas semanas depois, há elevação do CD4 para\nníveis inferiores a antes da infecção primária, e, em seguida, ao longo dos anos, vai diminuindo\nprogressivamente. Estão CORRETAS as proposições contidas em:","options":{"A":"I, II e III, apenas.","B":"II, III, IV e V, apenas.","C":"II e V, apenas.","D":"I, II, III, IV e V."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-136543","number":"136543","sourceNumber":"136543","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual é o método de escolha para o diagnóstico de infecção do trato urinário em\nPediatria?","options":{"A":"Urina tipo 1.","B":"Urografia excretora.","C":"Uretrocistografia.","D":"Urocultura."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-110204","number":"110204","sourceNumber":"110204","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"João Antônio, 6 anos de idade, foi conduzido à UBS, por estar apresentando, há 4\nmeses, alteração de comportamento, com\nirritabilidade e choro fácil. Segundo a mãe do menor, há\num mês vem observando também movimentos desordenados dos braços e pernas, principalmente\nquando ocorre algum estímulo, levando a quedas frequentes. Nega presença dos movimentos\ndurante o sono. No início, achou que a criança estava \"fazendo manha\", pois os sintomas iniciaram\nlogo após a viagem da avó do menor. Mas como tem persistido, ficou preocupada e resolveu\nprocurar o serviço médico. Nega presença de qualquer outro sintoma. Quando perguntada sobre os\nantecedentes pessoais fisiológicos e patólogicos da criança, a mãe referiu que o menor nasceu de\nparto normal, hospitalar, sem intercorrências, com desenvolvimento neuropsicomotor adequado\npara a idade, sendo internado duas vezes com diarreia e vômito (com 2 e 4 anos de idade). Há 7\nmeses a criança teve um episódio de gripe e há 6 meses, amigdalite. No exame físico geral, o\nmédico anotou os seguintes achados: BEG, ativo, eupneico, normocárdico, anictérico, acianótico,\nhidratado, consciente, orientado. Presença de movimentos involuntários rápidos, arrítmicos e\nincoordenados de membros superiores e inferiores. No exame físico cardiovascular de João\nAntônio, o médico auscultou presença de sopro sistólico apical com irradiação para a axilia, sem\nvariação com a posição do paciente. Foi realizado RX de tórax, que não mostrou alterações e ECG\nque apresentou alongamento do espaço PR. A mãe do menor informou ao médico que nunca\nhaviam falado que seu filho tinha \"problema de coração\". Correlacionando os dados do texto, os\ndados do exame cardiovascular e o resultado do RX de tórax e ECG, qual o provável acometimento\ncardiológico de João Antônio?","options":{"A":"Pericardite.","B":"Miocardite.","C":"Endocardite.","D":"Pancardite."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-109204","number":"109204","sourceNumber":"109204","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em paciente com SIDA, apresentando linfonodomegalia hilar, mediastinal e\nacometimento intersticial pulmonar em associação\ncom quadro neurológico de meningite, deve-se\nsuspeitar de:","options":{"A":"Linfoma.","B":"P. carinii.","C":"Histoplasmose.","D":"Criptococose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103676","number":"103676","sourceNumber":"103676","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com a expansão cada vez maior do vírus do HIV, sempre devemos aventar a\npossibilidade de o quadro respiratório ser\nrelacionado com o mesmo, caso o paciente seja portador\ndo vírus. Assim, torna importante papel como complicador das infecções por pneumocistose, que\npossui como característica:","options":{"A":"a radiologia, usualmente, não apresenta grandes alterações.","B":"elevação dos valores do DHL.","C":"gasometria com retenção de CO2.","D":"ausculta rica e com ênfase na estertoração."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103692","number":"103692","sourceNumber":"103692","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente feminina de 70 anos apresentou agitação e desorientação na última semana,\ninclusive deixando de se medicar adequadamente de vez que a mesma é hipertensa crônica. Não\napresenta queixas respiratórias, porém, se queixa de mal estar e está algo agressiva. Nesse caso,\npodemos AFIRMAR que:","options":{"A":"desorientações em idosos obrigam a pesquisa de infecções, mesmo sendo subclínicas.","B":"como não há queixa de febre, não devemos explorar possibilidade de infecção.","C":"quadros demenciais são a principal causa de desorientação em idosos.","D":"a melhor conduta é prescrever ansiolíticos para acalmar a idosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103723","number":"103723","sourceNumber":"103723","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual é a condição indispensável para a gênese da endocardite infecciosa (EI)? I.\nEndotélio intacto. II. Endotélio exposto. III. Endocardite trombótica não infecciosa. IV. Agente\ninfeccioso na corrente sanguínea. V. Porta de entrada visível do agente microbiano. São\nCORRETAS as proposições contidas, APENAS, em:","options":{"A":"I, II e IV.","B":"I, III e IV.","C":"II, III e IV.","D":"II, III e V."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-83687","number":"83687","sourceNumber":"83687","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 27 anos apresenta mal-estar, tontura, sudorese e confusão iniciados há\n12h. Há 3h apresentou uma crise epiléptica. Exame físico: confuso e agressivo. Temperatura\n39,2°C, PA 80 x 40 mmHg, pulso 123 bpm, frequência respiratória 32 ipm, extremidades frias e\ncianóticas. Em relação ao caso descrito, é correto afirmar:","options":{"A":"Os vasopressores são indicados imediatamente e podem melhorar o nível de consciência do\npaciente.","B":"Proteína C ativada recombinante intravenosa está recomendada porque reduz mortalidade\nnessa circunstância.","C":"A ausência de melhora da pressão arterial com reposição volêmica agressiva caracteriza o\nchoque séptico.","D":"O quadro clinico é inespecífico, podendo ocorrer em qualquer tipo de choque (cardiogênico,\nséptico e hipovolêmico).","E":"A punção do liquor é de grande importância diagnóstica e deve ser realizada imediatamente\nantes de quaisquer outros exames."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-78156","number":"78156","sourceNumber":"78156","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"As infecções causadas pelo Staphylococcus aureus meticilinorresistente da\ncomunidade (SAMRC) destacam-se pela gravidade.\nDiante de um quadro de Sepsis que tenha\ncomo foco infeccioso a pele e um SAMRC como agente mais provável, qual dos antibióticos abaixo\nseria a melhor opção terapêutica?","options":{"A":"Ampicilina-sulbactam","B":"Cefepime","C":"Clindamicina","D":"Tigeciclina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-63697","number":"63697","sourceNumber":"63697","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No estágio ambulatorial de medicina interna da UniEvangélica a Sra. Julieta, 22 anos, é\natendida com histórico de diabetes mellitus do tipo I há 12 anos. A paciente vem ao consultório com\nqueixa de disúria e poliaciúria recorrente há 1 ano, desde que se casou. Refere não estar fazendo\ncontrole rigoroso de glicemia no último ano e que ganhou 5 quilos no período. Ainda refere ter\nusado vários métodos contraceptivos, mas adaptou-se melhor com espermicida, método que vem\nutilizando desde o início do relacionamento conjugal. Que assertiva melhor descreve a hipótese\ndiagnóstica e conduta terapêutica apropriada?","options":{"A":"Infecção urinária baixa. Deve ser usado antibioticoterapia preferencialmente guiada por cultura,\nbem como controle glicêmico rigoroso e\nmodificação do método contraceptivo.","B":"Infecção urinária baixa. Deve ser usado antibioticoterapia sem preocupação com cultura, bem\ncomo controle glicêmico rigoroso. Não há\nnecessidade de modificação do método contraceptivo\nsendo este, inclusive, fator protetor contra infecções do trato urinário.","C":"Infecção urinária baixa. Deve ser usado antibioticoterapia preferencialmente guiada por cultura,\nbem como controle glicêmico rigoroso. A\nmodificação do método contraceptivo não influencia no\naumento ou diminuição da incidência de infecção urinária.","D":"Infecção urinária alta. Deve ser usado antibioticoterapia de largo espectro bem como controle\nglicêmico rigoroso. Deve ser feita a modificação do método contraceptivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-63696","number":"63696","sourceNumber":"63696","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Você está fazendo estágio de intercâmbio no estado de São Paulo atendendo no\nambulatório geral de adultos de um hospital\nterciário. Em um dos atendimentos você conheceu o\nSr. José das Dores, 50 anos, comerciante. Sr. José afirmou que nunca tinha ficado doente durante\na vida. Na consulta o paciente referiu estar com quadro febril diário de 38,5°C por cerca de 1 mês.\nReferiu que, na semana anterior, havia sido atendido por outro médico que conversou com o\npaciente por mais de 1 hora e o examinou \"do pé à cabeça\". Fez também vários exames de\nsangue, todos com resultado normal, não conseguindo fazer o diagnóstico do caso. Sr. José referiu\nnão apresentar mais febre havia 3 dias e ao exame físico não apresentou qualquer alteração, além\nde estar se sentindo bem. Você solicitou uma ampla avaliação de exames complementares e o\npaciente retorna com os resultados todos normais em duas semanas. Inclusive não apresentou\nfebre no período. Assinale a assertiva mais condizente com a hipótese diagnóstica do Sr. José.","options":{"A":"Pacientes com quadro clínico semelhante ao do Sr. José geralmente têm doença de evolução\nmaligna não manifestada. Se bem investigado, é improvável o Sr. José não ter um diagnóstico.","B":"O diagnóstico sindrômico do Sr. José é de febre de origem indeterminada. Pacientes com tal\nmanifestação, que não tem diagnóstico a despeito de extensa e completa investigação, geralmente\ntêm bom prognóstico, com resolução da febre em semanas ou meses.","C":"Dentre as possibilidades diagnósticas do paciente estão doenças infecciosas, imunológicas ou\nneoplásicas. A febre do Sr. José provavelmente se associa a um quadro infeccioso não percebido.","D":"Algumas lesões de pele como petéquias subconjuntivais, se presentes no Sr. José, não estariam\nligadas a nenhuma hipótese diagnóstica mais grave."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-61729","number":"61729","sourceNumber":"61729","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem de 26 anos tem um dente ?siso? molar impactado extraído. Várias\nsemanas mais tarde, ele tem febre, seguida\nvários dias depois por cefaleia. Uma tomografia de\ncrânio revela uma lesão em anel de 3.5 centímetros na região parietal direita. Além disso, a\nausculta o paciente demonstra um sopro em crescendo/decrescendo e uma leve vibração no\nsegundo espaço intercostal da borda external direita. Uma cultura sanguínea mostra cultura de\ncrescimento positiva rica em catalase e coagulase. Quais dos seguintes achados de exame físico\napontam para a lesão que aumentou o risco dessas complicações?","options":{"A":"Sopro na carótida direita.","B":"Estenose Mitral.","C":"Regurgitação Mitral.","D":"Prolapso da válvula mitral.","E":"Sopro de ejeção sistólica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-61264","number":"61264","sourceNumber":"61264","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na fisiopatologia da artrite séptica, quais articulações apresentam metáfise\nintracapsular que permite a penetração da bactéria na articulação?","options":{"A":"quadril, tornozelo e cotovelo.","B":"ombro, tornozelo e dedos.","C":"joelho, quadril e cotovelo.","D":"punho, cotovelo e tornozelo.","E":"quadril, joelho e tornozelo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-63281","number":"63281","sourceNumber":"63281","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação aos métodos de imagem mais sensíveis utilizados para diagnosticar\npaciente com sinais clínicos de osteomielite em\nfase inicial, consideramos correto realizar:","options":{"A":"ultrassonografia e radiografias convencionais.","B":"radiografias convencionais e cintilografia.","C":"cintilografia e ressonância magnética.","D":"tomografia convencional e ressonância magnética.","E":"densitometria óssea e tomografia computadorizada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-47303","number":"47303","sourceNumber":"47303","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O pediculus hominis (piolho do corpo) é vetor de doença febril causada pela bactéria:","options":{"A":"Bartonella quintana","B":"Yersinia pestis","C":"Burkhoderia cepacia","D":"Stenotrophomonas maltophilia"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-48270","number":"48270","sourceNumber":"48270","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Nos usuários de drogas endovenosas ilícitas, o local mais comumente atingido na\nendocardite infecciosa é:","options":{"A":"Válvula mitral.","B":"Válvula aórtica.","C":"Válvula pulmonar.","D":"Válvula tricúspide.","E":"Septo interventricular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-48313","number":"48313","sourceNumber":"48313","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O Staphylococcus aureus pode produzir patologias através de uma toxina ou pela\ninvasão tecidual direta. Uma doença desencadeada por uma toxina estafilocócica é a:","options":{"A":"Pneumonia da mucoviscidose","B":"Endocardite bacteriana aguda","C":"Síndrome do choque tóxico","D":"Meningoencefalite","E":"Artrite séptica"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-51086","number":"51086","sourceNumber":"51086","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um bebê de 1 semana de idade com vômitos e anorexia é admitida no hospital com\numa temperatura de 38,9°C e fontanela abaulada.\nDos agentes etiológicos listados abaixo, qual o\nmais provavelmente implicado?","options":{"A":"Streptococcus agalactiae.","B":"Listeria monocytogenes.","C":"Neisseria meningitidis.","D":"Staphylococcus aureus.","E":"Haempophilus influenzae tipo B."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-51050","number":"51050","sourceNumber":"51050","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um homem de 35 anos procura o médico por dor perineal persistente e disúria iniciada\nhá 6 meses. Nega infecção urinária prévia ou\nsecreções uretrais. Temperatura corporal normal. Ao\ntoque retal, a próstata é levemente dolorosa, com consistência esponjosa, mas não está\naumentada ou com áreas endurecidas. A análise da urina é normal. A análise da secreção\nprostática mostra 30 células por campo e ausência de bactérias. A cultura da secreção prostática e\na urocultura são normais. Qual o diagnóstico mais provável?","options":{"A":"Cistite aguda.","B":"Prostatite aguda.","C":"Prostatite crônica bacteriana.","D":"Prostatite crônica não bacteriana.","E":"Prostatodinia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-48151","number":"48151","sourceNumber":"48151","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O tratamento antimicrobiano de escolha na erisipela é:","options":{"A":"Tetraciclina.","B":"Metronidazol.","C":"Penicilina Cristalina.","D":"Cloranfenicol.","E":"Eritromicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-47707","number":"47707","sourceNumber":"47707","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual dos antimicrobianos a seguir NÃO apresenta cobertura adequada para o\nestafilococo meticilino resistente (MRSA)?","options":{"A":"Cefalotina;","B":"Linezolide;","C":"Teicoplanina;","D":"Vancomicina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-35853","number":"35853","sourceNumber":"35853","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A cura de infecção do trato urinário depende mais da:","options":{"A":"Meia-vida sérica do antimicrobiano.","B":"Concentração sérica do antimicrobiano.","C":"Concentração urinária do antimicrobiano.","D":"Duração do tratamento antimicrobiano.","E":"Frequência do tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-34013","number":"34013","sourceNumber":"34013","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em osteomielite hematogênica aguda dos ossos longos em crianças, o tratamento de\nescolha é o seguinte:","options":{"A":"anti-inflamatórios não esteroidais e aguardar ambulatorialmente o resultado dos exames.","B":"ressonância magnética da região, administrar antibióticos via oral, ambulatorialmente, e observar\na evolução.","C":"internação hospitalar imediata, tratamento cirúrgico e antibioticoterapia venosa.","D":"medicação oral e permissão de carga precoce no membro afetado para evitar fraturas\npatológicas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-35808","number":"35808","sourceNumber":"35808","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A localização óssea mais frequente da osteomielite aguda em ossos longos:","options":{"A":"R. metafisária.","B":"R. epifisária.","C":"R. diafisária.","D":"Intra-articular.","E":"Intramedular."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-26940","number":"26940","sourceNumber":"26940","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Cibele, 40 anos, portadora de insuficiência mitral secundária a prolapso, procurou\nserviço médico com queixa de febre e odinofagia há\n3 dias. O exame físico demonstrou estalido\nmesosistólico em área mitral e discreta hiperemia de orofaringe. A melhor conduta é:","options":{"A":"realização de ecocardiograma e coleta de sangue para hemoculturas","B":"coleta de sangue para hemoculturas e penicilina benzatina intramuscular","C":"realização de ecocardiograma e penicilina benzatina intramuscular","D":"realização de ecocardiograma e início de ácido-acetil-salicílico","E":"início de ácido-acetil-salicílico e observação"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-26942","number":"26942","sourceNumber":"26942","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Endocardite por Streptococcus bovis tem forte relação com:","options":{"A":"Carcinoma de pulmão","B":"Infecções do trato urinário","C":"Tumores do intestino Grosso","D":"Abuso de drogas injetáveis","E":"Melanoma"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-26956","number":"26956","sourceNumber":"26956","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Heitor, 22 anos, portador de Síndrome de Down e estenose mitral leve, submeter-se-á a\nanestesia para extração dentária múltipla. É mandatório iniciar no pré-operatório:","options":{"A":"Digital","B":"Heparina em pequenas doses","C":"Antibiótico","D":"Antinflamatório não hormonal","E":"Diurético"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27158","number":"27158","sourceNumber":"27158","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A pielonefrite aguda é melhor dignosticada por:","options":{"A":"Calafrios, febre e dor no flanco.","B":"Bacteriúria e piúria.","C":"Escara renal.","D":"Prejuízo da função renal.","E":"Refluxo vesico-ureteral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27161","number":"27161","sourceNumber":"27161","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O fator de predisposição mais comum para infecções do trato urinário adquiridas no\nhospital é:","options":{"A":"Procedimento cirúrgico.","B":"Utilização de antibióticos.","C":"Idade","D":"Sondagem vesical","E":"Diabetes Mellitus"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-27209","number":"27209","sourceNumber":"27209","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Escolar de 9 anos apresenta claudicação e dor no membro inferior direito há 1 semana.\nRefere que há dois dias foi medicado com\npenicilina benzatina intramuscular, aplicada em glúteo,\npara tratamento de piodermite. Ao exame: febril (38,3 graus); dor a compressão de coxa direita,\nsem manifestações articulares e ausência de sinal de Lasègue. RX de quadril e membro inferior\ndireito normal. Hemograma: 18000 leucócitos/mm (83% neutrófilos, 15% bastões). VHS 59 mm na\nprimeira hora. O diagnóstico provável é:","options":{"A":"Artrite séptica","B":"Osteomielite","C":"Infarto ósseo","D":"Sarcoma de Ewing","E":"Artrite reumatoide juvenil"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-22982","number":"22982","sourceNumber":"22982","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No que se refere à associação entre situação clínica, agente etiológico e tratamento\nadequado,","options":{"A":"a erisipela tem como principal agente o Streptococcus mutans e pode ser tratada com ampicilina.","B":"o impetigo bolhoso tem como principal agente o Staphylococcus epidermides e pode ser tratado\ncom aminoglicosídeo.","C":"a pielonefrite aguda não complicada tem como principal agente a Pseudomonas aeruginosa e\npode ser tratada com cefalotina.","D":"a faringoamigdalite bacteriana aguda tem como principal agente o Streptococcus pyogenes e\npode ser tratada com penicilina G."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-23057","number":"23057","sourceNumber":"23057","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Nas infecções do trato urinário adquiridas na comunidade, o agente etiológico mais\ncomum é:","options":{"A":"Klebsiella.","B":"Proteus sp.","C":"Stafilococcus epidermidis.","D":"Escherichia coli."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-10656","number":"10656","sourceNumber":"10656","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Nas infecções do trato urinário adquiridas na comunidade, o agente etiológico mais\ncomum é:","options":{"A":"Klebsiella.","B":"Stafilococcus aureus.","C":"Proteus sp.","D":"Stafilococcus epidermidis.","E":"Escherichia coli."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9350","number":"9350","sourceNumber":"9350","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A endocardite infecciosa é uma afecção predominantemente da terapêutica clínica. Em\nsituações especiais, a cirurgia é realizada mesmo na vigência da infecção. Na fase aguda, o\ntratamento cirúrgico é indicado quando ocorre a presença de:","options":{"A":"toxemia, insuficiência renal aguda com indicação de hemodiálise e abscessos esplênicos.","B":"insuficiência respiratória com indicação de ventilação mecânica, micro-organismo desconhecido\ne abscessos cerebrais.","C":"insuficiência cardíaca de difícil controle, embolias de repetição e abscesso anular.","D":"quadro séptico, detecção de lesão valvar e de vegetação ao ecocardiograma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-10663","number":"10663","sourceNumber":"10663","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O Staphylococcus aureus pode produzir patologias através de uma toxina ou pela\ninvasão tecidual direita. Uma doença desencadeada por uma toxina estafilcóccica é a:","options":{"A":"pneumonia da mucoviscidose.","B":"endocardite bacteriana aguda.","C":"artrite séptica.","D":"meningoencefalite.","E":"síndrome do choque tóxico."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-8964","number":"8964","sourceNumber":"8964","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A diferenciação córtico-medular na ultrassonografia renal se dá pelo alto fluxo de\nsangue no córtex renal, a perda dessa\ndiferenciação é uma alteração comum nos pacientes\nportadores de Doença Renal Crônica terminal devido o grau acentuado de esclerose glomerular.\nOutra causa de perda de diferenciação córtico-medular na ultrassonografia é:","options":{"A":"Pielonefrite aguda","B":"Sindrome Nefrótica","C":"Uso de anti-inflamatório hormonal","D":"Desidratação"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-8984","number":"8984","sourceNumber":"8984","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O abscesso hepático piogênico é uma coleção purulenta que se instala no parênquima\nhepático. Em relação aos abscessos hepáticos piogênicos é incorreto afirmar que:","options":{"A":"nos pacientes portadores de hipoalbuminemia, desnutridos e idosos o quadro clínico é mais\ngrave.","B":"no passado a etiologia mais comum era a apendicite aguda e atualmente são as de origem biliar.","C":"em 15 a 20% dos casos a causa do abscesso hepático não é identificada.","D":"a drenagem cirúrgica associada ao uso de antibióticos constitui a única opção eficaz de\ntratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-8976","number":"8976","sourceNumber":"8976","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na febre Reumática, assinale a alternativa verdadeira:","options":{"A":"O diagnóstico de Febre Reumática é feito na presença de dois critérios maiores ou de um critério\nmaior e dois menores;acompanhado de evidência de infecção estreptocócica anterior","B":"Cardite e alterações no eletrocardiograma podem ser usadas como critério maior e menor,\nrespectivamente, no mesmo paciente, para o diagnóstico de Febre Reumática","C":"O tratamento visa somente a erradicação do foco infeccioso (profilaxia primária) e a prevenção\nde recorrências (profilaxia secundária), pois na\nfase aguda praticamente não existem\nmanifestações inflamatórias que justifiquem intervenção terapêutica","D":"O tratamento deverá ser suspenso aos 18 anos para todos os pacientes, independentemente do\ncomprometimento cardíaco ou não"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-8978","number":"8978","sourceNumber":"8978","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os agentes mais frequentemente relacionados às meningites virais e encefalites virais\nsão respectivamente:","options":{"A":"Enterovírus e Citomegalovírus","B":"Citomegalovírus e Vírus Epstein barr","C":"Enterovírus e Herpes simples","D":"Herpes simples e HIV"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-11068","number":"11068","sourceNumber":"11068","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"De acordo com a contagem de colônias na urina, podemos afirmar tratar-se de I.T.U.\nquando temos:","options":{"A":"Maior que 100.000 colônias","B":"Sintomáticos maior que 10.000 colônias","C":"Assintomáticos maior que 10.000 colônias","D":"Sintomáticos entre 10.000 e 100.000 colônias","E":"Existem duas respostas corretas"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-9002","number":"9002","sourceNumber":"9002","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considerando-se uma criança com quadro de febre de origem indeterminada, assinale\na alternativa correta:","options":{"A":"A história e o exame físico dão poucos subsídios para a conduta do caso","B":"O diagnóstico etiológico é feito em mais de 85% dos casos","C":"As causas infecciosas, bacterianas e principalmente as virais são as responsáveis pela maioria\ndos casos","D":"As doenças do colágeno, Artrite Reumatoide Juvenil e Lúpus Eritematoso Sistêmico são as\nresponsáveis pela maioria dos casos"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-18960","number":"18960","sourceNumber":"18960","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na obstrução intestinal, quando a radiografia simples mostra dilatação do cólon, o\nenema opaco é imperativo. Todavia, é contraindicado:","options":{"A":"No megacólon tóxico.","B":"No tumor de sigmoide.","C":"Na apendicite aguda.","D":"Na divertude de Meckel."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-274011","number":"274011","sourceNumber":"274011","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre as estratégias para reduzir a transmissão vertical do HIV, assinale a alternativa\nCORRETA:","options":{"A":"Pode optar-se pelo parto normal, independente da carga viral materna no último trimestre caso a\nmesma já esteja em uso de terapia antirretroviral há mais de um ano.","B":"Não clampear imediatamente o cordão após o nascimento, devendo-se fazer ordenha caso a\nmãe tenha recebido zidovudina injetável para assegurar circulação dessa medicação\nimediatamente no recém-nascido.","C":"Deve ser orientada a não amamentação, inibindo-se a lactação e introduzindo a fórmula láctea,\npodendo usar-se o leite humano pasteurizado proveniente de banco de leite humano em\n\nrecém-nascido pré-termo ou de baixo peso.","D":"A zidovudina xarope deve ser instituída para o recém-nascido somente se o seu teste rápido for\npositivo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-250225","number":"250225","sourceNumber":"250225","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente 32 anos, transplantado renal, em uso de terapia imunossupressora, iniciou há\n15 dias com cefaleia holocraniana, pulsátil,\nturvação visual, náuseas e vômitos, nega febre. Ao\nexame clínico, apresentava confusão mental, edema de papila a fundoscopia, rigidez de nuca,\nparalisa de sexto nervo a esquerda. A ressonância magnética do crânio mostrou lesões\npseudocísticas em núcleos da base. Análise do liquor: lâmina corada com tinta da China positiva.\nQuanto a neurocriptococose, assinale a alternativa INCORRETA:","options":{"A":"Punção lombar seriada está contraindicada devido à hipertensão intracraniana, devendo a\nconduta inicial ser a implantação de uma derivação ventricular externa.","B":"Apresenta-se mais comumente como meningoencefalite aguda ou subaguda.","C":"A hipertensão intracraniana ocorre em mais de 50% dos casos (raquimanometria > 200 mmH?O\nem decúbito lateral).","D":"Durante a fase de indução do tratamento está indicado uso de anfotericina B."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-216432","number":"216432","sourceNumber":"216432","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recém-nascido com 15 dias de vida, nascido de parto cesariano, filho de mãe\nsoropositiva para HIV em tratamento com\nantirretroviral, realizou atendimento com a pediatra por\nquadro de cólica. A médica pediatra identificou que a criança estava com bom estado geral e em\nuso da zidovudina e de fórmula infantil. A pediatra decidiu então solicitar um teste rápido anti-HIV\ndisponível na unidade para criança, cujo resultado foi positivo. Considerando o caso descrito acima,\nselecione a conduta CORRETA.","options":{"A":"Trata-se de um caso de infecção vertical para vírus HIV, sendo recomendado manter a\nzidovudina, associar lamivudina e nevirapina e\ncolher a carga viral com genotipagem urgente por se\ntratar de uma recém-nascido.","B":"Trata-se de um caso de síndrome de imunodeficiência adquirida por HIV, sendo recomendado\ncolher carga viral, CD4, CD8 e iniciar\nantirretroviral urgente por se tratar de uma recém-nascido.","C":"Trata-se de um caso de exposição vertical para vírus HIV, sendo recomendado manter a\nzidovudina por 4 semanas e, posteriormente, realizar dosagem de carga viral.","D":"Trata-se de um caso de infecção vertical para vírus HIV, sendo recomendado pelo Ministério da\nSaúde, especialmente no período neonatal, o uso do esquema profilático de Pós-Exposição (PEP)\naté no máximo 3 semanas de vida, iniciando esquema com tenofovir, lamivudina e dolutegravir.\nAlém de colher carga viral com genotipagem."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-216426","number":"216426","sourceNumber":"216426","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Criança de 5 anos de idade, com diagnóstico de síndrome de imunodeficiência\nadquirida em uso de antirretroviral desde os\n2 anos de vida. Deu entrada no pronto-socorro com\nquadro de tosse, febre e cansaço há 4 dias. Durante a ausculta pulmonar, apresentava estertores\ncrepitantes em base direita. Realizado hemograma, apresentava leucocitose de 18.000\ncélulas/mm³, com predomínio de neutrófilos, e radiografia de tórax revelou consolidação lobar no\npulmão direito. Diante do caso descrito acima, selecione o provável diagnóstico e o tratamento\nrecomendado.","options":{"A":"Pneumocistose, sendo recomendado iniciar o sulfametoxazol com trimetoprima.","B":"Tuberculose pulmonar, sendo recomendado iniciar o tratamento com rifampicina, isoniazida e\npirazinamida.","C":"Micoses pulmonares sendo recomendado iniciar antifúngico.","D":"Pneumococo, sendo recomendado iniciar a penicilina ou cefalosporina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-176132","number":"176132","sourceNumber":"176132","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quanto ao manejo da infecção pelo HIV, assinale a CORRETA.","options":{"A":"Adultos e adolescentes que vivem com HIV podem receber todas as vacinas do calendário\nnacional, independente da contagem de linfócitos CD4.","B":"A terapia antirretroviral não deve ser oferecida a todas as pessoas com diagnóstico do HIV,\ndepende da carga viral e da contagem de linfócitos T-CD4+.","C":"Os usuários portadores de HIV podem ser acompanhados na atenção básica.","D":"A contagem de linfócitos T-CD4+ serve para monitorar a resposta ao tratamento antirretroviral.","E":"O uso de profilaxia secundária visa evitar o primeiro episódio de uma infecção oportunista."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-105721","number":"105721","sourceNumber":"105721","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 45 anos de idade, sexo feminino, com relato recente de dor abdominal em\nandar superior, associado a náuseas, vômitos, febre, calafrios, colúria e icterícia. Após\ninvestigação\ndiagnóstica, o quadro de colecistite aguda calculosa com coledocolitíase e colangite. Submetida à\npapilotomia endoscópica com coledocolitotomia e colecistectomia videolaparoscópica. Duas\nsemanas após o procedimento cirúrgico, evoluiu com dor em hipocôndrio direito, febre, calafrios e\nqueda no estado geral. Submeteu-se à tomografia computadorizada do abdome que evidenciou a\npresença de abscesso hepático único, com 11 x 8 x 7 cm de diâmetros em segmento V do fígado.\nAssinale a alternativa INCORRETA:","options":{"A":"O abscesso hepático bacteriano de origem hematogênica venoso comumente compromete\nsegmentos do lobo direito do fígado em função\nda distribuição do fluxo portal.","B":"Trata-se de um provável abscesso hepático de etiologia bacteriana (piogênico) em função do\nquadro prévio de colecistite com colangite.","C":"A maioria dos abscessos hepáticos piogênicos tem flora polimicrobiana com predomínio de\nGram-negativos entéricos (aeróbicos e/ou anaeróbicos).","D":"O manejo da paciente envolve a realização de um procedimento para drenagem do abscesso\n(percutâneo ou cirúrgico) e\nantibioticoterapia sistêmica empírica voltada para germes\n\nGram-positivos (vancomicina), até que se tenha o resultado da cultura pós-punção e antibiograma.","E":"A obstrução biliar de natureza benigna ou maligna tem se destacado com causas comuns de\nabscessos piogênicos do fígado no mundo ocidental."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-105714","number":"105714","sourceNumber":"105714","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às infecções necrosantes de pele e partes moles (INPPMs), assinale a\nalternativa INCORRETA:","options":{"A":"As INPPMs do tipo I são monomicrobianas e mais comumente causadas por bactérias\nanaeróbicas tais como clostrídios,\nestreptococos ou bacterióides, por sua vez, as INPPMs do tipo II\nsão polimicrobianas. A maioria dos patógenos, especialmente o Clostridium perfringens, secretam\nexotoxinas (hemolisina, colagenases, lecitinases e proteases) que determinam uma rápida\nevolução da necrose tissular ao longo das fáscias e planos musculares.","B":"Pacientes imunocomprometidos, incluindo pacientes com diabetes mellitus, vírus da\nimunodeficiência humana (HIV), desnutrição, doença\nvascular periférica e uso de dorgas injetáveis\naumentam o risco de desenvolvimento de INPPMs.","C":"Alto índice de suspeição e diagnóstico precoce são críticos, devido à rápida progressão para as\nalterações hemodinâmicas (choque) e falências orgânicas associadas ao retardo no diagnóstico e\nmanejo clínico e cirúrgico adequados nas INPPMs.","D":"Assim como ocorre nas infecções clostridianas (gangrena úmida), a amputação do membro está\nrecomendada como abordagem cirúrgica de escolha nos pacientes com fasceíte necrosante não\nclostridiana, envolvendo os membros inferiores, com o objetivo de se minimizar a morbiletalidade\ndo episódio.","E":"As INPPMs são consideradas como emergência cirúrgica, e recomenda-se tratamento imediato\ne agressivo com suporte hemodinâmico e\nressuscitação fluida, extensivo debridamento cirúrgico\ndos tecidos necróticos e antibioticoterapia de amplo espectro."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-105670","number":"105670","sourceNumber":"105670","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre as infecções estafilocócicas, não é correto afirmar:","options":{"A":"Na intoxicação alimentar, patologia de início e resolução agudos (geralmente em horas), a\ndoença é causada pela ingestão da\nenterotoxina pré-formada. A toxina estimula o centro do vômito\ne a peristalse intestinal, ocasionando os sintomas. Não há participação bacteriana direta nos\nsintomas, portanto o tratamento consiste apenas em suporte, sem necesidade de antibioticoterapia.","B":"Os estafilococos coagulase-negativa são mais virulentos do que os estafilococos\n\ncoagulase-positiva e, mais comumente, estão associados às infecções de dispositivos protéticos.\nComo estão presentes em grande quantidade na\npele, geralmente contaminam as culturas,\ndificultando a interpretação das mesmas.","C":"A vancomicina é uma opção menos efetiva do que a oxacilina para tratamento de infecções por\nMethicillin-Sensitive Staphylococcus Aureus (MSSA).","D":"As infecções de repetição podem ocorrer devido à colonização de superfícies corporais,\nespecialmente a parte anterior das narinas. Essa incidência pode ser reduzida com o uso de\nmupirocina tópica na região nasal.","E":"São síndromes clínicas cuja etiologia estafilocócica deve sempre ser lembrada como uma das\nmais importantes: infecções de pele e partes moles, artrite séptica, osteomielite, pneumonia\n(especialmente a comunitária grave e a nosocomial) e endocardite infecciosa."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-80906","number":"80906","sourceNumber":"80906","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente, 62 anos, diagnosticada com diabetes mellitus em uso de insulinoterapia,\niniciou há 48 horas febre de 38°C e lesão\ncutânea em membro inferior esquerdo. Ao exame: estado\ngeral preservado; FC = 94 bpm; PA = 120 x 70 mmHg; apresenta eritema de limites bem definidos;\nedema e calor acometendo o terço inferior da perna esquerda. Sobre o quadro descrito, é\nCORRETO afirmar:","options":{"A":"Trata-se de celulite, o agente mais provável é o Staphylococcus aureus e o tratamento deve ser\nfeito com norfloxacino por 3 dias.","B":"Trata-se de celulite e o tratamento deve aguardar o resultado da cultura e antibiograma.","C":"Não há relevância se o diagnóstico é erisipela ou celulite, devendo-se tratar com ciprofloxacino\ne\nclindamicina.","D":"O diagnóstico é de erisipela e o tratamento deve ser com antibiótico betalactâmico.","E":"Devem ser analisados os níveis glicêmicos e indicado o tratamento com vancomicina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-80851","number":"80851","sourceNumber":"80851","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Adolescente de 13 anos, sexo feminino, portador de estenose aórtica congênita leve,\nvai ser submetido a procedimento dentário invasivo. Neste caso, está indicada a profilaxia com:","options":{"A":"Sulfametoxazol + trimetropim.","B":"Ciprofloxacina.","C":"Amoxicilina.","D":"Azitromicina.","E":"Eritromicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-62637","number":"62637","sourceNumber":"62637","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 45 anos de idade, sexo feminino, com relato recente de dor abdominal em\nandar superior, associada a náuseas, vômitos, febre, calafrio, colúria e icterícia. Após\ninvestigação\ndiagnóstica, concluiu-se o quadro de colecistite aguda calculosa com coledocolitíase e colangite.\n\nSubmetida à papilotomia endoscópica com coledocolitotomia e colecistectomia videolaparoscópica.\nDuas semanas após o procedimento cirúrgico,\nevoluiu com dor em hipocôndrio direito, febre,\ncalafrios e queda no estado geral. Submeteu-se a tomografia computadorizada do abdome que\nevidenciou a presença de abscesso hepático único, com 11 x 8 x 7 cm de diâmetros em segmento\nV do fígado. Assinale a alternativa incorreta:","options":{"A":"Trata-se de um provável abscesso hepático de etiologia bacteriana (piogênico) em função do\nquadro prévio de colecistite com colangite;","B":"O manejo da paciente envolve a realização de um procedimento (percutâneo ou cirúrgico) para\ndrenagem do abscesso e antibioticoterapia sistêmica;","C":"A maioria dos abscessos hepáticos piogênicos tem flora polimicrobiana com predomínio de\nGram-negativos entéricos (aeróbicos e/ou anaeróbicos);","D":"O abscesso hepático bacteriano de origem hematogênica comumente compromete segmentos\ndo lobo esquerdo do fígado em função da\ndistribuição do fluxo venoso portal, manifestando-se\ncomo lesão isolada no parênquima hepático;","E":"A obstrução biliar de natureza benigna ou maligna tem se destacado com causas comuns de\nabscessos piogênicos do fígado no mundo ocidental."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-62647","number":"62647","sourceNumber":"62647","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher, 20 anos, chega ao Serviço de Emergência com cefaleia e febre há 72 horas. Ao\nexame físico, encontra-se sonolenta, febril\n(38,5°C) e com rigidez de nuca. Há história de sinusite\nde repetição. O médico aventou como hipótese diagnóstica meningite. Para confirmá-la, foi\nrealizada punção lombar, que revelou liquor turvo. Análise liquórica mostrou: celularidade: 800/cm³,\ncom predomínio de polimorfonucleares; proteína: 700 mg; glicose: 20 mg/dl e mostra, em coloração\npelo método de Gram, cocos Gram-positivos em cadeia. Considerando os dados clínicos e\nlaboratoriais do caso descrito, a afecção, o agente etiológico provável e o esquema antimicrobiano\na iniciar são, respectivamente:","options":{"A":"Meningite bacteriana por Neisseria meningitidis; penicilina cristalina.","B":"Meningite bacteriana por Haemophilus influenzae; ceftriaxona.","C":"Meningoencefalite viral por herpes simples; aciclovir.","D":"Meningoencefalite por Mycobacterium tuberculosis; esquema RIPE.","E":"Meningite bacteriana por Streptococcus pneumoniae; ceftriaxona."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-62580","number":"62580","sourceNumber":"62580","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na definição de febre de origem indeterminada, são considerados critérios diagnósticos:","options":{"A":"Episódios de febre maior de 38°C; duração de pelo menos três semanas; ausência de\ndiagnóstico após pelo menos uma semana de investigação hospitalar;","B":"Temperatura axilar acima de 38,3°C / presença de neutropenia;","C":"Vários episódios febris / duração de uma semana;","D":"Imunossupressão / duração de três semanas;","E":"Temperatura axilar acima de 37,5°C / duas semanas de duração."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-47444","number":"47444","sourceNumber":"47444","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual das seguintes afirmações é verdadeira em relação ao risco de infecção após\nesplenectomia eletiva?","options":{"A":"Pacientes não estão em maior risco de infecção viral após esplenectomia.","B":"Os pacientes devem ser vacinados 2 semanas após a esplenectomia.","C":"Pacientes com idade acima de 50 estão em maior risco de sepse pós-esplenectomia.","D":"O Staphylococcus aureus é o organismo mais comumente implicado na sepse\npós-esplenectomia.","E":"O risco de infecção após a esplenectomia aumenta com o tempo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-47476","number":"47476","sourceNumber":"47476","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma mulher de 25 anos se apresenta à clínica queixando-se de vários dias de ardor e\ndor ao urinar. Ela descreve um aumento na frequência urinária e sensibilidade suprapúbica, mas\nsem febre ou tenesmo. Ela não tem história médica pregressa, com exceção de dois episódios\nanteriores semelhantes a este nos últimos 2 anos. Análise de urina mostra aumento de leucócitos.\nQual dos seguintes é o agente causal mais provável de seus sintomas atuais?","options":{"A":"Candida.","B":"Enterobacter.","C":"Klebsiella.","D":"Escherichia coli.","E":"Proteus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-47472","number":"47472","sourceNumber":"47472","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Criança de 10 (dez) anos, sexo feminino, portador de estenose aórtica congênita leve,\nirá submeter-se a procedimento odontológico\ninvasivo. Neste caso, está indicada a profilaxia com:","options":{"A":"Ciprofloxacina.","B":"Eritromicina.","C":"Azitromicina.","D":"Sulfametoxanol - trimetropin.","E":"Amoxicilina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-28237","number":"28237","sourceNumber":"28237","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Menino com febre intermitente, mialgia difusa, com limitação dos movimentos,\nbaqueteamento dos dedos, petéquias, hematúria\nmicroscópica e sopro cardíaco. Baseado na\nclínica, qual o diagnóstico provável?","options":{"A":"Artrite reumatoide","B":"Febre reumática","C":"Endocardite infecciosa","D":"Lúpus eritematoso sistêmico","E":"Hanseníase"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-244658","number":"244658","sourceNumber":"244658","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 27 anos com HIV positivo chegou ao pronto-socorro do hospital com quadro\nde vertigem, cefaleia, febre e crises\nconvulsivas tônico-clônicas. Após medidas iniciais de suporte,\nfoi realizada tomografia de crânio com contraste que evidencia lesões hipodensas bilaterais em\ngânglios da base e junção corticomedular. A principal suspeita é:","options":{"A":"Neurocisticercose.","B":"Demência pelo vírus HIV.","C":"Meningoencefalite criptocócica.","D":"Neurotoxoplasmose.","E":"Meningite viral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-244667","number":"244667","sourceNumber":"244667","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A injúria glomerular característica do HIV é:","options":{"A":"Glomerulonefrite membranosa.","B":"Glomeruloesclerose segmentar e focal.","C":"Glomerulonefrite membranoproliferativa.","D":"Glomerulonerite fibrilar.","E":"Nefropatia por IgA."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-244668","number":"244668","sourceNumber":"244668","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A leucoencefalopatia multifocal progressiva (LEMP), que ocorre em indivíduos com\ncontagem de leucócitos T CD4+<200\ncélulas/mm³ e caracteriza-se por imagem de lesões múltiplas\nconfluentes, hipodensas, que não captam contraste e não possuem efeito de massa,\nprincipalmente na substância branca, tem como causa:","options":{"A":"Vírus JC","B":"Citomegalovirus","C":"Toxoplasma gondii","D":"Criptococus spp","E":"Complexo Micobacterium avium"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-250400","number":"250400","sourceNumber":"250400","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Segundo a estatística populacional americana, o risco de contrair o vírus HIV ao\nreceber uma doação de hemoderivados é de:","options":{"A":"1/100.000 unidades.","B":"1/200.000 unidades.","C":"1/500.000 unidades.","D":"1/2.000.000 unidades.","E":"1/ 100.000.000 unidades."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177476","number":"177476","sourceNumber":"177476","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente com diagnóstico recente de infecção por HIV, com contagem de CD4+ em 42\ncélulas, deve receber profilaxia primária para infecções oportunistas com que droga(s)?","options":{"A":"Sulfametoxazol-trimetoprim e azitromicina","B":"Sulfametoxazol-trimetoprim e fluconazol","C":"Sulfametoxazol-trimetoprim","D":"Isoniazida e Sulfametoxazol-trimetoprim","E":"Fluconazol e azitromicina"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-160365","number":"160365","sourceNumber":"160365","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O portador da infecção pelo HIV pode apresentar sinais e sintomas inespecíficos de\nintesidade variável, além de processos oportunistas de menor gravidade, conhecidos como\ncomplexo relacionado à AIDS (ARC). São indicativos de ARC a candidíase oral e a presença de\nmais de um dos seguintes sinais e sintomas, com duração superior a 1 mês, sem causa\nidentificada:","options":{"A":"Hipotensão arterial ortostática.","B":"Perda de peso superior a 10%.","C":"Desidratação refratária.","D":"Palidez cutâneo-mucosa.","E":"Dispneia ao repouso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-87557","number":"87557","sourceNumber":"87557","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 45 anos de idade, sexo feminino, com relato recente de dor abdominal em\nandar superior, associado a náuseas, vômitos, febre, calafrio, colúria e icterícia. Após\ninvestigação\ndiagnóstica, concluiu-se o quadro de colecistite aguda calculosa com coledocolitíase e colangite .\nSubmetida à papilotomia endoscópica com coledocolitotomia e colecistectomia videolaparoscópica.\nDuas semanas após o procedimento cirúrgico, evoluiu com dor em hipocôndrio direito, febre,\ncalafrios e queda no estado geral. Submeteu-se à tomografia computadorizada do abdome que\nevidenciou a presença de abscesso hepático único, com 11 x 8 x 7 cm de diâmetros em segmento\nIV do fígado. Assinale a alternativa INCORRETA:","options":{"A":"O abscesso hepático bacteriano de origem hematogênica comumente compromete segmentos\ndo lobo esquerdo do fígado em função da\ndistribuição do fluxo venoso portal, manifestando-se\ncomo lesão isolada no parênquima hepático;","B":"Trata-se de um provável abscesso hepático de etiologia bacteriana (piogênico) em função do\nquadro prévio de colescistite com colangite;","C":"O manejo da paciente envolve a realização de um procedimento (percutâneo ou cirúrgico) para\ndrenagem do abscesso e antibioticoterapia sistêmica;","D":"A maioria dos abscessos hepáticos piogênicos tem flora polimicrobiana com predomínio de\nGram negativos entéricos (aeróbicos e/ou anaeróbicos);","E":"A obstrução biliar de natureza benigna ou maligna tem se destacado com causas comuns de\nabscessos piogênicos do fígado no mundo ocidental."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-65567","number":"65567","sourceNumber":"65567","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação à antibioticoprofilaxia cirúrgica, podemos afirmar que:","options":{"A":"A Cefazolina, uma cefalosporina de 2º geração, é muito ativa contra cocos Gram-positivos.","B":"A Cefoxitina, uma cefalosporina de 1º geração, apresenta boa atividade contra anaeróbios.","C":"A Cefoxitina, uma cefalosporina de 2º geração, apresenta boa atividade contra anaeróbios.","D":"A Cefazolina, uma cefalosporina de 1ª geração, é pouco ativa contra cocos Gram-positivos.","E":"Nenhuma das anteriores."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-65654","number":"65654","sourceNumber":"65654","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Meningoencefalite é definida como um processo inflamatório do cérebro e das\nmeninges, cuja etiologia mais comum é infecciosa. Identifique qual das afirmativas acerca da\nMeningoencefalite é incorreta.","options":{"A":"O quadro clínico varia segundo a faixa etária, etiologia, região do cérebro acometida e\ncomprometimento meníngeo;","B":"O vírus da parotidite (caxumba) é um agente frequente de meningoencefalite viral nos pacientes\nnão vacinados ou sem imunidade completa;","C":"As alterações do líquido cefalorraquidiano (LCR) na Meningoencefalite viral são geralmente:\naumento de celularidade e proteína normal ou\naumentada;","D":"A gravidade da doença depende do agente etiológico, diagnóstico precoce, faixa etária e estado\nimunológico do paciente;","E":"Meningoencefalite por Mycoplasma pneumoniae é raro em crianças maiores de 05 anos com\nsintomas respiratórios que antecedem os sintomas de Meningoencefalite."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-52488","number":"52488","sourceNumber":"52488","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quais os sinais mais frequentes de meningites no período neonatal ?","options":{"A":"Convulsões, sinais de irritação meníngea, vômitos e rigidez de nuca.","B":"Hipoatividade, irritação, febre ou hipotermia e crises convulsivas.","C":"Febre alta, icterícia, sinal de Brudzinski e abaulamento de fontanela.","D":"Cefaleia, febre, rigidez de nuca e sinal de Kerning.","E":"Febre, sinal de Kerning, sinal de Brudzinski e rigidez de nuca."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-52465","number":"52465","sourceNumber":"52465","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Possuem atividade contra cepas de Staphylococcus aureus meticilina resistente todos\nos antibióticos abaixo, exceto:","options":{"A":"Tigeciclina.","B":"Imipenem.","C":"Vancomicina.","D":"Daptomicina.","E":"Linezolida."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-52466","number":"52466","sourceNumber":"52466","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 22 anos, masculino, dá entrada no Hospital com queixa de mal-estar, febre\ne dores no corpo há 2 horas. Ao exame\nencontra-se consciente, orientado, anictérico, febril (T.\naxilar = 38,5°C), com nuca livre. Presença de manchas purpúricas em membros inferiores e tronco.\nAusculta cardíaca e respiratória normais, FC = 120 e TA = 80 x 50 mmHg. O abdome é flácido.\n\nExames laboratoriais mostram leucocitose com desvio à esquerda e plaquetopenia leve, função\nrenal DHL normais e discreta elevação nas\ntransaminases. Após o atendimento inicial e hidratação\ncom 1000 ml de cristaloide, paciente evolui com piora clínica e rebaixamento do nível de\nconsciência sendo admitido à Unidade de Terapia Intensiva, onde vem a falecer cerca de 8h após a\nentrada na emergência. Qual o provável diagnóstico?","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Meningococcemia.","C":"Dengue hemorrágica.","D":"Leptospirose.","E":"Fasceíte necrotizante."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-362853","number":"362853","sourceNumber":"362853","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Perito criminal, 50 anos, internado em enfermaria para investigação de síndrome\nconsumptiva. Você é o residente responsável\npelo caso, colhe a história da doença atual e o\nhistórico médico que constam: perda de mais de 16kg nos últimos 3 meses, sem dieta, cansaço,\nastenia, hiporexia, febre intermitente e diarreia. Há duas semanas surgiram lesões em placas\nesbranquiçadas em toda mucosa oral, com odinofagia. Relata também lesões arredondadas e\nhiperemiadas em palma das mãos. Há 3 dias com tosse seca e dispneia. Vacinas em dia. É\nsolteiro, sem filhos, faz sexo somente com homens, faz uso esporádico de preservativo e diz não\nconsumir nenhum tipo de droga. Nega história de tuberculose na família. Nega alergias. Refere\ncirurgia por politrauma na infância onde precisou realizar várias transfusões sanguíneas. Os\nexames complementares apresentaram os seguintes resultados. Sobre o diagnóstico de retrovirose\ndesse paciente, podemos afirmar corretamente que o:","options":{"A":"diagnóstico não está confirmado.","B":"paciente apresenta diagnóstico de HIV.","C":"próximo passo é solicitar sorologia para HIV.","D":"paciente apresenta diagnóstico de AIDS."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-348445","number":"348445","sourceNumber":"348445","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Gestante, 30 anos de idade, G3P2(1N1C)A0, dá entrada em maternidade do Hospital\nUniversitário, já em pródromos de trabalho de parto. Trata-se de gestação com 38 semanas e 3\ndias, pré-natal realizado com 7 consultas e sem intercorrências obstétricas. A paciente possui\ndiagnóstico de HIV desde o terceiro trimestre da segunda gestação e seu filho do meio recebeu a\nconfirmação da transmissão vertical do HIV nos primeiros meses de vida. Desde que descobriu a\nterceira gestação, fez todo o possível para evitar que seu caçula recebesse o mesmo diagnóstico\ndo irmão. Faz uso de TARV regularmente desde o diagnóstico e apresenta carga viral indetectável\nsustentada há 1 ano, sendo o último exame realizado há cerca de 3 semanas. A equipe de\nobstetrícia optou pela evolução do parto normal e após 4 horas de trabalho de parto nasceu uma\ncriança do sexo masculino. É realizado o clampleamento imediato do cordão umbilical e a criança é\nentregue para os devidos cuidados à equipe assistente. Recém-nascido apresenta choro vigoroso,\ntônus flexor e frequência cardíaca maior do que 100bpm, não sendo indicadas manobras de\nreanimação neonatal. É realizado o banho em água corrente para a limpeza de secreções e a\ncriança é colocada em contato pele a pele com a mãe e ambos são liberados para a rotina do\nalojamento conjunto. Para esse RN, qual a conduta correta a ser instituída?","options":{"A":"Aleitamento permitido em livre demanda e quimioprofilaxia AZT via oral por 28 dias.","B":"Aleitamento contraindicado e quimioprofilaxia AZT, 3TC e RAL por 28 dias.","C":"Aleitamento permitido em livre demanda e quimioprofilaxia AZT, 3TC e RAL via oral por 28 dias.","D":"Aleitamento contraindicado e quimioprofilaxia AZT via oral por 28 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-274134","number":"274134","sourceNumber":"274134","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Lactente, 1 ano e 6 meses de idade, foi encaminhado para consulta com pediatra no\nHospital Universitário com história de ganho de peso inadequado. Nos últimos 12 meses,\napresentou 6 episódios de diarreia prolongada que melhoraram somente com uso de medicação\nantiparasitária, 4 episódios de otites e 1 episódio de pneumonia, sendo que se agravou e precisou\nser internado na UTI com quadro de sepses, recebendo antibióticos endovenosos. Parto normal.\nPeso 3.200 g; C= 48 cm, Apgar 8/9. Aleitamento materno exclusivo até 6 meses de vida. Vacinas\nem dia. Exame físico: Peso = 8.350 g; Altura = 81 cm [IMC = 13,1 Kg/m² (escore Z -2 e Z -3)].\n\nFácies atípica, eupneica, afebril, anictérica. Orofaringe e otoscopia perfuração de membrana\ntimpânica direita sem secreção. Pulmões com VM\nfisiológico, sem ruídos adventícios. ACV: RCR,\n2T, sopro sistólico 2+/6. Abdome plano, sem visceromegalias, RHA normais. Genitália sem\nalteração. SN: sem sinais meníngeos. Pele sem lesões. Segundo a Fundação Jeffrey Modell (EUA -\n1996) adaptados a nossa realidade, há 10 sinais de alerta para suspeitar de imunodeficiência\nprimária. Assinale a alternativa que apresenta os sinais de alerta presentes no caso.","options":{"A":"Desnutrição grave; Infecção intestinal de repetição; 4 episódios de otites.","B":"Desnutrição grave; 4 episódios de otites; 1 episódio de pneumonia.","C":"4 episódios de otites; 1 episódio de pneumonia grave.","D":"Infecção intestinal de repetição; 4 episódios de otites; 1 episódio de sepse."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255311","number":"255311","sourceNumber":"255311","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Raltegravir (RAL) deve ser administrado duas vezes ao dia, o que representa uma\npotencial desvantagem em relação a esquemas de tomada única diária. Podemos apenas\nconcordar com o item:","options":{"A":"RAL apresenta péssima tolerabilidade, alta potência, poucas interações medicamentosas,\neventos adversos pouco frequentes e segurança para o\nuso em coinfecções como hepatites e\ntuberculose.","B":"RAL apresenta excelente tolerabilidade, baixa potência, poucas interações medicamentosas,\neventos adversos pouco frequentes e segurança para o\nuso em coinfecções como hepatites e\ntuberculose.","C":"RAL apresenta excelente tolerabilidade, alta potência, poucas interações medicamentosas,\neventos adversos pouco frequentes e segurança para o\nuso em coinfecções como hepatites e\ntuberculose.","D":"RAL apresenta excelente tolerabilidade, alta potência, poucas interações medicamentosas,\neventos adversos muito frequentes e segurança para o\nuso em coinfecções como hepatites e\ntuberculose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255312","number":"255312","sourceNumber":"255312","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A genotipagem pré-tratamento para manejo da infecção pelo HIV em adultos está\nindicada nas seguintes situações listadas abaixo, indique o item com ERRO:","options":{"A":"Pessoas que tenham se infectado com parceiro (atual ou pregresso) em uso de TARV.","B":"Casais soro iguais.","C":"Gestantes infectadas pelo HIV.","D":"Coinfecção TB-HIV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247686","number":"247686","sourceNumber":"247686","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem, 23 anos, homossexual, refere que, após relação sexual sem preservativo, o\nparceiro comunicou ser portador do vírus HIV e que não estava em uso correto das medicações.\nApós 4 semanas, o paciente realizou um teste rápido de fluido oral em uma campanha da\nsecretaria de saúde do município, resultando positivo. Ele foi encaminhado a um serviço de\nreferência para esclarecimentos. Para confirmação diagnóstica de infecção pelo HIV, quais os\npróximos exames a serem solicitados?","options":{"A":"Pelo tempo de exposição, só é possível diagnóstico através de realização da carga viral do HIV\nou de exames que contenham antígeno p24.","B":"São necessários mais dois testes rápidos, de marcas diferentes, e, se ambos positivos, a\namostra é reagente para o HIV.","C":"No caso de um segundo teste inconclusivo, solicitar carga viral, se esta vier positiva, em\nqualquer valor, pode confirmar o diagnóstico.","D":"Apenas mais um teste rápido positivo (realizado com amostra de sangue) já pode confirmar a\ninfecção pelo HIV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-247690","number":"247690","sourceNumber":"247690","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 26 anos, HIV positivo, iniciou tratamento com TARV há três meses. Nega\noutras comorbidades ou uso de outros\nmedicamentos. Nega tabagismo. Retorna a consulta médica\ncom exames laboratoriais evidenciando hipercolesterolemia. Em relação ao tratamento das\ndislipidemias nesse paciente, é correto afirmar:","options":{"A":"A escolha da estatina deve basear-se apenas na sua potência.","B":"O ezetimibe pode ser usado com segurança.","C":"O uso de estatinas é contraindicado.","D":"Tratamento com inibidores da PCSK9 é indicado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-214062","number":"214062","sourceNumber":"214062","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Fábio,25 anos, vem a consulta na USB com queixa de há cerca de 2 semanas\napresentar sintomas discretos de náuseas,\ntontura e fadiga, nega vômitos, nega diarreia, nega\nfebre, nega perda ponderal. Vacinas atualizadas. Trabalha como vendedor e atualmente está\ndesempregado. No exame físico não há achados significativos. Como Fábio não costuma buscar a\nunidade de saúde o médico oferece a possibilidade de realizar testes rápidos e ambos testes para\nHIV resultam positivos. Sobre o caso cima e o contato inicial com o paciente soropositivo marque a\nalternativa CORRETA.","options":{"A":"O médico deve solicitar a avaliação do dentista para investigar lesões de cavidade oral e\nleucoplasia pilosa.","B":"Deve-se tranquilizar o paciente e solicitar sorologia para HIV, já que dois testes rápidos\npositivos\nde laboratórios diversos são insuficientes para\nfechar diagnóstico.","C":"A investigação de sintomas de doenças mentais não podem ser priorizada na avaliação porque\nnão há relação com a presença do HIV.","D":"Deve-se investigar uso de tabaco, álcool e drogas e também avaliar o risco cardiovascular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-214611","number":"214611","sourceNumber":"214611","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um lactente de seis meses é levado ao pediatra pela sua mãe, que se queixa de que a\ncriança não está engordando e é mais atrasada que os outros bebês de sua idade. Não se senta\ncom apoio, não rola na cama e não emite sons. A mãe não fez pré-natal, mas os testes realizados\nno pré-parto (teste rápido para HIV e VDRL), foram não reagentes. A criança tem as vacinas em dia\ne mama leite materno exclusivo. O peso de nascimento foi de 3.250 g. Há relato de um episódio de\npneumonia aos três meses de vida. No exame físico, observa-se peso de 4.300 g, palidez\n\ncutâneo-mucosa 2+/4+, panículo adiposo escasso, fígado a 4 cm da reborda costal direita e braço a\n3 cm da reborda costal esquerda. A escala\nde Denver mostra DNPM compatível com 3 meses de\nidade. Em relação ao quadro descrito acima, marque a afirmativa INCORRETA.","options":{"A":"O resultado do exame ELISA HIV realizado na criança foi reagente, confirmando o diagnóstico\nde transmissão vertical do HIV.","B":"O quadro clínico é compatível com aids de transmissão vertical.","C":"Exames sorológicos para toxoplasmose, citomegalovirose, sífilis, herpes I e II e carga viral para\nHIV são alguns do que devem ser solicitados como auxiliares no diagnóstico diferencial do quadro\napresentado pelo lactente.","D":"Caso a mãe da criança apresentasse, na admissão da maternidade, teste rápido para o HIV\npositivo, estaria indicado para o\nrecém-nascido zidovudina por 28 dias e 3 doses de nevirapina,\nsendo a primeira até 48 horas após o nascimento, a segunda 48 horas após a primeira e a terceira\n96 horas após a segunda dose como profilaxia para transmissão vertical do HIV."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-208561","number":"208561","sourceNumber":"208561","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre as infecções oculares relacionadas com HIV, é correto afirmar:","options":{"A":"em casos de contagem de CD4 abaixo de 50 céls/mm³, a uveíte causada pela toxoplasmose\ntende a apresentar lesão única com vitreíte\nintensa","B":"a associação com sífilis é rara, fazendo desnecessária a pesquisa de coinfecçao sifilítica","C":"o citomegalovírus está associado a retinite necrosante não exsudativa geralmente com\nhemorragias","D":"pacientes HIV-positivos apresentam menor tendência de resistência ao tratamento\nantituberculoso","E":"nenhuma das alternativas está correta"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-181553","number":"181553","sourceNumber":"181553","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um bebê nasceu de termo de uma mãe de 23 anos, HIV positiva. A mãe teve\nacompanhamento rigoroso durante a gravidez e recebeu medicação antirretroviral nas semanas\nanteriores ao parto. O protocolo de atendimento ao RN deve incluir:","options":{"A":"Iniciar zidovudina no RN.","B":"Administrar imunoglobulina no RN.","C":"Radiografia de tórax para avaliar pneumonia por Pneumocystis.","D":"Elisa para HIV para determinar se houve infecção do RN."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-137001","number":"137001","sourceNumber":"137001","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 48 anos está internado na Unidade de Terapia Intensiva em estado grave,\ncreatinina de 2 mg/dL, hemodinamicamente instável, com catéter venoso central. Na\nhemocultura houve crescimento de cândida albicans. A melhor conduta é:","options":{"A":"Retirar o catéter venoso central e observar por ser candidemia transitória.","B":"Não retirar o catéter venoso central e iniciar fluconazol.","C":"Retirar o catéter venoso central e iniciar fluconazol via endovenosa.","D":"Não retirar o catéter venoso central e iniciar anfotericina B."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-88424","number":"88424","sourceNumber":"88424","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual o agente etiológico mais comum na bacteriúria assintomática?","options":{"A":"Staphylococcus aureus.","B":"Burkholderia cepacia.","C":"Proteus mirabilis.","D":"Escherichia coli."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-75413","number":"75413","sourceNumber":"75413","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em gestante de 16 semanas, com infecção por HIV, a dosagem de linfócitos CD4\nresultou menor que 200 cel/mm3. Nesse caso, a\nprescrição de sulfametoxazol + trimetropim visa à\nprofilaxia de infecção por:","options":{"A":"Clamídia tracomatis.","B":"Toxoplasma gondii.","C":"Pneumocistis jiroveci.","D":"Herpes vírus hominis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-57618","number":"57618","sourceNumber":"57618","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"NÃO é observada em quaisquer das formas de apresentação clínica da\n\na falência das suprarrenais. Assinale a alternativa que apresenta a patologia que\npreenche corretamente a lacuna.","options":{"A":"Neoplasia maligna broncogênica","B":"Paracoccidioidomicose","C":"Micose fungoide","D":"Tuberculose","E":"Infecção meningocócica"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-360618","number":"360618","sourceNumber":"360618","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O diagnóstico sorológico da infecção por HTLV-1/2 baseia-se na detecção de\nanticorpos específicos contra o vírus:","options":{"A":"Os quais estão presentes em fluidos biológicos e são gerados a partir de uma resposta\nimunológica direcionada a antígenos virais codificados por genes estruturais e reguladores.","B":"Sendo ausentes nos fluidos biológicos, por serem gerados a partir de uma resposta imunológica\ndirecionada a antígenos virais codificados por genes estruturais e reguladores.","C":"Indetectáveis em fluidos biológicos por serem gerados a partir de uma resposta imunológica\ndirecionada a antígenos virais codificados por genes estruturais e reguladores.","D":"Nunca achados em fluidos biológicos, por não ser gerados a partir de uma resposta imunológica\ndirecionada a antígenos virais codificados por genes estruturais e reguladores."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-360620","number":"360620","sourceNumber":"360620","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A maioria das pessoas acometidas por HAM mielopatia associada ao HTLV-1 (HTLV-1\nAssociated Myelopathy):","options":{"A":"Evoluem bem sem a necessidade de uso de auxílio para marcha, e o tempo médio até varia de\nacordo com as características sociodemográficas e clínicas.","B":"Apresentam inicialmente necessidade de uso de auxílio para marcha, e o tempo médio até a\ndependência funcional é independente de características sociodemográficas e clínicas.","C":"Iniciam a doença com a necessidade de uso de auxílio para marcha, a dependência funcional\nvaria de acordo com as características\nsociodemográficas apenas, sem interações outras.","D":"Evoluem com necessidade de uso de auxílio para marcha, e o tempo médio até a dependência\nfuncional varia de acordo com as características sociodemográficas e clínicas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-360609","number":"360609","sourceNumber":"360609","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pessoas que vivem com o HTLV-1 podem apresentar distúrbios psiquiátricos/\npsicológicos:","options":{"A":"Tais como sinais de estresse psíquico, ansiedade, distúrbios do sono e psicossomáticos, não\nocorrendo desejo de morte ou falta de confiança no próprio desempenho.","B":"Tais como sinais de estresse psíquico, ansiedade, distúrbios do sono e psicossomáticos, desejo\nde morte, falta de confiança no próprio\ndesempenho e nível elevado de depressão.","C":"Mas não como sinais de estresse psíquico, ansiedade, distúrbios do sono e não os\npsicossomáticos, desejo de morte, falta de\nconfiança no próprio desempenho e nível elevado de\ndepressão.","D":"Não ocorrendo sinais de estresse psíquico, ansiedade, distúrbios do sono e somente os\npsicossomáticos, desejo de morte, falta de confiança no próprio desempenho e nível elevado de\ndepressão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-360587","number":"360587","sourceNumber":"360587","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com a introdução dos coquetéis para controle do HIV, a incidência de infecções por\nmicobactérias não tuberculosas (MNT) nessa população diminuiu.","options":{"A":"Entretanto, essa diminuição foi contrabalançada pela emergência de infecções em\nimunocomprometidos por outros motivos, como transplantes de órgãos, tratamentos de câncer e\nnão doenças autoimunes.","B":"Entretanto, essa diminuição foi contrabalançada pela emergência de infecções em\nimunocomprometidos por outros motivos, como transplantes de órgãos, tratamentos de câncer e\ndoenças autoimunes.","C":"Entretanto, essa diminuição não foi contrabalançada pela emergência de infecções em\nimunocomprometidos por outros motivos, como transplantes de órgãos, tratamentos de câncer e\ndoenças autoimunes.","D":"Entretanto, essa diminuição foi contrabalançada pela emergência de infecções em\nimunocomprometidos por outros motivos, mas não por transplantes de órgãos, tratamentos de\ncâncer e doenças autoimunes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-330690","number":"330690","sourceNumber":"330690","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Embora certos esquemas de antirretroviral - ARV possam aumentar o risco\ncardiovascular:","options":{"A":"Os benefícios da Terapia antirretroviral - TARV não superam o pequeno risco adicional\nobservado com seu uso.","B":"Os benefícios da Terapia antirretroviral - TARV superam o alto risco adicional observado com\nseu uso.","C":"Os benefícios da Terapia antirretroviral - TARV superam o pequeno risco adicional observado\ncom seu uso.","D":"Os benefícios da Terapia antirretroviral - TARV são menores que o risco adicional observado\ncom seu uso."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-330692","number":"330692","sourceNumber":"330692","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Esses individuos sao frequentemente chamados de ?controladores de elite?, estando\nde acordo com o item:","options":{"A":"Um pequeno grupo de indivíduos infectados pelo HIV mantém níveis plasmáticos de CV-HIV\nbem acima do nível de quantificação durante\nanos, sem uso de TARV.","B":"Um pequeno grupo de indivíduos infectados pelo HIV mantém níveis plasmáticos de CV-HIV\nabaixo do nível de quantificação durante anos, com uso de TARV.","C":"Um pequeno grupo de indivíduos infectados pelo HIV mantém níveis plasmáticos de CV-HIV\nabaixo do nível de quantificação durante dias, sem uso de TARV.","D":"Um pequeno grupo de indivíduos infectados pelo HIV mantém níveis plasmáticos de CV-HIV\nabaixo do nível de quantificação durante anos, sem uso de TARV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-330697","number":"330697","sourceNumber":"330697","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Dado o claro benefício da terapia antirretroviral - TARV, independentemente da\ncontagem de LT-CD4+, pode-se afirmar que:","options":{"A":"O atraso do tratamento para observar se um paciente se tornará um controlador de elite após o\ndiagnóstico inicial é fortemente encorajado.","B":"O atraso do tratamento para observar se um paciente se tornará um controlador de elite após o\ndiagnóstico inicial é fortemente desencorajado.","C":"O atraso do tratamento para observar se um paciente se tornará um controlador de elite após o\ndiagnóstico inicial não é desencorajado.","D":"O atraso do tratamento para não observar se um paciente se tornará um controlador de elite\napós o diagnóstico inicial é fortemente desencorajado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-301587","number":"301587","sourceNumber":"301587","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os efeitos da TARV que contêm a proliferação viral maciça e a progressão da doença:","options":{"A":"Ocorre persistente multiplicação do HIV no tecido linfoide de diversos sítios, excluindo o\nsistema\nnervoso central, o trato gastrintestinal e o próprio tecido adiposo, locais considerados santuários\nde\nreplicação viral, o que permite o estabelecimento de um estado de atividade inflamatória crônica.","B":"Ocorre persistente multiplicação do HIV no tecido linfoide de diversos sítios, incluindo o\nsistema\nnervoso central, o trato gastrintestinal e o próprio tecido adiposo, locais considerados santuários\nde\nreplicação viral, o que não permite o estabelecimento de um estado de atividade inflamatória\ncrônica.","C":"Ocorre persistente divisão do HIV no tecido linfoide de diversos sítios, incluindo o sistema\nnervoso central, o trato gastrintestinal e o\npróprio tecido adiposo, locais considerados santuários de\nreplicação viral, o que não permite o estabelecimento de um estado de atividade inflamatória\ncrônica.","D":"Ocorre persistente multiplicação do HIV no tecido linfoide de diversos sítios, incluindo o\nsistema\nnervoso central, o trato gastrintestinal e o próprio tecido adiposo, locais considerados santuários\nde\nreplicação viral, o que permite o estabelecimento de um estado de atividade inflamatória crônica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-301646","number":"301646","sourceNumber":"301646","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O cuidado às pessoa vivendo com HIV PVHIV está de acordo com o item:","options":{"A":"Deve abordar a vivência sexual sem sua plenitude, com questões referentes, por exemplo, à\nidentificação de práticas sexuais de risco, à infertilidade e ao planejamento reprodutivo.","B":"Deve abordar a vivência sexual em sua plenitude, com questões referentes, por exemplo, à\nidentificação de práticas sexuais de risco, à infertilidade e ao planejamento reprodutivo.","C":"Deve abordar a vivência sexual em sua plenitude, com questões referentes, por exemplo, à\nidentificação de práticas sexuais de risco, e não à infertilidade e ao planejamento reprodutivo.","D":"Deve abordar a vivência sexual em sua plenitude, com questões referentes, por exemplo, à\nidentificação de práticas sexuais de risco, à infertilidade e nunca planejamento reprodutivo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284143","number":"284143","sourceNumber":"284143","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A estratégia de controle da coinfecção TB-HIV está de acordo com o item:","options":{"A":"Pautada no diagnóstico tardio de ambas as afecções e na garantia de tratamento adequado para\no paciente, de forma oportuna.","B":"Pautada no diagnóstico precoce de ambas as afecções e na garantia de tratamento adequado\npara o paciente, de forma oportuna.","C":"Pautada no diagnóstico precoce de ambas as afecções e não na garantia de tratamento\nadequado para o paciente, de forma oportuna.","D":"Pautada no diagnóstico precoce de ambas as afecções e na garantia de tratamento inadequado\npara o paciente, de forma oportuna."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284145","number":"284145","sourceNumber":"284145","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Nos pacientes com imunossupressão grave, pode-se afirmar que:","options":{"A":"As formas extrapulmonares e disseminadas da TB devem fazer parte das investigações sobre\ninfecção oportunista (IO).","B":"As formas extrapulmonares e disseminadas da TB não devem fazer parte das investigações\nsobre infecção oportunista (IO).","C":"As formas extrapulmonares e não as disseminadas da TB devem fazer parte das investigações\nsobre infecção oportunista (IO).","D":"Somente as formas extrapulmonares da TB devem fazer parte das investigações sobre infecção\noportunista (IO)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284149","number":"284149","sourceNumber":"284149","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O manejo das hepatopatias é um componente importante do cuidado das pessoa\nvivendo com HIV PVHIV. Sendo correto o item:","options":{"A":"Embora a utilização da TARV terapia antirretroviral tenha acarretado um aumento significativo\nnas mortes relacionadas às complicações da\ninfecção pelo HIV, as hepatopatias têm aparecido\ncomo uma das causas mais comuns de mortalidade em PVHIV.","B":"Embora a utilização da TARV terapia antirretroviral tenha acarretado uma redução significativa\nnas mortes relacionadas às complicações da\ninfecção pelo HIV, as hepatopatias têm aparecido\ncomo uma das causas mais raras de mortalidade em PVHIV.","C":"Embora a utilização da TARV terapia antirretroviral tenha acarretado uma redução significativa\nnas mortes relacionadas às complicações da\ninfecção pelo HIV, as hepatopatias têm aparecido\ncomo uma das causas mais comuns de mortalidade em PVHIV.","D":"Embora a utilização da TARV terapia antirretroviral não tenha acarretado uma redução\nsignificativa nas mortes relacionadas às\ncomplicações da infecção pelo HIV, as hepatopatias têm\naparecido como uma das causas mais comuns de mortalidade em PVHIV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-284154","number":"284154","sourceNumber":"284154","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pacientes infectados pelo HIV, frequentemente, recebem prescrição de vários\nmedicamentos que não os antirretroviral ARV, os quais podem ter efeitos adversos hepáticos,\nisoladamente ou em combinação. Podemos indicar como correto o item:","options":{"A":"Não podemos evitar a adição de medicações hepatotóxicas ao esquema de antirretroviral ARV.","B":"Deve-se evitar, sempre que possível, a adição de medicações hepatotóxicas ao esquema de\nantirretroviral ARV.","C":"Deve-se evitar, sempre que possível, a retirada de medicações hepatotóxicas ao esquema de\nantirretroviral ARV.","D":"Deve-se evitar, sempre que possível, a adição de medicações não hepatotóxicas ao esquema\nde antirretroviral ARV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-216871","number":"216871","sourceNumber":"216871","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com o objetivo de chamar a atenção dos profissionais de saúde, o Grupo Brasileiro de\nImunodeficiências Primárias (Bragid), adaptou e publicou os Dez Sinais de Alerta para\nImunodeficiências Primárias na criança. Dentre estes dez sinais podemos citar:","options":{"A":"Presença de 3 infecções virais de vias aéreas superiores no último ano.","B":"Presença de 2 otites no último ano.","C":"Um episódio de infecção sistêmica grave (meningite, septicemia)","D":"Ausência de história familiar de imunodeficiência."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177877","number":"177877","sourceNumber":"177877","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Trata-se de um paciente com Imunodeficiência Humana que apresenta úlcera esofágica\nprofunda, linear em um exame de endoscopia digestiva. Pode-se pensar em:","options":{"A":"Doença de refluxo gastroesofágico.","B":"Helicobacter pylori.","C":"Candidíase.","D":"Sarcoma de Kaposi.","E":"Citomegalovírus."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177170","number":"177170","sourceNumber":"177170","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher, parda, 36 anos, trabalhadora do lar, ensino médio completo, casada,\nprocedente de Bela Vista ? MS. Apresentou em\npoucos dias hemiplegia e alteração de\nsensibilidade em hemídio esquerdo, onde foi encaminhada para o hospital de referência. Anti-HIV\nreagente. Linfócito T CD4 = 56 céls/mm³, carga viral > 1 milhão cópias. Tomografia de crânio com\nimagens hipodensas com captação anelar de contraste em núcleos de base. Liquor sem\nalterações. O diagnóstico mais provável é (clínico ? epidemiologicamente):","options":{"A":"Toxoplasmose cerebral.","B":"Linfoma primário do cérebro.","C":"Abscesso bacteriano.","D":"Tuberculose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177974","number":"177974","sourceNumber":"177974","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No que diz respeito à transmissão materno-fetal do vírus HIV, pode-se afirmar que:","options":{"A":"o recém-nascido de mãe com diagnóstico de infecção pelo HIV deve receber a zidovudina\npreferencialmente nas primeiras 8 horas após o nascimento.","B":"a administração da zidovudina tardiamente, na gestação, não reduz a transmissão vertical do\nHIV.","C":"o aleitamento materno não está contraindicado nas mães portadoras do vírus HIV.","D":"a carga viral e a ruptura prolongada de membranas ovulares não estão associadas à maior\ntransmissão vertical do HIV.","E":"a vacinação com BGG-ID e anti-hepatite B, realizadas habitualmente após o nascimento, está\ncontraindicada para recém-nascido de mãe soropositiva."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-155685","number":"155685","sourceNumber":"155685","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São tumores em pacientes portadores do HIV definidores de Síndrome da\nImunodeficiência Adquirida, EXCETO:","options":{"A":"Carcinoma Escamocelular Invasivo.","B":"Leiomiosarcoma.","C":"Linfoma cerebral primário.","D":"Linfoma de Burkitt.","E":"Sarcoma de Kaposi."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-156301","number":"156301","sourceNumber":"156301","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher de 45 anos procurou a Unidade Básica de Saúde (UBS) com queixa de diarreia\naquosa (4 evacuações ao dia) há cerca de 2 meses e emagrecimento de 8 kg nos últimos 6 meses.\nApresenta comportamento promíscuo com relações sexuais desprotegidas. Qual exame o médico\nda UBS deve solicitar?","options":{"A":"Carga viral.","B":"Imunoblot rápido.","C":"Western blotting.","D":"Imunofluorescência indireta para o HIV.","E":"Reação de ensaio imunoenzimático."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-155601","number":"155601","sourceNumber":"155601","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Aluno do 5° ano de Medicina, vinculado à liga do trauma de uma universidade da\ncidade, durante o procedimento de sutura,\nsofre um acidente perfurativo ao encapar a agulha que\nutilizou para anestesiar o paciente. Trata-se de um paciente sabidamente com infecção por vírus\ndas hepatites B e C, mas que é HIV-negativo. Os exames laboratoriais básicos realizados no\nestudante incluem a seguinte sorologia: HBsAg negativo, anticorpo anti-HBs positivo e lgG anti-HBc\nnegativo. O aluno deve receber qual profilaxia?","options":{"A":"Imunoglobulina contra vírus de hepatite B.","B":"Imunoglobulina intravenosa.","C":"Lamivudina.","D":"Não há necessidade de profilaxia.","E":"Penicilina benzatina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-140364","number":"140364","sourceNumber":"140364","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual (is) antibiótico (s) deve (m) ser evitado (s) no tratamento de infecções do sistema\nnervoso central, por apresentar (em) baixa penetração no liquor:","options":{"A":"Imipenem.","B":"Cefalosporina de 1ª geração.","C":"Cefalosporina de 4ª geração.","D":"Cloranfinicol.","E":"Meropenem."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-138020","number":"138020","sourceNumber":"138020","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação à Aids na clínica pediátrica, avalie o que se afirma a seguir: I. A carga\nviral\nplasmática materna durante a gestação não tem relação com risco de transmissão vertical do HIV;\n\nII. Criança com idade até 18 meses que possui primeira carga viral detectável, segunda carga viral\nindetectável e terceira carga viral também indetectável é considerada não infectada; III. Apesar da\nimaturidade imunológica das crianças, a velocidade de progressão dessa doença e sua evolução\nclínica é igual em crianças e adultos; IV. A via de parto será definida por critérios obstétricos e\nnão\nhá relação com a carga viral do HIV da gestante. Está CORRETO o que se afirma em:","options":{"A":"I, II, III e IV.","B":"II e IV apenas.","C":"III e IV apenas.","D":"I e IV apenas.","E":"II apenas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-137890","number":"137890","sourceNumber":"137890","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre a Infecção do Trato Urinário (ITU) em mulheres, é incorreto afirmar que:","options":{"A":"A ITU recorrente se caracteriza pela manifestação clínica de 4 ou mais episódios ao longo de 12\nmeses.","B":"A bacteriúria é caracterizada à Urocultura através do isolamento de 10 elevada a 5 UFC/ml de\num uropatógeno.","C":"A E.Coli é o patógeno mais frequente (cerca de 85%), seguido de Staphylococus saprophyticus\n(cerca de 10 a 15%).","D":"A bacteriúria assintomática é observada em cerca de 5% das mulheres em idade reprodutiva e\ndeve ser tratada somente em grupos\nsegmentares específicos.","E":"Nas ITU de Repetição, indica-se antibióticoprofilaxia em dose única noturna ou pós-relação\nsexual."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-130097","number":"130097","sourceNumber":"130097","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A \"bacteriúria assintomática\" consiste na ausência de sintomas clínicos por parte do\npaciente com a presença de mais de 10³ unidades formadoras de colônias/ml de urina para um\ndeterminado micro-organismo em duas ou mais amostras coletadas do jato médio.\n\nConsiderando-se que os pacientes abaixo apresentam bacteriúria em duas amostras consecutivas,\nsem sintomas clínicos e exames de ultrassonografia\nde rins e vias urinárias sem alterações, qual\ndeles requer tratamento antimicrobiano?","options":{"A":"Pessoa vivendo com HIV/Aids (PVHA).","B":"Portador de transplante renal.","C":"Pessoa com bexiga neurogênica.","D":"Portador de lúpus eritematoso sistêmico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-132218","number":"132218","sourceNumber":"132218","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 70 anos chega ao PS febril, taquicárdico, hipotenso. Foi atendido,\nmedicado, iniciado antibioticoterapia empírica\ne colhidos culturas, após 24 horas há crescimento de\nbactéria gram negativa, sugestivo de Escherichia Coli. Neste caso, qual o sítio primário da infecção\nmais provável?","options":{"A":"Trato urinário","B":"Vias biliares","C":"Sistema respiratório","D":"Sistema nervoso central"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-132282","number":"132282","sourceNumber":"132282","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Para determinar a sensibilidade de um isolado bacteriano a agentes antimicrobianos\nque poderiam ser considerados para a terapia, qual é\no parâmetro\nfarmacocinético/farmacodinâmico mais importante a ser avalidado em um resultado de cultura?","options":{"A":"Eliminação tempo-dependente.","B":"Eliminação concentração-dependente.","C":"Efeito pós-antibiótico.","D":"Concentração inibitória mínima."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-132294","number":"132294","sourceNumber":"132294","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O principal agente etiológico e a valva acometida em pacientes usuários de droga com\ndiagnóstico de Endocardite Bacteriana são respectivamente:","options":{"A":"Streptococcus viridans; valva mitral.","B":"Staphylococcus aureus; valva mitral.","C":"Streptococcus viridans; valva tricúspide.","D":"Staphylococcus aureus; valva tricúspide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-107805","number":"107805","sourceNumber":"107805","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente, 29 anos, dá entrada no serviço de emergência devido a quadro convulsivo\ncom características tônico-clônicas há 30 minutos.\nFamiliares referem história de perda ponderal\nimportante nos últimos meses e há 2 dias perda de força em membro superior direito. Você solicita,\nentre outros exames, o teste rápido para HIV, que resulta como positivo. Qual a melhor conduta\nnesse caso?","options":{"A":"Iniciar terapia com manitol e corticoide associado a anticonvulsivantes.","B":"Iniciar pirimetamina e anfotericina empiricamente até resultado dos exames.","C":"Realizar coleta de líquido cefalorraquidiano e iniciar empiricamente sulfadiazina associada à\npirimetamina.","D":"Realizar tomografia computadorizada de crânio após estabilização clínica.","E":"Realizar coleta de líquido cefalorraquidiano após estabilização clínica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-111731","number":"111731","sourceNumber":"111731","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A respeito dos antimicrobianos e sua ação sobre os germes e o organismo humano,\nassinale a alternativa com a afirmativa CORRETA:","options":{"A":"Entre as substâncias que interferem na síntese do peptidoglicano, constituinte fundamental da\nparede celular bacteriana, tem-se as tetraciclinas e aminoglicosídeos.","B":"A resistência natural (intrínseca) é um caráter hereditário transmitido verticalmente às\ncélulas-filhas através de genes cromossômicos.","C":"O diagnóstico sindrômico e diagnóstico anatômico são variáveis que exercem pouca influência\nna escolha do antimicrobiano a ser utilizado.","D":"Nas profilaxias, a droga prescrita deve ser ativa contra o microorganismo envolvido na gênese\nda infecção, preferindo-se drogas com espectro\nde ação mais amplo.","E":"As tetraciclinas e glicilciclinas (ex.tigeciclina) podem causar tendinite e ruptura de tendão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-106952","number":"106952","sourceNumber":"106952","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quando iniciamos tratamento de qualquer quadro infeccioso, notadamente com\nutilização de antimicrobianos, devemos considerar interações e efeitos colaterais. São esses\nverdadeiros EXCETO por:","options":{"A":"Nefrotoxicidade das Cefalosporinas.","B":"Nefrotoxicidade dos Aminoglicosídeos.","C":"Teratogenicidade dos derivados do Enxofre (Sulfas).","D":"Teratogenicidade das Penicilinas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-64939","number":"64939","sourceNumber":"64939","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Pré-escolar de três anos, em consulta ambulatorial, vem com lesões em nádegas, tipo\nvesículas e bolhas flácidas de até 2 cm, com conteúdo inicialmente límpido e posteriormente turvo.\nQual é o principal agente etiológico e respectivo diagnóstico?","options":{"A":"Estreptococos / ectima.","B":"S. aureus / impetigo bolhoso.","C":"Estreptococos / erisipela.","D":"Herpes-vírus / herpes.","E":"S. aureus / impetigo crostoso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45457","number":"45457","sourceNumber":"45457","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação à meningite bacteriana na criança, assinale a alternativa INCORRETA.","options":{"A":"Sabendo que a duração da antibioticoterapia depende do micro-organismo isolado, as\nmeningites meningocócicas devem ser tratadas durante 10 dias com penicilina cristalina ou em\ncasos especiais, como alergia, com ceftriaxone ou cefotaxime.","B":"Existem algumas contraindicações para realizar punção lombar em uma criança, como a\npresença de infecção no local da punção, paciente hemofílico e trombocitopenia grave =\n50.000/mm³.","C":"Os sinais e sintomas de meningite bacteriana são frequentemente inespecíficos especialmente\nnas crianças mais jovens. Os sintomas incluem\nfebre alta, vômito, letargia e irritabilidade. Os sinais\nclínicos incluem abaulamento de fontanela, sonolência e nas crianças maiores a rigidez de nuca, e\nos sinais de Kernig, e Brudzinski costumam ser positivos.","D":"Na avaliação do líquor, a contagem de leucócitos está \"maior que\" 500, Neutrófilos \"maior que\"\n50, glicose \"menor que\" 30 e proteínas \"maior\nque\" 100.","E":"Tem sido usadas diferentes doses de dexametasona. Uma dose de 0,4 mg/kg a cada 12 horas\ndurante dois dias provou ser tão segura e\neficaz quanto a dose de 0,15 mg/kg/dose a cada 6 horas,\npor 4 dias."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45896","number":"45896","sourceNumber":"45896","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na profilaxia da endorcardite infecciosa, qual dos procedimentos abaixo apresenta\nmaior percentual de risco de bacteremia após sua\nrealização?","options":{"A":"Broncoscopia rígida.","B":"Tonsilectomia.","C":"Cirurgia periodontal.","D":"Entubação traqueal.","E":"Extração dentária."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45949","number":"45949","sourceNumber":"45949","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A higienização das mãos e a medida individual mais simples para previnir as infecções\nrelacionadas à assistência a saúde PORQUE: A população transitória e a residente da pele do\nprofissional de saúde é colonizada por bactérias multirresistentes. Sobre essas duas afirmativas é\ncorreto:","options":{"A":"A primeira é uma afirmativa correta e a segunda é falsa","B":"A primeira é uma afirmativa falsa e a segunda verdadeira","C":"As duas são verdadeiras, mas não estabelecem razão entre si","D":"As duas estão corretas e estabelecem razão entre si","E":"As duas são falsas"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45939","number":"45939","sourceNumber":"45939","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Dentro do pacote (bundle) de prevenção de infecção de corrente sanguínea, os\nprincipais componentes são, com EXCEÇÃO de:","options":{"A":"Higienização das mãos.","B":"Precauções de barreiras restritas ao local de inserção sendo indicado somente o uso de luvas\nestéreis para a sua inserção.","C":"Antissepsia e com Clorexidina.","D":"Escolha de sítio de inserção adequado com preferência para a veia subclávia nos casos de\ncateteres não tunelizados.","E":"Reavalição diária da necessidade de manutenção de cateter, com pronta remoção daqueles\ndesnecessários."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-22629","number":"22629","sourceNumber":"22629","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O indicador clínico precoce mais confiável da septicemia é:","options":{"A":"Os calafrios","B":"A febre","C":"A hiperventilação","D":"A letargia","E":"A mudança no status mental"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-8744","number":"8744","sourceNumber":"8744","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação à infecção do trato urinário - ITU, é incorreta a informação:","options":{"A":"a cateterização vesical é um importante fator de risco para ITU hospitalar.","B":"o agente etiológico mais frequente é a Escherichia coli.","C":"infecções de repetição em mulheres podem estar relacionadas à atividade sexual.","D":"a síndrome uretral se caracteriza por apresentar sintomas urinários, porém com sedimento\nurinário normal ou com leucocitúria e urocultura negativa.","E":"a presença de bactérias evidenciadas no exame de urina tipo I, em pacientes sem queixas\nurinárias, caracteriza bacteriúria assintomática."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-330519","number":"330519","sourceNumber":"330519","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação aos cuidados com o recém-nascido é CORRETO afirmar:","options":{"A":"Em recém-nascidos prematuros, os banhos devem ser realizados utilizando esponjas, pois\ncausam menor variabilidade de temperatura","B":"O primeiro banho de recém-nascidos filhos de mães soropositivas para o HIV deve ser realizado\no mais precocemente possível","C":"O vérnix deve ser removido do recém-nascido o mais precocemente possível","D":"Os sabonetes com pH alcalino são os ideais para o banho de recém-nascidos"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-255907","number":"255907","sourceNumber":"255907","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher de 67 anos vai ao pronto atendimento queixando-se de tosse seca e dispneia há\n7 dias, que evoluiu com piora progressiva e\nocorre mesmo em repouso no momento. Nega febre,\ndor torácica, ortopneia ou sintomas de aéreas superiores. É portadora de câncer de mama e está\nrealizando quimioterapia. Ao exame físico, apresente PA = 120/80 mmHg, FC = 89 bpm, FR = 26\nirpm, SpO2 em ar ambiente 80%. Encontra-se alerta e orientada. O exame respiratório revela\ntaquipneia e esforço respiratório; a ausculta não apresenta anormalidades. O exame cardiovasular\nrevela ictus cordis no 4° espaço intercostal esquerdo e linha hemiclavicular, ritmo cardíaco\nregular,\nsem anormalidades; pulso venoso jugular interno direito visualizado a 2 cm do esterno, sem refluxo\nhepatojugular. Restante do exame físico sem anormalidades. Exames de laboratório: Hb = 12,9\ng/dl; LG = 5.600/mm³; NS = 3.450/mm³; Plq = 210.000/mm³; LDH = 1.200 U/L; PCR = 80 mg/L;\nCreat. = 1,2 mg/dl. TC tórax: infiltrado em vidro fosco e espessamento septal intralobular e\ninterlobular, constituindo padrão de pavimentação em mosaico, difusamente encontrado em ambos\nos campos pulmonares de distribuição peri-hilar predominante. Dentre as alternativas abaixo,\nassinale a que apresenta o tratamento empírico MAIS ADEQUADO para essa paciente.","options":{"A":"Amoxicilina e clavulanato.","B":"Enoxaparina.","C":"Furosemida e nitroglicerina.","D":"Sulfametoxazol-trimetoprima e prednisona."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-233777","number":"233777","sourceNumber":"233777","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recém-nascido do sexo masculino com 28 dias de vida é trazido para primeira consulta\nna UBS pela mãe, que nega intercorrências até\no momento, exceto por fezes mais ressecadas da\ncriança. Vem aceitando bem a fórmula láctea, em intervalos de 3 em 3 horas, recebendo ainda\nZidovudina (ZDV) por via oral. Mãe refere ser infectada pelo HIV, fez pré-natal irregular e traz\nexames de segundo trimestre gestacional evidenciando replicação viral persistente apesar de estar,\nà época, tomando regularmente os antirretrovirais. A conduta MAIS ADEQUADA para essa criança\nneste momento é:","options":{"A":"Associar à zidovudina, o medicamento nevirapina em três doses para bloqueio adicional da\ntransmissão vertical.","B":"Iniciar sulfametoxazol-trimetoprim às 2ª, 4ª e 6ª feiras, após suspensão do ZDV, e mantê-lo por\n12 meses, independentemente do status\ninfeccioso da criança.","C":"Manter zidovudina até 4 semanas de vida e após, vacinar com BCG se peso maior que 2.000g,\ne também contra Hepatite B.","D":"Solicitar genotipagem do HIV para definição precoce de estar infectada, devido a seu maior risco\npara esta infecção."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-127562","number":"127562","sourceNumber":"127562","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"LMF, 35 anos, gênero feminino, engenheira ambiental, aparece com área de enduração\nna região da nuca, intensamente dolorosa e\navermelhada, no centro da qual se desenvolvem\nmúltiplas áreas de necrose das quais sai pequena quantidade de pus. A pele, no local da necrose,\napresenta-se com um aspecto de favo de mel. Mostra-se febril. Em relação a este caso, qual das\nalternativas abaixo está CORRETA?","options":{"A":"A maioria dos casos assemelhados pode ser tratada conservadoramente","B":"Antibioticoterapia sistêmica deve ser instituída","C":"Trata-se mais provavelmente de infecção por Bacillus anthracis","D":"Trata-se mais provavelmente de infecção por estreptococo"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-141300","number":"141300","sourceNumber":"141300","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Na lista a seguir, constitui doença para a qual está indicada quimioprofilaxia em\ncomunicante:","options":{"A":"Poliomielite.","B":"Hepatite A.","C":"Tuberculose.","D":"Doença meningocócica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-112666","number":"112666","sourceNumber":"112666","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recém-nascido à termo, gênero feminino, apresenta lesão de pele caracterizada por\nvesículas que se transformam em bolhas flácidas. Algumas se rompem deixando uma base\neritematosa. Essa lesão de pele é quase sempre causada pelo:","options":{"A":"Haemophilus influenza","B":"Staficlococcus aureus","C":"Streptococcus do grupo A","D":"Pseudomonas aeruginosa"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-101865","number":"101865","sourceNumber":"101865","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às manifestações pulmonares nos pacientes infectados pelo vírus HIV, é\nERRADO afirmar que:","options":{"A":"A disfunção celular dos linfócitos B aumenta o risco de desenvolvimento de infecções\npulmonares, principalmente por Streptococcus pneumoniae e Haemophilus influenzae.","B":"A tuberculose é mais frequente do que na população em geral, principalmente nos pacientes\ncom contagem de linfócitos CD4 \"menor ou igual a\"\n350 céls/mm³.","C":"Hipoxemia, infiltrado intersticial difuso bilateral e derrame pleural são achados comuns em\npacientes com pneumonia por Pneumocystis jirovecii.","D":"O sarcoma de Kaposi é uma manifestação pouco frequente nos dias atuais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-71491","number":"71491","sourceNumber":"71491","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Senhora de 72 anos, hígida, veio ao ambulatório preocupada com o resultado de suas\núltimas uroculturas. Apesar de assintomática, os exames mostravam, repetidamente, presença de\nEscherichia coli em contagem sempre superior a 100.000 UFC/ml. Avaliação ginecológica recente\nfoi considerada normal para a idade. A intervenção médica MAIS PRUDENTE neste caso seria:","options":{"A":"Tratamento da infecção urinária, de acordo com o antibiograma, por prazo não inferior a 10 dias,\npor se tratar de paciente idosa.","B":"Tratamento do quadro agudo, por prazo não inferior a 10 dias, seguido de terapia de\nmanutenção com nitrofurantoína por 3 meses.","C":"Reforçar medidas preventivas e reservar tratamento antimicrobiano no caso de surgirem\nsintomas clínicos.","D":"Solicitar exames de imagem do trato urinário."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-53355","number":"53355","sourceNumber":"53355","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um lactente de sete meses de vida evoluindo nas últimas 48 horas com febre, letargia e\nirritabilidade. Dentro dessas 48 horas recebeu duas doses de amoxicilina. A mãe o leva a um\nserviço de pronto atendimento com relato de crise convulsiva. Qual das alternativas abaixo,\nrelativas ao caso deste paciente é INCORRETA:","options":{"A":"Se houver sinais de hipertensão intracraniana a punção lombar deve ser precedida de uma\ntomografia de crânio.","B":"Um exame de liquor inicial normal descarta a possibilidade de infecção do sistema nervoso\ncentral.","C":"O leucograma com a presença de leucocitose e desvio para a esquerda não é suficiente para\ndiferenciar infecções bacterianas de virais, principalmente em recém-nascidos.","D":"O uso do antibiótico neste paciente não altera de modo significativo os achados morfológicos e\nde composição química do liquor."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-45204","number":"45204","sourceNumber":"45204","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 16 anos de idade, estudante, dá entrada em serviço de Pronto\nAtendimento (PA), acompanhado da namorada,\ncom quadro clínico sugestivo de meningite. Não foi\nrealizado nenhum procedimento invasivo no Pronto Atendimento (PA). Trinta minutos após a\nentrada, o paciente foi transferido para um hospital de referência, onde foram coletados materiais\nbiológicos para exames laboratoriais, incluindo liquor. Foi iniciado tratamento com ceftriaxona. O\nexame do liquor foi compatível com meningite bacteriana e a reação de látex no soro foi positiva\npara Neisseria meningitidis. Sobre a realização da quimioprofilaxia da infecção pela N.\nmeningitidis,\nassinale a alternativa CORRETA:","options":{"A":"Deverá ser iniciada nos contatos somente após a cultura do liquor comprovar o crescimento da\n\nN. meningitidis.","B":"Deverá ser realizada nos familiares que residem com o paciente, na namorada e nos colegas de\nturma que mantinham contato próximo, e na equipe do PA.","C":"O medicamento indicado pelo Ministério da Saúde para a quimioprofilaxia dos contatos de casos\nconfirmados ou suspeitos é a Rifampicina.","D":"Também está indicada para o próprio paciente para erradicação da bactéria de sua orofaringe,\nevitando-se assim, o estado de portador."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-53311","number":"53311","sourceNumber":"53311","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma criança de 10 anos, previamente hígida, é levada a um pronto-socorrro com\nhistória de febre, tosse e dor torácica no\nhemitórax direito há dois dias. Está febril, taquicárdica e\ntaquipneica, com macicez à percussão, abolição do murmúrio vesicular no 1/3 inferior do hemitórax\nafetado e frêmito tóraco vocal diminuído. O diagnóstico para o caso baseado na história clínica,\nepidemiologia e dados semiológicos é:","options":{"A":"Pneumonia alveolar.","B":"Pneumonia necrotizante com derrame pleural.","C":"Pneumonia intersticial com derrame.","D":"Pneumonia alveolar com derrame pleural."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-22862","number":"22862","sourceNumber":"22862","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher de 62 anos vem à consulta ambulatorial por disúria, algúria e polaciúria, há 8\ndias. Nega febre e diz que sua urina está\nescura. Admitiu quadro semelhante há 1 ano. Usa apenas\nbloqueador de enzima conversora, para hipertensão arterial, e faz controle periódico com sua\nequipe de saúde. Seu exame mostra estar em bom estado geral, afebril, com dor discreta à\npalpação da região suprapúbica. Sua PA = 150/84 mmHg. Trouxe exame de urinálise recente que\nrevela presença de 7 hemácias/campo e piúria. Com estes dados pode-se afirmar:","options":{"A":"<P>Não é possível fazer qualquer diagnóstico seguro, sem estender&nbsp;a propedêutica.</P>","B":"Há evidências, na literatura, que sustentam a conduta de se iniciar a antibioticoterapia já neste\nmomento da abordagem.","C":"Caso se opte pela antibioticoterapia, esta não depende da susceptibilidade antibacteriana da\nEscherichia coli naquela comunidade.","D":"<P>Independentemente da sua conduta inicial, será necessário sua referência ao\nnefrologista.</P>"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-22910","number":"22910","sourceNumber":"22910","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo feminino, 75 anos, foi submetida a anastomose biliodigestiva no\ntratamento de carcinoma irressecável e metastático da cabeça do pâncreas. No pós-operatório\ncursou com febre, anorexia e astenia. No oitavo dia apresentou quadro súbito de dispnéia e\nhipotensão, sendo acionado o médico de plantão. Após avaliação clínico-radiológica, o mesmo\nconcluiu que a paciente apresentava pneumonia, hipoxemia grave e choque misto. Dentre as\nopções terapêuticas abaixo citadas, assinale aquela(s) que não deveria(m) ser realizada(s) nessa\npaciente:","options":{"A":"Antibioticoterapia","B":"Entubação orotraqueal e ventilação assistida","C":"Oxigenioterapia","D":"Reposição volêmica e correção de eventuais distúrbios hidro-eletrolíticos e ácidos-básicos"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-355421","number":"355421","sourceNumber":"355421","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo masculino, 34 anos, internado em contexto de primodiagnóstico de\nHIV devido à febre, cefaleia e sonolência.\nEvoluiu com rebaixamento do sensório, sendo intubado e\nencaminhado a tomografia seguido de punção liquórica que apresentou pressão de abertura de 27\ne análise bioquímica do líquor revelou glicose de 40 mg/dL, celularidade de 35 cels/microL,\nproteinorraquia de 200 mg/dL, além de cultura positiva para Criptococcus neoformans. A respeito\ndo manejo desse paciente, assinale a alternativa que apresenta as condutas corretas.","options":{"A":"Iniciar tratamento combinado de anfotericina B e fluconazol, além de punção liquórica frequente.","B":"Iniciar tratamento combinado de anfotericina B e fluconazol, além de início de terapia\nantirretroviral.","C":"Iniciar tratamento combinado de itraconazol e fluconazol, além de aciclovir e nova tomografia de\ncrânio.","D":"Iniciar tratamento combinado de anfotericina B e voriconazol, além de terapia antirretroviral e\npunção liquórica frequente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-372565","number":"372565","sourceNumber":"372565","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação a transmissão vertical do HIV (Vírus da Imunodeficiência Humana), assinale\na alternativa CORRETA:","options":{"A":"Na gestante infectada pelo HIV, a cesariana é sempre a via de parto indicada.","B":"Pelas amplas vantagens do leite materno, a amamentação pode ser mantida pela mãe infectada\npelo HIV.","C":"A transmissão do vírus pode ser placentária, mas na maioria das vezes ocorre no peri-parto.","D":"O uso de terapia anti-retroviral pela gestante não altera as taxas de transmissão do HIV para o\nrécem nascido."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-361689","number":"361689","sourceNumber":"361689","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em caso de gestante portadora de HIV com carga viral indetectável após 34 semanas\nde gestação, e que estejam em terapia\nantirretroviral com boa adesão são recomendados os\nseguintes cuidados na sala de parto para evitar a contaminação da criança, à exceção de um,\nassinale-o.","options":{"A":"O clampeamento do cordão umbilical deve ser imediato.","B":"Se possível, realizar o parto empelicado.","C":"Realizar o banho após estabilização térmica do bebê.","D":"Evitar aspiração de estômago, porém, se necessário, aspirar delicadamente evitando lesão de\nmucosa e na presença de sangue realizar\nlavagem gástrica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-311260","number":"311260","sourceNumber":"311260","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Não existem evidências de que o uso de bicarbonato de sódio influencie os desfechos\nnesses pacientes. Sendo adequado:","options":{"A":"O uso de bicarbonato de sódio não é recomendado para pacientes com hipoperfusão e\nhiperlactatemia visando reduzir a dose de vasopressor quando o pH estiver acima de 7.2.","B":"O uso de bicarbonato de sódio é recomendado para pacientes com hipoperfusão e\nhiperlactatemia visando reduzir a dose de vasopressor quando o pH estiver acima de 7.2.","C":"O uso de bicarbonato de sódio não é recomendado para pacientes com hipoperfusão e\nhipolactatemia visando reduzir a dose de vasopressor quando o pH estiver acima de 7.2.","D":"O uso de bicarbonato de sódio não é recomendado para pacientes com hipoperfusão e\nhiperlactatemia visando aumentar a dose de vasopressor quando o pH estiver acima de 7.2."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-301020","number":"301020","sourceNumber":"301020","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Assinale a alternativa que apresenta uma opção eficaz para o tratamento da\nneurotoxoplasmose.","options":{"A":"Sulfametoxazol-trimetoprima.","B":"Ganciclovir.","C":"Albendazol.","D":"Praziquantel."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-311300","number":"311300","sourceNumber":"311300","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quando uma pessoa/casal chega ao serviço de saúde em busca de anticoncepção,\noferece-se várias opções como por exemplo:\nanticoncepcional oral, DIU com cobre,\nanticoncepcional injetável, vasectomia, etc. Sendo assim, assinale a alternativa correta.","options":{"A":"Métodos com menor eficácia não podem ser utilizados pelas pessoas/casais como preservativos\ne tabelinha. Portanto, a pessoa/casal não é que\nidentifica o melhor método que se enquadra à sua\nrotina com auxílio do profissional de saúde.","B":"Até métodos com menor eficácia podem ser utilizados pelas pessoas/casais a depender de sua\nindicação como preservativos e tabelinha. Portanto, a pessoa/casal não é que identifica o melhor\nmétodo que se enquadra à sua rotina com auxílio do profissional de saúde.","C":"Até métodos com menor eficácia podem ser utilizados pelas pessoas/casais a depender de sua\nindicação como preservativos e tabelinha. Portanto, a pessoa/casal é que identifica o melhor\nmétodo que se enquadra à sua rotina com auxílio do profissional de saúde.","D":"Até os métodos com menor eficácia podem ser utilizados pelas pessoas/casais a depender de\nsua indicação como preservativos e tabelinha.\nPortanto, a pessoa/casal é que identifica o melhor\nmétodo que não se enquadra à sua rotina e sem auxílio do profissional de saúde."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-311305","number":"311305","sourceNumber":"311305","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Desde o início da década de 1980 até junho de 2012, foram notificados ao Ministério da\nSaúde 686.478 casos de AIDS no Brasil. Desse\ntotal, 379.045 (55,2%) são da região Sudeste.\n\nPodemos indicar que:","options":{"A":"Mais recentemente, pode ser observada a disseminação da epidemia para outras regiões do\nPaís e para as cidades de pequeno porte\napenas. Nos últimos anos, o perfil epidemiológico de HIV\nno Brasil vem apresentando modificações importantes.","B":"Mais recentemente, pode ser observada a disseminação da epidemia para outras regiões do\nPaís e para as cidades de médio e de\npequeno porte. Nos últimos anos, o perfil epidemiológico de\nHIV no Brasil vem apresentando modificações importantes.","C":"Mais recentemente, pode ser observada a disseminação da epidemia para outras regiões do\nPaís e para as cidades de médio e de\npequeno porte. Nos últimos anos, o perfil epidemiológico de\nHIV no Brasil não vem apresentando modificações importantes.","D":"Mais recentemente, pode ser observada a redução da epidemia para outras regiões do País e\npara as cidades de médio e de pequeno porte. Nos últimos anos, o perfil epidemiológico de HIV no\nBrasil vem apresentando modificações importantes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-287616","number":"287616","sourceNumber":"287616","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Ocorrem interações observadas entre os medicamentos para o tratamento da Hepatite\nC e a TARV. Podemos indicar como correto\nque:","options":{"A":"Eventualmente, serão necessários ajustes posológicos ou substituições medicamentosas a fim\nde se evitarem essas interações indesejáveis.","B":"Nunca serão necessários ajustes posológicos ou substituições medicamentosas a fim de se\nevitarem essas interações indesejáveis.","C":"Eventualmente, serão necessários ajustes posológicos, mas nunca substituições\nmedicamentosas a fim de se evitarem essas\n\ninterações indesejáveis.","D":"São proibidos ajustes posológicos ou substituições medicamentosas a fim de se evitarem essas\ninterações indesejáveis."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-266581","number":"266581","sourceNumber":"266581","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 35 anos vai ao Pronto-Socorro queixando-se de tosse seca e dispneia há 18\ndias, de curso insidioso e piora progressiva. Apresentou alguns episódios de febre (38,3°C) no\nperíodo. Nega ortopneia, dispneia paroxística noturna, chieira torácica ou sintomas de vias aéreas\nsuperiores. Fez uso de levofloxacino por 7 dias, porém não obteve melhora. É portador de SIDA,\nem uso irregular dos antirretrovirais. Ao exame físico, PA: 110X66mmHg, FC: 76bpm, FR: 28ipm,\nSpO 2 83% ( em ar ambiente). O exame respiratório revela o uso da musculatura acessória da\nrespiração, e a ausculta não apresenta anormalidades. O restante do exame físico está normal.\n\nExames de laboratório: Hb: 10,2g/dL; LG:6.200/mm ³; NS: 4.270/mm ³; Plq: 154.000/mm ³; LDH:\n960UI/L (VR:120-246UI/L); PCR: 32mg/L; Bilirrubina total: 1,0mg/dL; Creat.:1,3mg/dL; CD4:\n156/mm ³; Tomografia computadorizada do tórax conforme imagem a seguir: Considerando a\nprincipal hipótese diagnóstica, assinale a alternativa que apresenta o tratamento empírico MAIS\nADEQUADO para esse paciente:","options":{"A":"Azitromicina e dexametasona.","B":"Piperacilina e tazobactam.","C":"Rifampicina, isoniazida, pirazinamida e etambutol.","D":"Sulfametoxazol-trimetoprima e prednisona."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-266582","number":"266582","sourceNumber":"266582","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem de 35 anos vai ao Pronto-Socorro queixando-se de tosse seca e dispneia há 18\ndias, de curso insidioso e piora progressiva. Apresentou alguns episódios de febre (38,3°C) no\nperíodo. Nega ortopneia, dispneia paroxística noturna, chieira torácica ou sintomas de vias aéreas\nsuperiores. Fez uso de levofloxacino por 7 dias, porém não obteve melhora. É portador de SIDA,\nem uso irregular dos antirretrovirais. Ao exame físico, PA: 110 X 66 mmHg, FC: 76 bpm, FR: 28\nipm, SpO2 83% (em ar ambiente). O exame respiratório revela o uso da musculatura acessória da\nrespiração, e a ausculta não apresenta anormalidades. O restante do exame físico está normal.\n\nExames de laboratório: Hb: 10,2 g/dL; LG:6.200/mm³; NS: 4.270/mm³; Plq: 154.000/mm³; LDH: 960\nUI/L (VR:120-246 UI/L); PCR: 32 mg/L; Bilirrubina total: 1,0 mg/dL; Creat.:1,3 mg/dL; CD4:\n156/mm³; Tomografia computadorizada do tórax conforme imagem a seguir: Assinale a alternativa\nque apresenta um diagnóstico diferencial MAIS PROVÁVEL para o quadro pulmonar apresentado\npor esse paciente:","options":{"A":"Citomegalovirose.","B":"Histoplasmose pulmonar.","C":"Infecção pelo complexo Mycobacterium avium.","D":"Sarcoma de Kaposi."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-259415","number":"259415","sourceNumber":"259415","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A transmissão do vírus da hepatite B (VHB), após exposição a sangue ou líquidos\ncorporais em hospitais, representa um risco\nimportante para o profissional de saúde, variando de\n6% a 30%, a depender da natureza dessas exposições. Em relação à vacinação do profissional de\nsaúde e à profilaxia após exposição, é INCORRETO afirmar:","options":{"A":"Em caso de sorologia (anti-AgHBs) negativa, 6 meses ou mais após a terceira dose do primeiro\nesquema vacinal, deve-se administrar 1 dose vacinal e repetir a sorologia 1 mês depois. Caso\npersista negativa, não indicar nova vacinação (suscetível não respondedor).","B":"Recomenda-se a sorologia um a dois meses após a última dose do esquema vacinal, para\nverificar se houve resposta satisfatória à\nvacina (anti-AgHBs >10 UI/L), para todos os profissionais\nde saúde.","C":"Se o profissional de saúde vítima de acidente biológico de paciente fonte AgHBs positivo tiver a\nresposta vacinal desconhecida, deve-se dosar o anti-AgHBs e administrar imunoglobulina\nhiperimune para hepatite B, juntamente com uma dose de vacina, a depender da resposta vacinal.","D":"Indivíduos com vacinação incompleta com exposição ocupacional a material biológico,\nconsiderar imunoglobulina hiperimune para hepatite B,\njuntamente com complementação do\nesquema vacinal, apenas se o paciente-fonte for AgHBS positivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-278878","number":"278878","sourceNumber":"278878","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A abordagem Profilaxia Pré-Exposição (PrEP) de Risco à Infecção pelo HIV reconhece\nque as escolhas são feitas considerando\ndiferentes pertencimentos culturais, inserções\ncomunitárias e histórias de vida, que influenciarão nos modos como os métodos de prevenção são\nadotados ao longo da vida. Assim, podemos concordar com o item:","options":{"A":"A partir do conhecimento das alternativas de prevenção, não se deve conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, conforme suas práticas sexuais.","B":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, independentemente de suas práticas\nsexuais.","C":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, conforme suas práticas sexuais.","D":"A partir do conhecimento das alternativas de prevenção, deve-se conversar com o indivíduo\nsobre a possibilidade de realizar o\ngerenciamento de risco, proibindo suas práticas sexuais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-287655","number":"287655","sourceNumber":"287655","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A atenção se deve a exposição a pessoas com TB, aumentando o risco de\ndesenvolvimento da doença ativa, sendo correto o item:","options":{"A":"Para as pessoas vivendo com HIV PVHIV, o foco especial não se deve ao risco aumentado de\ndesenvolvimento de doença ativa, devido à resposta imunológica menos eficaz.","B":"Para as pessoas vivendo com HIV PVHIV, o foco especial se deve ao risco reduzido de\ndesenvolvimento de doença ativa, devido à resposta imunológica menos eficaz.","C":"Para as pessoas vivendo com HIV PVHIV, o foco especial se deve ao risco aumentado de\ndesenvolvimento de doença ativa, devido à resposta imunológica mais eficaz.","D":"Para as pessoas vivendo com HIV PVHIV, o foco especial se deve ao risco aumentado de\ndesenvolvimento de doença ativa, devido à resposta imunológica menos eficaz."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-287658","number":"287658","sourceNumber":"287658","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O termo Prevenção Combinada do HIV refere-se às diferentes ações de prevenção,\nsendo correto e adequado que:","options":{"A":"Somente as diretamente voltadas ao combate do HIV, não fatores associados à infecção.","B":"Tanto as indiretamente voltadas ao combate do HIV quanto aos fatores não associados à\ninfecção.","C":"Tanto as diretamente voltadas ao combate do HIV quanto aos fatores não associados à\ninfecção.","D":"Tanto as diretamente voltadas ao combate do HIV quanto aos fatores associados à infecção."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-266639","number":"266639","sourceNumber":"266639","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A expansão da pandemia de AIDS exige que todos os profissionais e serviços de saúde\nestejam preparados para diagnosticar e tratar a doença. Sobre essa temática, assinale a alternativa\nINCORRETA:","options":{"A":"A mãe HIV positiva não pode amamentar.","B":"Linfadenopatia, hepatoesplenomegalia persistente e febre de origem indeterminada são\nsintomas de A.I.D.S.","C":"Não existe protocolo para prevenção de transmissão vertical da mãe HIV positiva para o\nneonato. O tratamento é iniciado após confirmação da patologia na criança.","D":"A sorologia pode ser positiva por até 18 meses por anticorpos maternos no filho de mãe HIV\npositiva."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-254622","number":"254622","sourceNumber":"254622","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Qual a duração da profilaxia do AZT?","options":{"A":"48 horas","B":"96 horas","C":"4 semanas","D":"30 semanas"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-219422","number":"219422","sourceNumber":"219422","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre a transmissão vertical do HIV podemos afirmar:","options":{"A":"O uso de AZT venoso na parturiente antecedendo ao parto só é indicada em caso de cargas\nvirais elevadas no último trimestre de gestação","B":"Medidas preventivas adotadas antes, durante e após o parto não reduzem de forma significativa\nos índices de transmissão","C":"A suspensão do aleitamento materno não deverá ser recomendada em virtudes dos amplos\nbenefícios do LM e dos baixos riscos de transmissão do HIV pelo mesmo.","D":"Deverá ser iniciada, preferencialmente nas primeiras horas de vida, uso de AZT e, em alguns\ncasos, também de nevirapina orais pelo RN como forma de prevenção"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-219447","number":"219447","sourceNumber":"219447","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação às Imunodeficiência Primárias da Infância, após associar as colunas,\nassinale a sequência correta: I ? Deficiência de IGA; II ? Deficiência de complemento; III ?\n\nDeficiência Celulares; IV ? Deficiências de fagócitos; A- Infecções graves por germes capsulados\ncomo Neisserias; B- Giardíase e Infecções\nrespiratórias recorrentes; C- Infecções cutâneas como\npiodermites e abscessos recorrentes; D- Reações severas a BCG e infecções graves por\npatógenos intracelulares","options":{"A":"I-B , II-C , III-A , IV-D","B":"I-C , II-A , III-D , IV-B","C":"I-C , II-B , III-A , IV-D","D":"I-B , II-A , III-D , IV-C"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-211994","number":"211994","sourceNumber":"211994","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Determinamos como fatores que dificultam a adesão de tratamento os listados abaixo,\nqual se mostra INADEQUADO.","options":{"A":"Complexidade do esquema terapêutico (diferentes drogas, quantidade de doses).","B":"Aceitação do soro positividade.","C":"Faixa etária do paciente (criança, adolescente e idoso).","D":"Baixa escolaridade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-211992","number":"211992","sourceNumber":"211992","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Precariedade ou ausência de suporte social/exclusão social, efeitos colaterais do\nmedicamento e a relação insatisfatória do usuário com o profissional de saúde e os serviços\nprestados são elementos que dificultam a adesão. Qual dos itens abaixos NÃO faz parte do\nconceito?","options":{"A":"Crenças negativas e informações inadequadas em relação ao tratamento e à doença.","B":"Adequação da rotina diária do tratamento.","C":"Abuso de álcool e outras drogas.","D":"Dificuldade de acesso ao serviço."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-219417","number":"219417","sourceNumber":"219417","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente atendido na unidade da Estratégia de Saúde da Família devido à preocupação\ncom exposição à doenças sexualmente\ntransmissíveis. Após aconselhamento pré-teste, foram\nrealizados testes rápidos para diagnóstico de Sífilis, hepatite B, hepatite C e HIV 1 e 2,\ndisponíveis\nna unidade de saúde, tendo obtido o resultado em menos de trinta minutos. O método que\npossibilita a realização dos exames de forma rápida, econômica, de fácil interpretação, com\nsensibilidade e especificidade similar aos métodos clássicos e de grande valor em situações\nambulatoriais nas quais os profissionais de saúde necessitem tomar decisões e assumir condutas\nmais rápidas, utiliza a técnica de:","options":{"A":"Ensaio de imunoabsorção enzimática (ELISA).","B":"Imunocromatografia.","C":"Quimioluminescência.","D":"Eletroquimioluminescência (ECLIA)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-203883","number":"203883","sourceNumber":"203883","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os profissionais de saúde que desempenham suas atividades na área assistencial\nestão expostos frequentemente a possíveis\ninfecções de origem ocupacional. Em relação aos\nacidentes de trabalho com risco de contaminação com material biológico, é INCORRETO afirmar\nque:","options":{"A":"Todos os acidentes de trabalho em que haja risco de exposição a material biológico são de\nnotificação compulsória.","B":"A empresa é obrigada a emitir a Comunicação de Acidente de Trabalho (CAT) para todos os\nacidentes de trabalho ocorridos com seus empregados, mesmo que não haja afastamento das\natividades, até o primeiro dia útil seguinte ao da ocorrência.","C":"A Profilaxia Pós-Exposição (PPE) ao HIV somente está indicada se a fonte for conhecida e\napresentar sorologia positiva para o vírus da AIDS.","D":"O uso de óculos, como Equipamento de Proteção Individual (EPI), é obrigatório para todos os\nprocedimentos em que haja o risco de projeção de fluidos corpóreos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-217192","number":"217192","sourceNumber":"217192","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A janela imunológica para detecção de anticorpos anti-HIV no sangue periférico é:","options":{"A":"1 a 2 semanas.","B":"3 a 12 semanas.","C":"15 a 18 semanas.","D":"Acima de 18 semanas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-177992","number":"177992","sourceNumber":"177992","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Considerando os benefícios e os efeitos colaterais relacionados ao uso de terapia\nantirretroviral, as recomendações atuais para a grande maioria dos pacientes são de que seja\niniciada:","options":{"A":"Quando a infecção pelo HIV for confirmada","B":"Somente em pacientes com diagnóstico de SIDA","C":"Somente quando a contagem de CD4 for menor que 200céls/microL","D":"Somente na presença de infecções repetidas, em qualquer sítio"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-179308","number":"179308","sourceNumber":"179308","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O acometimento neurológico sintomático acontece em cerca de 40% a 60% dos\nindivíduos infectados pelo HIV em algum momento da doença, sendo o sistema nervoso um\nimportante sítio de morbidade e mortalidade. Sobre as doenças neurológicas em pacientes\ninfectados pelo HIV, assinale a alternativa INCORRETA.","options":{"A":"A encefalopatia pelo HIV, embora incomum, caracteriza-se por uma evolução aguda marcada\npor febre e aumento na celularidade do liquor\nem mais de 90% dos casos.","B":"A neurotoxoplasmose é a principal causa de lesão com efeito de massa no SNC, representando\ncerca\n\nde 50% a 70% dos casos.","C":"O linfoma primário é a neoplasia mais frequente no SNC em pacientes com HIV/SIDA, estando\nassociado à infecção pelo vírus Epstein-Barr (EBV).","D":"O Cryptococcus neoformans é o principal agente oportunista, causador de meningite no paciente\ncom SIDA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-178038","number":"178038","sourceNumber":"178038","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O conceito de ADJUVANTE é:","options":{"A":"Anticorpos protetores que inativam proteínas solúveis.","B":"Substância tipo antigênica que produz hipersensibilidade imediata e capaz de provocar reação\nalérgica.","C":"Glicoproteína sintética capaz de se ligar a imunoglobulina das bactérias e atuar como\ntoxina.","D":"Produto capaz de melhorar a resposta imunológica e conferir proteção de maior duração aos\nimunobiológicos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-181966","number":"181966","sourceNumber":"181966","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente de 34 anos, com entrada em pronto-socorro às 22h30min, com histórico de ter\nsofrido estupro que ocorreu há 6 horas. Pensando em profilaxia do HIV, a medicação CORRETA a\nser prescrita será:","options":{"A":"Zidovudina + ciprofloxacina + ceftriaxona.","B":"Tenofovir + lamivudina.","C":"Lopinavir + ritonavir.","D":"Tenofovir + lamivudina + dolutegravir."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-179275","number":"179275","sourceNumber":"179275","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Marcelo, criança de um ano e oito meses, comprovadamente infectada pelo vírus HIV\n(transmissão vertical durante o parto), é trazido por sua avó para consulta de acompanhamento\nclínico. Em relação ao tratamento e acompanhamento dessa criança, é CORRETO afirmar que:","options":{"A":"Se apresentar infecções do trato respiratório recorrentes deve-se, obrigatoriamente, iniciar\nesquema quádruplo de tratamento para HIV.","B":"Os seguintes exames laboratoriais devem ser realizados anualmente: hemograma completo,\ncontagem de linfócitos T CD4 e T CD8 e quantificação do RNA viral (carga viral).","C":"O tratamento antirretroviral, quando indicado seu início, visa preservar, melhorar ou\nreconstituir o\nfuncionamento do sistema imunológico, reduzindo a ocorrência de infecções oportunistas.","D":"O AZT xarope profilático na dose de 1mg/kg, de 6/6 horas, deve estar sendo usado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-153132","number":"153132","sourceNumber":"153132","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação à coinfecção HIV/Tuberculose pulmonar (TBP), assinale a alternativa\ncorreta:","options":{"A":"Deve-se iniciar tratamento simultâneo das duas condições. Optar por esquema antirretroviral\nsem inibidores de protease.","B":"Deve-se realizar o tratamento antirretroviral (TARV) inicialmente. A atividade da Tuberculose\nPulmonar tende a recrudescer após o início da TARV.","C":"Iniciar a TARV após o térmico do tratamenmto para TBP; a interação das drogas utilizadas\napresenta efeitos colaterais proibitivos para a associação dos esquemas..","D":"Iniciar a TARV após 30 dias do início da poliquimioterapia para tratamento da Tuberculose\nPulmonar. Esta, quando em atividade, está\nassociada diretamente à diminuição dos linfócitos CD","E":"Se o paciente apresentar linfócitos CD4 maiores que 500/mm3, apenas realizar tratamento para\ntuberculose pulmonar. Não há indicação para TARV nesta situação solicitar tomografia\ncomputadorizada de crânio."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-153069","number":"153069","sourceNumber":"153069","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os risco de transmissão vertical do HIV, em nosso meio, persiste. Por conseguinte em\ncrianças pré-escolares e escolares que apresentam condições clínicas recorrentes ou persistentes -\nexemplo: monilíase oral persistente -, o diagnóstico de AIDS deve ser considerado. Das condições\nabaixo, a mais indicativa dessa enfermidade é:","options":{"A":"Febre de origem indetarminada (FOI).","B":"Hepatoesplenomegalia.","C":"Infecções recorrentes de vias aéreas superiores.","D":"Linfonodomegalia generalizada.","E":"Paratodite de repetição crônica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-157961","number":"157961","sourceNumber":"157961","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Segundo o consenso sobre terapia antirretrovial para crianças infectadas pelo hiv -\n2002/2003, na escolha do regime antirretrovial, não está considerado entre os principais fatores\nque influenciam na adesão:","options":{"A":"Disponibilidade e palatabilidade de formulação.","B":"Impacto do esquema terapêutico na qualidade de vida, incluindo número de medicamentos,\nfrequência de administração e necessidade de\ningestão com ou sem alimentos.","C":"Potencial de interação com outras drogas e efeitos colaterais.","D":"Custo do tratamento combinado com duas ou mais drogas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-159485","number":"159485","sourceNumber":"159485","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Infecções de repetição na infância são uma queixa comum na rotina de atendimento\npediátrico, especialmente em crianças no período\npré-escolar. Sobre as infecções de repetição na\ninfância afirma-se: I. Quatro ou mais episódios de otite média, em um ano, ganho ponderal\ninadequado, presença de abscessos, úlceras orais ou monilíase persistente, são sugestivas de\nimunodeficiências primárias.; II. Aproximadamente 50% das crianças com infecções recorrentes\napresentam uma doença de base como causa significativa para as infecções de repetição.; III.\nDurante a anamnese, é importante detalhar a história familiar para se investigar a possibilidade de\ndoença genética.; IV. Crianças atópicas, geralmente, apresentam curva de crescimento com padrão\nde retardo constitucional no desenvolvimento puberal, independentemente da gravidade dos\nsintomas da doença alérgica de base. Estão CORRETAS as afirmativas.","options":{"A":"I, III e IV apenas.","B":"II, III e IV apenas.","C":"II e III apenas.","D":"I e III apenas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131706","number":"131706","sourceNumber":"131706","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Aline, 28 anos, foi admitida no hospital com pielonefrite aguda e tratada com\nCiprofloxacina oral. Após três dias de\nterapia, ela retorna ao hospital apresentando febre\npersistente de 38,9°C e dor em flancos. A cultura de urina revelou 100.000 unidades formadoras de\ncolônia de E. coli por ml, com sensibilidade à Ciprofloxacina. Durante o exame, você constata\ntaquicardia, taquipnéia e letargia. Qual será a próxima etapa da avaliação e abordagem? Assinale a\nalternativa correta:","options":{"A":"Solicitar hemocultura e ampliar o espectro de antimicrobianos.","B":"Avaliação cirúrgica para analisar a possibilidade de apendicite.","C":"Acrescentar uma terapia fúngica.","D":"Obter acesso venoso e administrar líquidos.","E":"Iniciar a infusão de Noradrenalina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-129540","number":"129540","sourceNumber":"129540","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Com relação à endocardite infecciosa, é CORRETO afirmar:","options":{"A":"Streptococcus gallolyticus é germe do trato gastrointestinal e, portanto, na presença de\nendocardite por esse germe, deve-se pesquisar a presença de tumor de cólon.","B":"Vários estudos comprovam o benefício da profilaxia antibiótica, sendo assim, é mandatório o uso\nde amoxicilina uma hora antes de extração\n\ndentária em um paciente com insuficiência mitral moderada de valva nativa.","C":"Constituem critérios maiores de Duke para o diagnóstico endocardite infecciosa: hemocultura\npositiva, vegetação ao ecocardiograma e febre.","D":"São germes que mais comumente causam endocardite de valva nativa: estreptococos,\nenterococos e Klebsiella sp."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-129241","number":"129241","sourceNumber":"129241","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Você trabalha em uma clínica que tem serviço de odontologia e endoscopia. Certo dia,\no dentista e o endoscopista solicitaram uma interconsulta pré-procedimento odontológico de\nlimpeza simples dos dentes e de endoscopia por quadro de disfagia devido a paciente ter relatado\nque já teve endocardite bacteriana no passado e leu na internet que se deve usar antibiótico para\nprevenir a recorrência. A paciente, além desse passado mórbido, não apresentava nenhuma outra\ncomorbidade. Os colegas aguardam sua resposta para definir se farão ou não a\nantibioticoprofilaxia. Dessa forma, escolha a alternativa que apresenta a MELHOR resposta para\ndar ao paciente e aos colegas:","options":{"A":"A antibioticoprofilaxia deve ser feita nesse caso, pois se trata de paciente de alto risco para\nrecorrência\n\ne que será submetida a procedimento odontológico de risco.","B":"A antibioticoprofilaxia não deve ser feita nesse caso, porque apesar da paciente ser do grupo de\nalto\n\nrisco de recorrência, ela não será submetida a procedimentos de risco.","C":"A antibioticoprofilaxia não deve ser feita nesse caso, porque somente pacientes com disfunção\nvalvar grave ou com prótese valvar são de alto\nrisco para recorrência e se beneficiam da profilaxia.","D":"A antibioticoprofilaxia deve ser feita nesse caso, devido a paciente ser de alto risco e\nnecessitar\nfazer a endoscopia digestiva."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131802","number":"131802","sourceNumber":"131802","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Você recepciona um recém-nascido (Joaquim) em centro obstétrico, filho de mãe\ninfectada pelo HIV. A criança nasce a termo, com peso de nascimento igual a 2.850 g. Todas as\nalternativas abaixo representam condutas corretas no manuseio desta criança, EXCETO:","options":{"A":"Limpar com compressas todo sangue e secreções visíveis no recém-nascido imediatamente\napós o nascimento e proceder com banho, ainda na\nsala de parto.","B":"Aspirar vias aéreas do recém-nascido com cuidado, evitando traumatismos em mucosas.","C":"Iniciar a primeira dose do AZT solução oral após 48 horas do nascimento.","D":"Acrescentar nevirapina ao esquema da profilaxia nas mães que não receberam ARV no\n\npré-natal ou não têm carga viral menor que 1.000 cópias/mililitro no último trimestre de gestação.","E":"Substituição do leite materno por fórmula infantil."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-135643","number":"135643","sourceNumber":"135643","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Mulher de 26 anos de idade procura uma Unidade de pronto Atendimento (UPA) com\nqueixa de disúria, polaciúria, urgência miccional e dor abdominal suprapúbica há 48 horas. Nega\nepisódios anteriores. Não apresenta comorbidades. O EAS mostra nitrito positivo, piúria maior que\n20000 piócitos por campo e cilindros leucocitários positivos. Dentre as opções abaixo, qual inclui\nmelhor opção de antibioticoterapia neste caso?","options":{"A":"Ciprofloxacino.","B":"Imipenem.","C":"Vancomicina.","D":"Piperacilia/tazobactam."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-136703","number":"136703","sourceNumber":"136703","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"São exemplos de antibióticos que agem como inibidores da síntese da parede celular:","options":{"A":"Bacitracina e vancomincina.","B":"Polimixina e ionoforos.","C":"Quinolonas e rifampicina.","D":"Estreptomicina e cloranfenicol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-129285","number":"129285","sourceNumber":"129285","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Criança de 1 ano de idade é internada por apresentar há 3 dias quadro de secreção\nocular amarelada, bilateral, febre e exantema\ngeneralizado, eritematoso. Após 1 a 2 dias do\nsurgimento do exantema, apareceram bolhas e a epiderme se desprende em lâminas grandes,\nrevelando embaixo uma superfície úmida, vermelha e brilhante. Considerando o caso descrito,\nassinale a alternativa que apresenta a MELHOR conduta a ser adotada:","options":{"A":"Iniciar imunoglobulina humana.","B":"Iniciar imunoglobulina + Ácido Acetilsalicílico (AAS).","C":"Iniciar imunoglobulina + metilprednisolona.","D":"Iniciar oxacilina ou cefalosporina de primeira geração."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-136692","number":"136692","sourceNumber":"136692","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma bactéria (sp) pode ser tornar resistente à cefalosporina por alterações\nbioquímicas, como:","options":{"A":"Transformação da substância ativa em \"inativa\" por ação de enzimas produzidas por formas\nresistentes do microorganismo.","B":"Alteração do sítio-alvo da droga no agente bacteriano.","C":"Perda da permeabilidade celular à droga.","D":"Elevação das concentrações de metabólito que antagonize a droga inibidora."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-131783","number":"131783","sourceNumber":"131783","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Soraia, técnica de enfermagem da UBSF (Unidade Básica de Saúde da Família) em\nque você trabalha, pede orientação sobre os\nriscos para infecção por HIV de acordo com o contato\ncom diferentes fluidos do paciente. Qual material biológico abaixo é potencialmente não infectante\npara HIV?","options":{"A":"Escarro.","B":"Sêmen.","C":"Líquido pleural.","D":"Liquor.","E":"Sangue."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-108054","number":"108054","sourceNumber":"108054","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Quanto às quinolonas, podemos afirmar:","options":{"A":"São mal absorvidas por via oral, exceto a norfloxacina.","B":"Têm meia-vida reduzida em idosos.","C":"As quinolonas são antimicrobianos estruturalmente antagônicos ao ácido nalidíxico.","D":"São antimicrobianos bactericidas que interferem na síntese do DNA Bacteriano.","E":"Não devem ser utilizada em qualquer tipo de infecção por Gram-positivos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-120753","number":"120753","sourceNumber":"120753","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Gestante com idade gestacional de 21 semanas de acordo com ultrassom de 1º\ntrimestre, chega ao pronto atendimento\nqueixando-se de disúria, urina escurecida e com odor mais\nforte há 3 dias. Ao exame físico, evidencia-se: frequência cardíaca materna = 107 bpm; PA = 120 x\n80 mmHg; frequência fetal = 164 bpm; altura uterina = 20 cm; punho-percussão (sinal de Giordano)\npositivo à direita. Temperatura axilar = 39ºC. Qual a principal hipótese diagnóstica e qual seria a\nconduta mais apropriada?","options":{"A":"Infecção do trato urinário inferior. Deve-se internar a gestante com curva térmica, solicitar\nurocultura e iniciar antibiótico de largo espectro.","B":"Pielonefrite aguda. Deve-se solicitar exames laboratoriais, como hemograma e urocultura e\niniciar antibiótico, como as cefalosporinas, em regime hospitalar.","C":"Apendicite. Deve-se encaminhar a gestante para intervenção cirúrgica.","D":"Pielonefrite aguda. Deve-se avaliar ambulatorialmente a paciente, com curva térmica e, caso a\nfebre persista, introduzir antibioticoterapia.","E":"Infecção do trato urinário inferior. Deve-se avaliar ambulatorialmente a paciente, com\nantibioticoterapia via oral e curva térmica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-109903","number":"109903","sourceNumber":"109903","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Dentre os grupos de bactérias relacionadas a seguir, qual alternativa reflete a etiologia\nmais provável de meningite bacteriana no\nrecém-nascido?","options":{"A":"Streptococcus de grupo B, bacilos entéricos Gram-negativos, Listeria monocytogenes.","B":"Staphylococcus aureus, bacilos entéricos Gram-negativos, Neisseria meningitidis.","C":"H. influenzae, S. pneumoniae, bacilos entéricos Gram-negativos.","D":"Pseudomonas aeruginosa, Staphylococcus epidermidis, Listeria monocytogenes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-103754","number":"103754","sourceNumber":"103754","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Em relação à resistência antimicrobiana, é CORRETO afirmar que deve-se:","options":{"A":"Revisar frequentemente a lista de antimicrobianos essenciais, com base em dados de\nespecificidade.","B":"Desenvolver e distribuir recomendações que prolonguem a vida útil de antibióticos.","C":"Reduzir o acesso a antimicrobianos, exceto daqueles utilizados em medicina veterinária.","D":"Estimular o uso dos antibióticos genéricos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-120782","number":"120782","sourceNumber":"120782","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Uma moça de 17 anos vem à consulta com quadro de polaciúria intensa, disúria e\neliminação de urina opaca há dois dias. Refere que nunca apresentou quadro semelhante. Nega\nfebre, calafrios, dor lombar ou outros sintomas urinários. Ao exame físico apresenta somente dor a\npalpação da região infraumbilical. Diante da presente sintomatologia e na tentativa de se\nidentificar\nalgum fator desencadeante dos sintomas, é importante se questionar sobre:","options":{"A":"História pregressa de doenças próprias da\ninfância;","B":"História familiar de infecções urinárias;","C":"História familiar de doença renal crônica;","D":"História da atividade sexual da paciente;","E":"História de hipertensão ou diabete nos pais."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-120781","number":"120781","sourceNumber":"120781","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Havendo a suspeita de que a doença desta paciente seja de origem infecciosa:","options":{"A":"É provável que exista alguma anomalia de trato urinário na paciente;","B":"Há grande possibilidade da infecção ser\nocasionada pela bactéria Escherichia coli;","C":"Há necessidade de se esperar o resultado de\nexames culturais para iniciar o tratamento\nespecífico;","D":"É importante ser feita uma investigação com imagem da paciente (ultra-sonografia, raios-X ou\ntomografia computadorizada);","E":"Provavelmente a infecção seja a primeira manifestação de um quadro de diabete subclínico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-58998","number":"58998","sourceNumber":"58998","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Recém-nascido, no terceiro dia de vida, evoluiu com hipoatividade, vômitos e\nabaulamento de fontanela anterior. Dá entrada em pronto-socorro onde, após propedêutica, se\nchegou ao diagnóstico de meningite neonatal. Assinale o esquema de antibiótico que deve ser\niniciado para o recém-nascido em questão.","options":{"A":"Ampicilina + gentamicina.","B":"Cefotaxima + Ampicilina.","C":"Ceftriaxone.","D":"Ampicilina + Cloranfenicol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-59008","number":"59008","sourceNumber":"59008","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Criança de sete anos, com quadro de quatro dias com febre baixa, cefaleia, vômitos,\nevolui com sonolência e crises convulsivas,\ndando entrada em pronto-socorro já sem convulsão,\nporém com rebaixamento de consciência e hemiparesia à direita, ausência de sinais meníngeos\n(Brudzinski e Kernig negativos). (VER IMAGEM) Optou-se por realização de ressonância magnética\nde encéfalo que mostrou hipersinal nas sequências T2 e FLAIR ao nível da região medial temporal\n(córtex insular e giro reto) esquerda. Frente ao quadro descrito, qual a melhor conduta?","options":{"A":"Iniciar aciclovir imediatamente.","B":"Iniciar ceftriaxone.","C":"Pulsoterapia com metilprednisolona.","D":"Sintomáticos até sair o resultado do PCR para Herpes I e II, caso positivo iniciar então o\nAciclovir."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-44532","number":"44532","sourceNumber":"44532","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"J.V.A., 22 anos, com história de dor lombar intensa à direita, iniciada há 3 dias,\nassociada à algúria e piúria. Teve febre de\n39°C. Chegou ao PA com os seguintes dados vitais:\npressão arterial: 90 x 60; frequência cardíaca: 98 bpm; frequência respiratória: 24 irpm;\ntemperatura\naxilar: 34,5°C. Estava descorada, desidratada, acianótica. Havia dor à palpação do flanco direito.\n\nOs exames complementares mostraram: global de leucócitos de 3.600, sem desvio; urinálise e\ngram de gota compatíveis, com infecção do\ntrato urinário; radiografia de tórax normal; lactato: 4,2\nmmol/L (referência: 0,5 a 2,2 mmol/L). Sobre esse caso clínico, marque a alternativa INCORRETA:","options":{"A":"Trata-se de um caso de sepse grave ou choque séptico, a ser definido pela resposta à\nressuscitação volêmica inicial.","B":"A incidência de hemoculturas positivas pode chegar a 45% em pacientes sépticos.","C":"Antimicrobianos só devem ser administrados, após a coleta de pelo menos duas hemoculturas e\numa urocultura.","D":"Prova volêmica é uma modalidade de restauração da volemia, que se baseia na infusão rápida\nde cristaloides seguida de avaliação da resposta."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-51415","number":"51415","sourceNumber":"51415","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Os antimicrobianos podem atuar de diversas maneiras. Marque a alternativa na qual\nTODOS INTERFEREM na membrana citoplasmática do microrganismo:","options":{"A":"Penicilina, fosfomicina, carbapenêmicos.","B":"Metronidazol, quinolona, aciclovir.","C":"Cefalosporinas, vancomicina, cloranfenicol.","D":"Polimixina B, anfotericina, fluconazol."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-44563","number":"44563","sourceNumber":"44563","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A profilaxia antibiótica, por via oral, para prevenção de endocardite em paciente que vai\nsubmeter-se à extração dentária deve ser feita com:","options":{"A":"Ampicilina.","B":"Amoxacilina.","C":"Ciprofloxacina.","D":"Sulfametoxazol + trimetoprin."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-44564","number":"44564","sourceNumber":"44564","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A profilaxia antibiótica para prevenção de endocardite bacteriana está indicada em\npacientes com:","options":{"A":"Desfibrilador implantável.","B":"Prolapso mitral com regurgitação.","C":"Revascularização do miocárdio.","D":"Defeito do septo atrial."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-44530","number":"44530","sourceNumber":"44530","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"No que se refere à infecção hospitalar da corrente sanguínea, assinale a opção\nINCORRETA.","options":{"A":"Os cateteres intravenosos são a fonte mais comum de infecção da corrente sanguínea.","B":"Quanto mais tempo o cateter é deixado no local, maior é a probabilidade de infecção.","C":"Os principais agentes associados às bacteremias de origens hospitalares são os Staphylococcus\ncoagulase-negativos e o Staphylococcus aureus.","D":"A contaminação intrínseca dos líquidos intravenosos pelo fabricante é um acontecimento\nfrequente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-33819","number":"33819","sourceNumber":"33819","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre a Endocardite Infecciosa (EI), marque a alternativa CORRETA:","options":{"A":"O ecocardiograma transesofágico possui alta sensibilidade (acima de 90%) para detecção de\nvegetações e é o ideal para estudar válvulas protéticas e complicações como abscessos, fístulas e\nperfurações.","B":"Segundo os critérios de Duke, bastam um critério maior, ou um maior e um menor, ou cinco\ncritérios menores para o diagnóstico de EI.","C":"Os aminoglicosídeos podem ser utilizados em dose única diária para tratamento de EI por\nenterococos.","D":"A única indicação de cirurgia cardíaca de emergência na EI é quando há ruptura para saco\npericárdico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-33463","number":"33463","sourceNumber":"33463","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente do sexo masculino, 39 anos, branco, foi admitido no hospital com quadro de\nfebre, prostração, hemorragias conjuntivais e\nnecrose em pododáctilos, sugestivas de embolia\narterial. O paciente se encontrava no 30º dia de pós-operatório de cirurgia de revascularização\nmiocárdica, iniciou o quadro atual há uma semana, apresentando também dispneia aos moderados\nesforços e edema de membros inferiores. Na admissão apresentava-se toxemiado, hipotenso,\nrefratário à expansão volêmica, taquicárdico, febril (> 38°C); o exame clínico mostrava turgência\njugular, sopro sistólico mitral, estertores crepitantes basais em ausculta pulmonar,\nhepatoesplenomegalia e edema de membros inferiores; foi transferido para a UTI com o diagnóstico\nde sepse de foco indeterminado. Evoluiu com confusão mental, agitação psicomotora, piora da\ntaquicardia e da hipotensão mesmo após início da noradrenalina. Houve redução do volume\nurinário, hematúria macroscópica e dispneia acentuada. O Ecodoppler transtorácico demonstrou\nvegetação oscilante em valva mitral. O mais provável diagnóstico, agente etiológico e tratamento\ninicial recomendado, pode ser considerado:","options":{"A":"Endocardite por streptococcus viridans ou bovis; penicilina G.","B":"Endocardite por doença valvular pré-existente por streptococcus viridans; ampicilina,\ngentamicina e oxacilina.","C":"Endocardite precoce relacionada à cirurgia prévia por staphylococcus aureus ou epidermidis;\nvancomicina e gentamicina.","D":"Endocardite tardia não relacionada à cirurgia prévia, por enterobactérias ou pseudomonas\naeruginosa; cefalosporina de 3ª ou 4ª geração."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-23200","number":"23200","sourceNumber":"23200","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Avalie as afirmativas a seguir: O diagnóstico do tétano é baseado totalmente em\nachados clínicos. · O diagnóstico de botulismo\ndeve ser considerado em paciente com paralisia\nsimétrica descendente, febre e status mental intacto. · O diagnóstico laboratorial de infecção\ngonocócica em homens é rapidamente obtido por coloração Gram de exsudato uretral encontrando\nmonococos ou diplococos Gram negativo intra-celular. · HELICOBACTER PYLORY é fator de risco\npara úlcera péptica, adenocarcinoma do estômago e linfoma MALT gástrico. · Quase todos os\nórgãos poderão ser acometidos por Blasto micose.","options":{"A":"Uma afirmativa é incorreta.","B":"Todas as afirmativas são corretas.","C":"Duas afirmativas são incorretas.","D":"Três afirmativas são incorretas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-26825","number":"26825","sourceNumber":"26825","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre infecções de trato urinário é incorreto dizer:","options":{"A":"Leucocitúria é comum em pacientes sondados.","B":"Pacientes sondados, mesmo que tenham uroculturas positivas com > 100.000 UFC/ml, só\ndeverão ser tratados se sintomáticos.","C":"Pode-se instituir tratamento sem exames adicionais em mulheres jovens que aprensentem\npolaciúria e disúria e não tenham lesões genitais.","D":"Triagem de bacteriúria assintomática em gestante deve ser feita com exame de urina rotina,\nsolicitando-se urocultura para casos selecionados.","E":"Norfloxacino não é considerado antibiótico adequado para tratamento de pielonefrite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-26826","number":"26826","sourceNumber":"26826","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Sobre infecções associadas a cateteres vasculares, assinale a alternativa incorreta:","options":{"A":"Cateteres não devem ser removidos rotineiramente na abordagem inicial de pacientes\nhemodinamicamente estáveis com febre sem causa aparente.","B":"A retirada do cateter venoso central é considerada indispensável para confirmação do\ndiagnóstico quando não há culturas quantitativas ou automatizadas","C":"Crescimento de > 15 UFC em cultura semiquantitativa em ponta de cateter não é diagnóstico se\nas hemoculturas periféricas forem negativas.","D":"Culturas qualitativas de sangue obtido através do cateter central só terão valor se negativas,\nquando ajudarão a excluir infecção.","E":"Sinais clínicos de infecção no local de punção devem sempre ser avaliados, e são considerados\nde alta sensibilidade para o diagnóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-369426","number":"369426","sourceNumber":"369426","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Homem, 40 anos, reporta em consulta ser bissexual e ter histórico de uso de\npreservativo masculino na maioria de suas relações. Refere desejo de iniciar PrEP (Profilaxia\nPré-Exposição de Risco à Infecção pelo HIV). Sobre essa estratégica de prevenção, é correto\nafirmar que:","options":{"A":"a Prep é uma associação de três fármacos antirretrovirais combinados na posologia de 1 (um)\ncomprimido diário, destinado a grupos com alto risco de infecção pelo HIV.","B":"dada o baixo potencial toxicidade renal da Prep, a sua prescrição está indicada para indivíduos\ncom clearance de creatinina acima de 15 mL/min.","C":"mulheres HIV negativas, com desejo de engravidar de parceiro soropositivo, não podem fazer\nuso de PrEP de forma segura, devido risco ao\nlongo da gravidez e amamentação.","D":"o esquema de prescrição \"\"sob demanda\"\" (PrEP intermitente) envolve tomar uma dose dupla\n(duas pílulas) entre 2 e 24 horas antes do\nsexo previsto e uma pílula 24 horas após a dose dupla e\noutra 48 horas depois (esquema 2 + 1 + 1).","E":"caso o indivíduo seja portador de infecção pelo vírus da hepatites B ou C, há uma\ncontraindicação formal para o uso de PrEP oral diária, pelo risco de toxicidade hepática."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-331192","number":"331192","sourceNumber":"331192","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Ao discutir o caso de um lactente com 60 dias de vida, admitido em unidade de terapia\nintensiva com sépsis secundária a abscesso cutâneo pós-picada de inseto, o preceptor questiona a\nseus residentes sobre os sinais de alerta para erro inato da imunidade em crianças. A resposta\ncorreta é","options":{"A":"duas ou mais otites por ano.","B":"quatro ou mais pneumonias por ano.","C":"candidíase oral em recém-nascidos.","D":"história de imunodeficiência na família.","E":"diarreia aguda."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-302534","number":"302534","sourceNumber":"302534","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"A infecção pelo vírus linfotrópico de células T de humanos (Human T lymphotropic\nvirus, HTLV) é prevalente em nosso meio, mas\na sua terapia não é bem estabelecida. O vírus pode\nseguir um curso completamente assintomático, contudo suas manifestações clínicas podem ser\nbastante variadas, incluindo manifestações dermatológicas, oculares, reumatológicas e\nneurológicas. Com relação a sua manifestação na forma de paraparesia espástica tropical, uma das\nmedicações indicadas nos protocolos terapêuticos é","options":{"A":"corticoide.","B":"belimumabe.","C":"tocilizumabe.","D":"abiraterona.","E":"brequinar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-277739","number":"277739","sourceNumber":"277739","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente, 30 anos, masculino, apresenta-se com diarreia há 30 dias, perda de peso de\n10 kg no mesmo período. Deu entrada no\nserviço de pronto atendimento devido à dispneia aos\nesforços, com tosse seca e febre que se iniciaram há cerca de duas semanas, porém que pioraram\nnas últimas 48 horas. Realizou gasometria arterial que evidenciou pH 7,2 (VR: 7,35?7,45), HCO3\n16 mmol/L (VR: 22?26 mmol/L), pCO2 30 mmHg (VR: 35 a 45 mmHg), pO2 40 mmHg (VR: 60?110\nmmHg), SatO2 80%. Considerando o quadro em questão, os exames a solicitar e o tratamento\nmedicamentoso mais apropriados são:","options":{"A":"FAN; pulsoterapia com ciclofosfamida.","B":"PCR para SARS-Cov-2; hidroxicloroquina.","C":"Sorologia para HIV; sulfametoxazol-trimetoprima e prednisona.","D":"FAN; pulsoterapia com metilprednisolona.","E":"Sorologia para HIV; sulfametoxazol-trimetoprima somente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-260006","number":"260006","sourceNumber":"260006","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O tratamento para o HIV vem evoluindo continuamente, e nos últimos anos houve uma\nmudança no olhar sobre a prevenção.\nAtualmente, é possível oferecer mais alternativas ?\ncientificamente eficazes ? em relação à única opção disponível até pouco tempo atrás: o\npreservativo. O Ministério da Saúde elaborou a mandala de Prevenção Combinada que associa\ndiferentes métodos de prevenção ao HIV, às IST e às hepatites virais (ao mesmo tempo ou em\nsequência), conforme as características e o momento de vida de cada pessoa. Dentro da\nPrevenção Combinada recomenda-se:","options":{"A":"A identificação de populações chaves que incluem homens que fazem sexo com homens,\npessoas trans, população de rua, pessoas\nprivadas de liberdade, profissionais do sexo, negros,\njovens e pessoas que fazem uso de álcool e outras drogas.","B":"A PEP ? profilaxia pós-exposição é recomendada em casos de violência sexual ou acidente\npérfuro-cortante, pode ser iniciada até 1\nsemana após a exposição e deve ser mantida por 3 meses\ncontínuos.","C":"A PrEP ? profilaxia pré-exposição, está indicada apenas para casais heterossexuais\nsorodiferentes para o HIV e para profissionais do sexo que tem alto risco de infecção.","D":"O tratamento como prevenção para todos os indivíduos vivendo com HIV, que apresentem a\ncarga viral acima de 10.000 cópias/mm3 ou contagem de linfócito CD4+ < 500 cel/dL."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-277796","number":"277796","sourceNumber":"277796","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Luís Carlos, 6 anos, é portador de doença granulomatosa crônica e deverá fazer,\npreferencialmente, tratamento profilático com as seguintes medicações:","options":{"A":"Cefuroxima; nitrofurantoina; cetoconazol.","B":"Sulfametoxazol/trimetroprim; itraconazol.","C":"Amoxicilina; ciprofloxacina.","D":"Cetoconazol; ciclopirox olamina.","E":"Azitromicina; cefalexina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-277797","number":"277797","sourceNumber":"277797","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Um imunologista avalia um lactente de 6 meses devido a quadro de infecções\nbacterianas de repetição, queda de coto\numbilical no 21° dia de vida e ausência de imagem tímica\nno Rx de tórax. A provável hipótese diagnóstica em questão é","options":{"A":"imunodeficiência celular.","B":"síndrome de Di George.","C":"imunodeficiência humoral.","D":"angioedema hereditário.","E":"imunodeficiência comum variável."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-230902","number":"230902","sourceNumber":"230902","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"O gráfico a seguir representa a história natural da infecção pelo HIV. A partir da\nanálise\ndo gráfico, é possível afirmar que pacientes:","options":{"A":"Na fase ?A?, permanecem assintomáticos apesar da replicação do vírus, e têm menos chance\nde transmissão da doença por via sexual.","B":"Na fase ?C?, apresentam a chamada síndrome retroviral aguda, que acontece quando há a\nqueda significativa dos linfócitos T CD4.","C":"Nas fases ?A? e ?B?, se tratados adequadamente com medidas de supressão viral, podem não\ndesenvolver as doenças oportunistas e evitar a transmissão do vírus.","D":"Na fase ?B? corresponde à fase chamada janela imunológica, onde o organismo ainda\nconsegue combater a replicação viral e número de células T CD4 está normal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-227633","number":"227633","sourceNumber":"227633","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Síndromes clínicas herdadas, com padrão de evolução clínica que se apresenta na\ndependência do grau de comprometimento e do tipo de imunidade alterada, são designadas como\nimunodeficiências primárias. Em relação ao seu quadro clínico, é correto afirmar que:","options":{"A":"pacientes podem apresentar exame de neuroimagem mostrando lesão intracraniana com efeito\nde massa, alterações neurológicas, alteração\ndos níveis de consciência e com IgM positiva para T.\ngondi.","B":"pneumonia recorrente, com vários episódios em um período de 01 ano, sugerem fortemente\ndiagnóstico acima, sendo que o quadro clínico pode, isoladamente e sem necessidade de\ninvestigação complementar, fechar o diagnóstico.","C":"dispneia e tosse não produtivas nos últimos 3 meses, associado a infiltrado intersticial difuso\nbilateral, com ausência de pneumonia bacteriana, aponta, primariamente, para o diagnóstico de\nimunodeficiência primária.","D":"placas eritemato-violáceas na pele ou mucosa sugestivas de lesão de Kaposi são\npatognomônicos de imunodeficiência primária combinada grave.","E":"presença de telangiectasias na conjuntiva e flexura, associada a gengivoestomatite herpética\nrecorrente a manchas \"\"café-au-lait\"\" apontam para o quadro de imunodeficiência primária."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-240526","number":"240526","sourceNumber":"240526","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"J.P.A, sexo masculino, 3 anos e 5 meses, evolui com infecções de repetição: otites,\namigdalites e 5 episódios de pneumonia. Apresentou hemograma normal e níveis de\nimunoglobulinas e subclasses de IgG sem alterações. Não apresentou resposta adequada após\nimunização com vacina antipneumocócica apesar de responder normalmente às outras vacinas. A\nsuspeita clínica mais provável para o caso citado é","options":{"A":"síndrome de Wiskott-Aldrich.","B":"síndrome de Hiper IgM.","C":"deficiência de IgA.","D":"deficiência de anticorpos antipolissacarideos.","E":"imunodeficiência comum variável."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-08-203765","number":"203765","sourceNumber":"203765","collectionBlock":"med:med-clinica-medica-med-clm-08","collectionLabel":"MED · MED CLM 08","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 08","subtopic":"","stem":"Paciente, 28 anos, recebe diagnóstico recente da infecção pelo HIV, e aos exames\niniciais pré-tratamento apresentava: Taxa de Filtração Glomerular (TFG): 100 ml/min; ureia: 40\nmg/dl; HbsAg: negativo; anti-hbs: >100 mUi/ml; anti-Hbc total: negativo; anti-HCV: negativo;\n\nanti-HAV IgG: positivo; AST: 25 U/L; ALT: 30 U/L; glicose jejum: 80 mg/dl; VDRL: não reator. Na\nconsulta médica, foi-lhe prescrita a Terapia Antirretroviral (TARV) com tenofovir 300 mg +\nlamivudina 300 mg + efavirenz 600 mg. Segundo o Protocolo Clínico e Diretrizes Terapêuticas para\ntratamento da infecção pelo HIV em adultos e suas atualizações com as notas técnicas editados\npelo Ministério da Saúde, analise as assertivas abaixo. I. O esquema antirretroviral prescrito é\nalternativo, e deve ser utilizado em pessoa vivendo com HIV/Aids PVHA) coinfectadas por qualquer\nforma de tuberculose e independente da contagem de linfócitos T CD4+. II. Devido à possibilidade\nde mutações virais que possam conferir resistência aos inibidores da transcriptase reversa não\nnucleosídeos, estaria indicada a realização de genotipagem do HIV-1 pré-tratamento no caso\nacima. III. O esquema antirretroviral prescrito é preferencial para todas as mulheres vivendo com\nHIV (MVHIV). IV. O esquema preferencial vigente no Brasil é a associação de tenofovir 300 mg +\nlamivudina 300 mg + dolutegravir 50 mg. O esquema prescrito para o caso em questão não\napresenta inferioridade quanto à supressão viral em 24 semanas ao ser comparado aos esquemas\ncom inibidores de integrase. Entretanto, está associado a maior risco de suicídio. V. O esquema\nantirretroviral prescrito pode ser utilizado em MVHIV grávidas, entretanto, se essas forem\napresentadoras tardias (início de TARV após 28 semanas de gestação), está recomendada a\nutilização de raltegravir. Estão corretas:","options":{"A":"II, III, IV e V, apenas.","B":"I, II e IV, apenas.","C":"I, III e V, apenas.","D":"II, IV e V, apenas.","E":"I, II, III, IV e V."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 08/MED CLM 08.txt","sourceLabel":"MED · MED CLM 08","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 08","MED"],"answerSource":"explicit","commentDeferred":true}]};
